INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592965481', 'Bermuda Compressão Feminina HUPI Run Longa Canguru', 'Bermuda Compressão Feminina HUPI Run Longa Canguru A Bermuda de Compressão para Corrida de Longa Distância, uma peça projetada especialmente para atender às necessidades dos corredores de resistência. Com um design inovador, tecido premium e uma gama de recursos desenvolvidos para aprimorar sua experiência de corrida, esta bermuda é o parceiro ideal para desafios mais extensos. Descubra a Bermuda de Compressão para Corrida de Longa Distância, uma peça criada para atender às exigências dos corredores de resistência. Com características de alto desempenho, esta bermuda oferece: Composição Premium: Feita com um tecido avançado de 78% poliamida e 22% elastano, proporcionando compressão adequada, suporte muscular e elasticidade para acompanhar seus passos durante corridas longas. Proteção UV50+ e Tecido Opaque: Além de suporte físico, a bermuda protege sua pele dos raios UV com classificação UV50+. O tecido não é transparente, garantindo cobertura total e conforto. Medidas Estratégicas: Com altura de 37 cm, cobre da cintura até o final das pernas, oferecendo suporte e compressão adequados. O comprimento do meio das pernas ao final é de 40,5 cm para cobertura total durante corridas longas. Cós Largo e Confortável: Com 7 cm de largura, o cós largo proporciona suporte adicional à região abdominal, mantendo a bermuda no lugar sem desconforto. Seis Bolsos Inteligentes: Possui seis bolsos estrategicamente posicionados para transportar itens essenciais como barras de cereais, garrafinhas dobráveis para hidratação (modelo Soft Flash HUPI de 250 ml, 350 ml e 500 ml), chaves e outros acessórios.', 306.16, 229.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-lualij8ey9692c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F23592965481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494466217', 'Multimídia Honda Hrv 2015 A 2021 2+64gb 9 Polegadas Android Sem Fio', 'Central Multimídia Android SOAUDIO 9 Polegadas – Modelo S964B Sobre Nós Desde 2007, somos especialistas em centrais multimídia automotivas, oferecendo produtos modernos, confiáveis e com o melhor custo-benefício. Diferenciais: • Garantia de 12 meses • Suporte técnico especializado • Atendimento rápido e personalizado • Produto de altíssima qualidade, testado e garantido. Especificações Técnicas • Tela: IPS 9” 1280x720dpi (toque capacitivo duplo vidro) • Android: 15.0 • Memória: 2GB RAM / 64GB Flash • Processador: Quad Core RK3326 1.5GHz • Bluetooth: 5.0 (50 Mbps) • Wi-Fi: Dual Band 2.4G / 5.0G • Som: 4x41W com DSP e Sub EQ • Compatível com: CarPlay e Android Auto sem fio Aplicativos Instalados GPS IGO 3D offline, Waze, Netflix, Spotify, YouTube, Google Maps, Chrome e Play Store. Funções Principais • Interface personalizável: opções de layout • Logo da montadora ajustável • Câmeras compatíveis: 480p e 720p • Multitela: Divisão de tela para múltiplos apps • Bluetooth Hands-Free: Ligações e música • Ajuste de iluminação automática • Reprodução multimídia: MP3, MP4, AVI, MKV e mais • Rádio FM: Frequência 76–108 MHz • Wi-Fi com antena integrada Conteúdo da Embalagem • Central Multimídia 9” • Moldura do painel • Chicote plug and play • Canbus • Câmera de ré + cabo • Antena GPS • Cabos USB e RCA • Microfone Bluetooth Suporte técnico pós-venda incluso.', 1178.38, 1036.98, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820lk-mqc7inm86ygw97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1613233738%2F22494466217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
