INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27776622853', 'Livro Comfy Vibes', 'Inspirado no sucesso dos livros de colorir PARA RELAXAR no TikTok, este livro é ideal para quem busca transformar momentos simples em uma experiência verdadeiramente calmante. Explore sua criatividade com lápis de cor ou marcadores, mergulhando em momentos de tranquilidade. Perfeito para todas as idades, este livro oferece uma maneira leve e prazerosa de aliviar o estresse e de se desconectar da correria diária. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Jeferson Silva_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.50_x000D_ ISBN: 9786526122198_x000D_ Coleção: Comfy & cozy books_x000D_ Linha Editorial: Ciranda Cultural - Lab_x000D_ Faixa Etária: Sem definição_x000D_ Assuntos (tags): Colorir, Atividades, Relaxar_x000D_ BISAC: Jogos & Atividades / Livros de Colorir_x000D_ Linha de Produto: Comfy & cozy books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Verniz UV localizado_x000D_ Material: Papel', 24.9, 11.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rccc-m6egpqs0pkey71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F27776622853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21110470172', 'Coletor Admissao Honda Cbx 200 Strada Nx 200 Xr 200', 'COLETOR DE ADMISSAO CODIGO: 3520 APLICACAO: HONDA CBX 200 STRADA. COLETOR DE ADMISSAO, PRODUTO DE EXCELENTE QUALIDADE IDENTICO AOS ORIGINAIS HONDA, POSSUI ENCAIXE PERFEITO EM SUA MOTO. MAIS DETALHES DO COLETOR DE ADMISSAO: - PRODUZIDA EM ALUMINIO E BORRACHA DE ALTA QUALIDADE E RESISTENCIA; - MAIOR CUSTO BENEFICIO DO MERCADO; - FACIL DE INSTALAR; O COLETOR DE ADMISSAO DA BROS 150 PODE SER USADO EM TODAS AS CATEGORIAS COMO: MOTOCROSS, ENDURO, TRILHA, CROSS COUNTRY, VELOCROSS, ETC... """""!!!!!!!!!! IMAGENS MERAMENTE ILUSTRATIVAS !!!!!!!!!!""""" """""!!!!!!!!!! TIRE SUAS DUVIDAS ANTES DA COMPRA !!!!!!!!!!"""""', 35.99, 35.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/ce6499e703931102e461a83acd6cef22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346208010%2F21110470172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697117938', 'Caixa Cooler Térmico Vermelho 32 Litros Cabe Latas Praia Pesca Termolar Orginal', 'Caixa Térmica SUV 32L Vermelha Termolar A Caixa Térmica SUV 32L é segura, útil e versátil. Com design inovador, possui acesso rápido por exclusiva abertura deslizante com estojo para guardar seus pertences, apresenta conservação térmica diferenciada através do Sistema Air Flow, que permite a circulação de ar pela base, assim trazendo uma melhor performance na conservação térmica: até 24 horas para bebidas e 12 horas para alimento (com o uso de gelo 20%). Sua alça é reforçada e mais resistente proporcionando segurança para o transporte individual, e maior ergonomia através de angulações nos cantos, para o transporte em dupla. A tampa contém pegas superiores e inferiores que possibilitam a abertura com apenas uma mão, além de ser reversível, com passa tempos no verso. Já na sua base, possuem pegas que facilitam a retirada do líquido, ou gelo. Outro diferencial está nas pequenas alças laterais, que possibilitam prender sacolas ou cordas elásticas. Um produto com a qualidade e garantia Termolar. Abertura deslizante Acesso rápido Alça mais resistente Pegas laterais salientes Tampa reversível Comporta: 45 latas de 350ml ou 35 latas de 473ml ou 6 garrafas PET de 2L. Informações Técnicas: Referencia: 2031 Código: 3502VRO Marca: Termolar Capacidade: 32 Litros. Comporta: 45 latas de 350ml ou 35 latas de 473ml ou 6 garrafas PET de 2L. Conservação Térmica: 12 Horas sem Gelo / 24 Horas com Gelo Isolamento Térmico: Poliestireno Expandido (EPS) Material Externo: Plástico Sistema de Servir: ------ Medidas Aproximadas do Produto: - Altura: 39 cm - Largura: 32,1 cm - Comprimento: 52,7 cm', 159.99, 147.35, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-lnvqd0t5gwjs5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F23697117938', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8470271500', 'Livro - A volta de Sherlock Holmes - Capa comum - Principis', 'A volta de Sherlock Holmes é uma coleção de histórias do detetive mais conhecido do mundo, originalmente publicadas entre 1903-1904, por Arthur Conan Doyle. Dado como morto havia três anos, Sherlock Holmes retorna triunfante para seu querido companheiro Dr. Watson. E não antes da hora! Londres nunca precisou tanto de seus serviços extraordinários: um assassino com uma arma de ar comprimido espreita a cidade. Entre outras treze brilhantes histórias de mistério, detecção e dedução, Sherlock Holmes investiga o problema do construtor de Norwood, decifra a mensagem dos dançarinos e desvenda o caso dos seis Napoleões Editora: Principis Edição: 1, 2021 Autor: Arthur Conan Doyle Idioma: Português Páginas: 352 Dimensões: L 15.50 x A 22.60 x E 2.00 ISBN: 9786555524376', 34.9, 34.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/21f88928451c01a5a3e4de64f88a68d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8470271500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
