INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497417899', 'Livro Aquarela Animais de estimação', 'Em uma casa no campo, moravam três animais de estimação: O cãozinho Toby, a gata Mima e a jabuti Fifi. Certo dia, eles receberam uma inesperada visita. Embarque nessa incrível história e divirta-se pintando as ilustrações com as aquarelas que acompanham este livro!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2023_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 16_x000D_ Dimensões: L 27.00 x A 28.00 x E 0.61_x000D_ ISBN: 9786526102671_x000D_ Coleção: Livro com aquarela_x000D_ Linha Editorial: Ciranda Cultural - Livro-brinquedo_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Colorir, Atividades, Animais de estimação , Diversão, Aprendizado, Pintar_x000D_ BISAC: Jogos & Atividades / Livros de Colorir_x000D_ Linha de Produto: Aquarela_x000D_ Encadernação: Grampeado_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbkb-lmdkg7pci9s570', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F18497417899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
