INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198736865', 'Cera Nutritiva Granado Unhas e Cutículas Pink 7g', 'A Cera Nutritiva Granado Pink para Unhas e Cutículas 7g hidrata profundamente, fortalece as unhas e suaviza as cutículas. Enriquecida com vitamina E e óleos vegetais, sua fórmula não oleosa é ideal para uso diário, promovendo unhas mais saudáveis e bonitas.', 37.02, 37.02, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-mci65o7c5xvb71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547988074%2F23198736865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
