INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297325434', 'Moldura Som Dvd 2din Multimídia Gol G5 Preta Moldura Botões', 'Moldura do Painel 2 Din Gol Voyage Saveiro G5 2009 a 2013 Preto Padrão Japonês e Chinês A moldura é um acessórios que vem sendo cada vez mais procurados pelos motoristas e passageiros. Pode ser utilizada com centrais multimídia, Dvd players 2 Din, sem se preocupar com o tamanho do seu aparelho, pois possui o padrão Japonês e Chinês. Fabricada em ABS, acompanha moldura intermediária e suportes laterais para fixação. Acabamento impecável na cor Preto, com encaixe perfeito e sob medida para o painel do seu carro, mantendo a originalidade e beleza após a instalação de um Multimídia ou um DVD automotivo. Compatível com: - Gol G5 2009 a 2013 - Voyage G5 2009 a 2013 - Saveiro G5 2009 a 2013 Especificação Técnica: - Encaixe Sob Medida - Cor Preta com Textura Fosca - Produzido em ABS Injetado Resistente - Acabamento Impecável - Disponível no Modelo 2 Din - Fácil Instalação - Acompanha Aro de Acabamento e Suportes de Instalação do Player - Medidas da Moldura (LxAxP): 26,5 x 23 x 8cm - Medidas da Abertura Sem Aro de Acabamento (LxA): 18,4 x 9,8 cm - Medidas da Abertura Com Aro de Acabamento (LxA): 17,2 x 9,5 cm Conteúdo da Embalagem: - 1 Moldura de Painel - 1 Aro de Acabamento - Suportes para Instalação do Player Importante: - Valor do Kit. - Imagens Meramente Ilustrativas. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 47.69, 47.69, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2s4s1pmmm8j0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F23297325434', NULL, NULL, '2026-07-28T02:11:31