INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994659034', 'Processador Compacto Philco PH900V Turbo 220V', 'Processador Compacto Philco PH900V Turbo 220VO Processador Compacto Philco PH900V Turbo possui 250W, potência que te leva muito além na hora de preparar deliciosas receitas! Com duplo sentido de rotação, que processa todos os tipos de frutas, vegetais, queijos, carne, grãos, coco, torradas, cebola, alho e outros alimentos. Acompanha acessórios, que inclusive podem ser lavados na lava-louça. Compacto com a medida certa, pois oferece capacidade para 500ml e design vertical, ocupando menos espaço na sua cozinha. Sabor e praticidade, juntos em um único produto, juntos no Processador Compacto Philco PH900V! Principais Características Potência: 250W Design vertical: ocupa menos espaço na cozinha Todos os acessórios podem ser levados a lava-louças Pés antiderrapantes Funções: processar, cortar, misturar, picar, triturar. Observação: Somente faturamos para o nosso consumidor final, ou seja, não faturamos pedidos para CNPJ por este portal de vendas; Especificações Técnicas Marca: Philco Modelo: PH900V Estado: Garantia: 360 Dias', 119.9, 119.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-821g2-mgi5wle71w5k7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F22994659034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993832890', 'Prensa Sublimadora Transfer Térmica Cilíndrica Canecas Squeezes Copos 127v ou 220v', 'Prensa Térmica Sublimação Caneca Importway 110v A Prensa Térmica para canecas é uma excelente opção para quem quer trabalhar com sublimação de diversos materiais cilíndricos. Prensa de fácil manuseio com funções como alarme sonoro e programação de tempo e temperatura, que te ajudarão a maximizar sua produção. Indicada para confecção de brindes para eventos ou presentes em datas comemorativas. Compacta, de fácil manuseio e muito leve proporciona trabalhos incríveis de alta qualidade. Poderá utilizar em evento de todos os tipos casamentos, festa infantis, buffet em geral, feiras e negócios, em lojas. Especificações Técnicas: - Marca: Importway - Modelo: IWPTSC-110 - Voltagem: 110V - Potência: 350w - Cor: Preta - Peso: 6,5kg - Intervalo de Tempo (Temperatura): 0 - 999 segundos - Faixa de Temperatura: 0 - 250ºC - Tamanho da Transferência: 11 Oz - Faz garrafa squeeze - Painel de controle Características: - Aviso sonoro de finalização da transferência - Versátil, estampa diversos produtos Conteúdo da embalagem: - Prensa Térmica Sublimação Caneca Importway 110V - Manual de Instruções "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 616.13, 616.13, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj5ki6nfe0areb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242218284%2F23993832890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299835900', 'Mochila Esportiva Unissex com Compartimento para Notebook Braze OIWB221802 - Olympikus', 'Mochila Esportiva Unissex com Compartimento para Notebook Braze - Olympikus Prática, resistente e com visual moderno, a Mochila Braze da Olympikus é ideal para acompanhar a rotina esportiva, acadêmica ou urbana. Desenvolvida em tecido 100% poliéster, ela garante leveza e alta durabilidade mesmo com o uso frequente, além de possuir ótimo acabamento e organização inteligente para o dia a dia. Seu design funcional oferece dois compartimentos principais espaçosos, sendo o maior com divisória especial para notebook, protegendo seu equipamento com segurança e praticidade. Na parte frontal, o bolso com zíper em hotmelt tape facilita o acesso rápido a objetos essenciais, mantendo tudo bem organizado. Para maior conforto no transporte, conta com alças acolchoadas com regulagem, adaptando-se ao corpo com firmeza. O puxador emborrachado com logo Olympikus em alto relevo, além de estiloso, permite manuseio fácil. Destaque também para os bolsos laterais em mesh, ideais para garrafas de água ou acessórios de uso rápido. Com capacidade de 16 litros, essa mochila oferece o equilíbrio ideal entre tamanho compacto e espaço interno, sendo uma excelente escolha para quem busca versatilidade e resistência em qualquer ocasião. Especificações Marca: Olympikus Modelo: Mochila Braze Material: 100% poliéster Capacidade: 16L Compartimentos: 2 principais com divisória para notebook Bolso frontal: Com zíper hotmelt tape Puxador: Emborrachado com logo em alto relevo Bolsos laterais: Em mesh para garrafas ou pequenos itens Alças: Reguláveis e acolchoadas Alça de mão: Sim', 159.9, 109.9, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbwftxx8263d1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1314243679%2F20299835900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
