INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53007630426', 'Carimbo Autotintado Decorado Harry Potter - Blister c/ 6 Und. Leo&Leo Leonora - 92099', 'Olha só quem vai decorar anotações, carimbar agendas e cadernos: Carimbo Autotintado Decorado Harry Potter – Blister c/ 6 Un Leo&Leo. É ideal para uso em papel, deixando tudo mais divertido. Ele possui reservatório interno de tinta e encaixe para lápis, sendo um diferencial bem interessante e prático. Com o carimbo a criança tem sua coordenação motora estimulada, segurando com a mãozinha a peça e apertando no papel, sem contar que ajuda também a soltar a imaginação. São 6 cores variadas e 6 estampas diferentes, uma mais legal que a outra, com os personagens e ícones do Harry Potter e com a cor do corpo do carimbo autotintado na cor da tinta. Recomendado para crianças a partir de 4 anos, o Carimbo Autotintado Decorado Harry Potter – Blister c/ 6 Un Leo&Leo é atóxico e possui certificado. Composição: Carimbo: Resina termoplástica Tinta: ácido linoleico, glicerol, pigmento e água Indicação de uso: Atenção! Não recomendável para crianças menores de 4 anos por conter parte(s) pequena(s) que pode(m) ser engolida(s) ou aspirada(s). Dimensões: 2,5cm x 2,5cm x 3,5cm Características: - Marca: Leo&Leo Leonora -Modelo: 92099 *Imagens meramente ilustrativas* Conteúdo da embalagem: - 01 Blister com 6 Unidades de Carimbo Autotintado Decorado Harry Potter', 22.48, 20.23, NULL, 'Stationery > Others', 'https://cf.shopee.com.br/file/sg-11134201-82609-mm7h5z0b6iv7f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F53007630426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
