INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20831092550', 'Colar Bamoer Pingente De Corrente De Clavícula Dos Olhos Do Diabo Prata 925 Para Mulheres Meninas Joias Acessórios', 'Bem-vindo à Loja Oficial Bamoer! Imformação do Produto •Material: Prata 925 • Peso: 1,9g • Comprimento: 42 cm (ajustável), tamanho dos pingentes: 1,6 * 1,4 cm • Origem: China •Função: Pulseira &amp; Colar DIY; Presentes, Lembranças, Coleção, Acessórios de moda Instruções de armazenamento •Não Deixe o produto entrar em contato com cosméticos e produtos químicos •Limpe O produto regularmente com creme dental diluído ou líquido de lavar louça e depois enxágue com água e seque. • Armazenar em uma caixa ou uma bolsa quando não estiver em uso Observação • Evite golpes pesados, fogo e produtos químicos corrosivos • O produto é seguro para a pele usar. •Devido À diferença na exibição do terminal, pode haver ligeira diferença de cor entre a imagem do produto e o produto real. • Estoque 100% pronto • Novo e de alta qualidade Obrigado por escolher a Loja Oficial Bamoer!', 136.99, 85.99, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/a2e50cd51802da704965212c8c126dea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325735487%2F20831092550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
