INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498342338', 'Bolsa Feminina Chenson Original Matelassê Cute Ombro 3484982', 'Bolsa Feminina Chenson Original Matelassê Cute Ombro 3484982 Bolsa Feminina Chenson Original Matelassê Cute Ombro 3484982 Confeccionada em PU, material de excelente qualidade, essa linda bolsa possui amplo espaço com compartimento para pequenos objetos. O forro em tecido personalizado com logo Chenson garante sofisticação. O fechamento principal é feito com zíper personalizado, e a alça em PU no modelo ombro oferece conforto e praticidade. O acabamento com costura contrastante e o chaveiro porta-níquel adicionam um toque refinado, com detalhes das ferragens em dourado. Medidas Aproximadas: Altura: 14 cm Largura: 7 cm Comprimento: 23 cm Cuidados: Guarde em um local seco e arejado, evitando locais úmidos. Evite colocar excesso de peso no produto para não forçar os zíperes e costuras. Proteja os objetos cortantes e/ou pontiagudos, evitando o contato direto com o produto. Evite altas temperaturas. Cores claras podem manchar ao entrar em contato com objetos ou roupas de cores pigmentadas. Dicas de Limpeza: Para a limpeza, utilize apenas pano úmido com sabão neutro. Não mergulhe na água e não utilize componentes químicos, solventes ou alvejantes. Não deixe de molho e seque à sombra.', 310.92, 310.92, NULL, 'Women Bags > Top-handle Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rd3x-m7movxdes6c4c4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F22498342338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998088232', 'Focus 240ml Vonixx Removedor de Manchas para Vidros Automotivos, Espelhos e Box', '>>>>>>REMOVEDOR DE MARCAS D''ÁGUA EM VIDROS E ESPELHOS FOCUS 240ml VONIXX<<<<<< Especificações Técnicas: - Remoção de imperfeições - Acabamento brilhante - Ph equilibrado - Total segurança Conteúdo da Embalagem: - 01 Removedor de Marcas D''Água em Vidros; Focus 240ml Vonixx; Aplicações - Indicado para revitalização de vidros automotivos, para-brisas, vidros laterais, vidros traseiros, lanternas, espelhos, box de banheiro ou qualquer tipo de vidro. Modo de Uso 1 - Agite bem o produto antes de usar. 2 - Coloque algumas gotas do produto em um aplicador específico para esse fim e comece a esfregar, aplicando pressão em uma área de aproximadamente 30cm x 30cm. 3 - Remova o excesso de produto com água ou uma toalha de microfibra. 4 - Verifique se as marcas foram completamente removidas e caso contrário, repita o procedimento. 5 - Continue o processo até concluir toda a superfície. Por que comprar com a LSA – Loja do Som e Acessórios? - Especialistas em som automotivo: anos de experiência no segmento e conhecimento técnico para oferecer os melhores produtos - Produtos originais e testados: trabalhamos apenas com marcas reconhecidas e garantia de procedência - Envio rápido e seguro: logística 100% integrada com os marketplaces, garantindo rastreamento e entrega confiável em todo o Brasil - Atendimento especializado: suporte rápido via chat das plataformas, ajudando a escolher o produto certo para sua necessidade - Pós-venda ativo: acompanhamento após a compra para garantir sua satisfação - Variedade e atualização constante: catálogo completo de alto-falantes, módulos, players e acessórios automotivos', 59.9, 58.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-mdkopl5nt89lf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800059202%2F21998088232', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
