INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41808854231', 'Suporte Celular Para Veiculo Automotivo 360° Ajustável Porta Copos Garrafa LE-134', 'Suporte Automotivo LE-134 com Porta Copos e Garrafas – Praticidade e Segurança em Cada Viagem! Transforme sua experiência ao dirigir com o Suporte Automotivo LE-134! Com design funcional e versátil, ele garante praticidade no uso do celular para navegação, chamadas ou entretenimento, enquanto mantém sua bebida sempre ao alcance. Ideal para carros, seu sistema de ajuste 360° permite encontrar o ângulo perfeito com total estabilidade. ✓ Ajuste 360° para visualização personalizada ✓ Compatível com veículos ✓ Base firme e segura para celular ✓ Porta garrafas integrado – ideal para longas viagens ✓ Instalação simples e rápida Especificações Técnicas: - Modelo: LE-134 - Ajuste de ângulo: 360° - Compatibilidade: Veículos - Função extra: Porta garrafas integrado - Estrutura estável e resistente Conteúdo da Embalagem: 1x Suporte Automotivo LE-134 com Porta Copos', 76.9, 60.3, NULL, 'Mobile & Gadgets > Accessories > Phone Grips', 'https://cf.shopee.com.br/file/sg-11134201-82618-mkdyjohe9ybq45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F41808854231', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
