INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200685351', 'X-carnitine - 480ml Yellow Fruits - Under Labz', 'O único queimador de gordura do Brasil com tecnologia exclusiva LIPO-DRIVE.QUEIME GORDURA COMO FONTE DE ENERGIA, ACELERE SUA PERDA DE PESO E CONTROLE SUA FOME Como Tomar Agite bem o frasco, remova a tampa e coloque o batoque na boca do frasco. Conecte a seringa, incline o frasco e puxe o líquido com a seringa até a marca de 10mL. Tomar uma dose 10 minutos antes do treino ou conforme orientação profissional. Ingredientes Ingredientes: ÁGua purificada, tartarato de L-carnitina, picolinato de cromo, conservante benzoato de sódio e sorbato de potássio, estabilizante goma xantana, aromatizante idêntico ao natural, edulcorante sucralose e acessulfame de potássio, corante amarelo tartrazina. NÃO CONTÉM GLÚTEN. ALÉRGICOS: PODE CONTER DERIVADOS DE LEITE E OVO. ...', 120.62, 120.62, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-821e1-mh6fovi5hfyg1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F58200685351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
