INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893985152', 'Colchão Queen Guldi Massageador Quântico Molas Ensacadas (30x158x198) Branco e Bege', 'Que tal o Colchão Guldi Massageador Quântico? Com características perfeitas para promover relaxamento, o Colchão Guldi Massageador Quântico é a escolha certa para seu ambiente de descanso. Enquanto tem estrutura em molas ensacadas individualmente, que dão boa sustentação ao corpo, ele também conta com camada de espuma D33, que oferece maciez e conforto para você descansar depois de um dia corrido. O ponto extra de bem-estar fica por conta das cápsulas massageadoras localizadas em pontos estratégicos e ativadas por controle remoto, assim cada ponto do seu corpo receberá a atenção especial. Daí é só adquirir uma boa base box e um travesseiro - se preferir, eles podem ser também da linha Guldi. Ah, esse modelo é embalado à vácuo, tecnologia que facilita o transporte até chegar em sua casa.', 2964.99, 2315.56, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-824gv-me7mzclf7xfm38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1494838355%2F22893985152', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
