INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498187134', 'Beliche Robusto C/ 2 Colchões Confortáveis - Kit Completo Nature', 'Beliche Robusto C/ 2 Colchões Confortáveis - Kit Completo Nature Beliche Jaspe Completa – Conforto e Praticidade para Seu Quarto Atenção: - Entrega apenas em áreas urbanas. - Não realizamos montagem (kit desmontado). - Limite de 1 unidade por pedido. Destaques do Produto: - 2 Colchões D33 – Espuma de alta densidade para máximo conforto e durabilidade. - Estrutura Reforçada – Suporta até 100 kg por cama, ideal para adultos e crianças. - Transformável em 2 Camas – Versátil e adaptável ao seu espaço. - Madeira Resistente – Ripas e travessas reforçadas para maior estabilidade. - Pés Antiumidade – Proteção extra para maior durabilidade. Montagem: Fácil instalação com manual ilustrado incluso. Perfeito para: - Quartos infantis - Acomodar visitas - Otimizar espaços pequenos. Garanta já o seu beliche Jaspe e aproveite noites de sono tranquilas! Beliche Jaspe Completa – Conforto e Praticidade para Seu Quarto Atenção: - Entrega apenas em áreas urbanas. - Não realizamos montagem (kit desmontado). - Limite de 1 unidade por pedido. Destaques do Produto: - 2 Colchões D33 – Espuma de alta densidade para máximo conforto e durabilidade. - Estrutura Reforçada – Suporta até 100 kg por cama, ideal para adultos e crianças. - Transformável em 2 Camas – Versátil e adaptável ao seu espaço. - Madeira Resistente – Ripas e travessas reforçadas para maior estabilidade. - Pés Antiumidade – Proteção extra para maior durabilidade. Montagem: Fácil instalação com manual ilustrado incluso. Perfeito para: - Quartos infantis - Acomodar visitas - Otimizar espaços pequenos. Garanta já o seu beliche Jaspe e aproveite noites de sono tranquilas!', 1407.0, 1407.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf