INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699216104', 'Pastilha Freio Dianteira CG 160 Fan 2016 2017 2018 2019 2020 2021 2022 2023 CBS Semi-Metálica', 'Pastilha de Freio Dianteira Honda CG 160 Fan 2016 2017 2018 2019 2020 2021 2022 2023 CBS Semi-Metálica Características: - Produto novo de ótima qualidade; - Alta resistência e durabilidade; - Feito sob medida, encaixe perfeito. Especificações técnicas: - Sem amianto; - Suporta altas temperaturas; - Fabricado em semi-metal resistente. Compatível com os modelos: - CG 160 Fan 2016 a 2023; - CG 160 Titan 2018 a 2023. Obs: valor anunciado referente ao PAR. Atenção: Compatível para CG 160 Fan CBS. Garantia: 90 dias. Conteúdo da embalagem: - 02 Pastilhas de freio. Dica: - Dê um novo visual para a sua moto, aqui você encontra os melhores produtos com os melhores preços. Importante: - Não somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 90.9, 81.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lsudytra2ziw43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F18699216104', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
