INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299298172', 'LANTERNA TRAS - BIZ 125 2011 2017 BIZ 100 2013 VERMELHA', 'Fundada em 1995, a VALPLAS iniciou suas atividades produzindo Piscas para motocicletas que desde o princípio se diferenciam por sua qualidade.Com o passar dos anos, novos produtos foram sendo agregados e assim nasceu a Linha Valplas de Piscas, Lentes e Lanternas.Investimentos em tecnologias e em recursos humanos no decorrer destes 22 anos, resultaram em um crescimento no segmento de Motocicletas, que levou a uma reestruturação desta área e a mudança para um espaço ainda maior em Bragança Paulista, a 100 km de SP, onde hoje é a sede da VALPLAS, com uma área de aproximadamente 10.000 metros.LANTERNA TRAS - BIZ 125 11/17 / BIZ 100 13 LENTE VERMELHA', 95.68, 95.68, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rd4c-lwncxicvbv55e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F20299298172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199284384', 'Kit 4 Cubitan Baunilha Pb 200ml', 'Kit com 4 unidades Cubitan Baunilha 200ml O Cubitan é um suplemento oral hiperproteico com nutrientes que contribuem no processo de cicatrização de feridas, como o aminoácido arginina; minerais como zinco, selênio, ferro, e cobre; vitaminas C, A eE; e um exclusivo mix decarotenóides. Esses nutrientes contribuem especialmente na cicatrização das lesões por pressão, também chamadas de úlceras por pressão ou escaras. São feridas que surgem na pele de pessoas que ficam muito tempo na mesma posição, sendo uma consequência comum de longas internações hospitalares. Cubitan já vem pronto para beber e está disponível em três sabores: baunilha, chocolate e morango.', 140.16, 105.9, NULL, 'Health > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvp-mig19neaic5f5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1685471497%2F22199284384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
