INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797627137', 'Lavadora De Alta Pressão 1400w Lav 1600 Vonder 127v', 'Seja bem-vindo a Inter Level Brasil. A Loja de ferramentas e acessórios mais completa do mercado. ATENÇÃO PRODUTO EM 127V ***Lavadora De Alta Pressão Potente 1400w Lav1600 Vonder 127v*** Conta com sistema que gera mais pressão e libera menos água, tornando-a mais eficiente e diminuindo desperdícios. Em média, uma torneira aberta consome 1.800 litros de água por hora. Com o uso da Lavadora de Alta Pressão LAV 1600 esse consumo cai para 306 litros por hora, promovendo grande economia de água. Possui alça e rodas para transporte, suportes para armazenar a pistola e o cabo elétrico. Bico da lança ajustável, com jato leque ou concentrado e acompanha ainda acessório para detergente e com sistema stop total que proporciona maior praticidade e economia de água e energia, desligando o motor toda vez que o gatilho é liberado. Pistões da bomba em aço inox, garantindo maior resistência e durabilidade. Uso doméstico. Indicada para limpezas em geral, com maior remoção de sujeira, devido a alta pressão de saída da água. Ideal para os mais diversos usos, como na limpeza de pisos, carros, motos, bicicletas, muros e muito mais! Basta regular a saída de água no bico, alternando entre jato leque e concentrado para obter a máxima eficiência na limpeza. Acompanha: 01 Acessório para detergente 01 Mangueira de alta pressão com 5 m 01 Lança com bico ajustável 01 Pistola com gatilho 01 Conector engate rápido de 1/2" com filtro interno lavável.', 429.0, 389.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxingqxv6oxr62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1042011939%2F23797627137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
