INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994196850', 'Vagisil Prevent Plus Sabonete Íntimo 200G Grátis 100G', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Vagisil Sabonete Íntimo foi especialmente formulado e testado por ginecologistas para a higiene íntima diária da parte mais delicada do corpo da mulher, além de proporcionar conforto e bem-estar. No mundo inteiro as mulheres escolheram a linha mais completa para cuidados íntimos femininos, Vagisil. Modo de Usar: Aplique uma pequena quantidade de Vagisil Sabonete Íntimo sobre a palma da mão e lave a região genital externa. Enxágue abundantemente e seque como de costume.', 29.47, 29.47, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-mbqyy6xzw9q12c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22994196850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
