INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098212501', 'Vou te receitar outro gato', 'Sequência de Vou te receitar um gato traz novas histórias divertidas e emocionantes sobre clínica que oferece gatinhos como cura para todos os problemasÀs vezes, tudo que queremos é que nossos problemas se resolvam num passe de mágica. Na falta disso, porém, um gatinho (ou vários) vem bem a calhar: Basta uma visita à Clínica Kokoro, onde os pacientes recebem um tipo de remédio que com certeza não se encontra em qualquer farmácia — gatos! — E, quando voltam para casa, veem sua vida se transformar para sempre.Embora nem todo mundo encontre a misteriosa clínica e ninguém saiba dizer exatamente quem a indicou, aqueles que precisam de verdade conseguem achar o estabelecimento. Ao entrarem na salinha, eles são recebidos pela enfermeira Chitose e pelo dr. Nike e convidados a compartilhar um pouco de suas dificuldades: Uma jovem estudante reluta em admitir que está passando por um momento complicado no namoro um septuagenário enlutado se vê cada vez mais recluso dois amigos não sabem como expressar suas angústias para os familiares e um tutor preocupado mergulha no trabalho para não ter que enfrentar seu pior medo.Entre conversas enigmáticas e trocas de farpas entre o médico e a enfermeira, fica cada vez mais claro que aquelas duas figuras intrigantes escondem algum segredo, mas, curiosamente, o estranho tratamento funciona. Aos poucos, após passarem um tempo com os gatos, os pacientes desenvolvem uma percepção melhor de como lidar com o que sentem, vivem novas experiências e descobrem que algumas conexões são muito mais fortes do que imaginam.', 44.9, 44.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rbna-m64h9hc4ye6m2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22098212501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
