INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261425074', 'Par Farol Celta Prisma 2007 2008 2009 2010 A 2012 Cromado', 'Par Farol Celta Prisma 2007 2008 2009 2010 A 2012 Cromado Descrição do Produto Dê um novo destaque ao seu veículo com este farol cromado de foco simples, desenvolvido com encaixe preciso e acabamento impecável. Produzido com materiais de alta durabilidade, ele oferece iluminação eficiente e visual moderno, garantindo mais segurança e estilo nas suas viagens. Características Principais Produto novo de excelente qualidade. Fabricado em material altamente resistente. Carcaça em plástico preto e lente em acrílico de alta resistência. Design cromado que valoriza o visual do carro e proporciona brilho duradouro. Especificações Técnicas Foco simples com regulagem manual para direcionar a luz conforme sua necessidade. Encaixe de lâmpada H4 nas luzes baixa e alta. Compatível com lâmpadas até 55W e sistema Xênon. Não acompanha lâmpadas. Compatibilidade Projetado para encaixe perfeito nos seguintes modelos: Celta / Prisma 2007 a 2012 Importante !!!! Recomendamos que a instalação seja feita por um profissional especializado. Não nos responsabilizamos por instalação incorreta. Por que escolher este farol? Este é o produto ideal para quem busca qualidade, durabilidade e design original. Melhore sua visibilidade noturna, incremente o visual do seu carro e garanta um resultado profissional na substituição do farol. Aproveite — estoque limitado e alta demanda entre proprietários exigentes.', 593.0, 593.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-823p8-mopse7a8udj6b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226818547%2F58261425074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
