INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198101314', 'Pulverizador Manual Orange 2Lt - Sigma Tools', 'PULVERIZADOR MANUAL ORANGE 2L APLICAÇÕES Pulverização de líquidos não corrosivos em aplicações automotivas, jardinagem e outros usos profissionais e hobbistas. CARACTERÍSTICAS • Reservatório de 2L (maior autonomia); • Bico com ajuste de vazão; • Possui trava no gatilho para maior conforto na aplicação; • Compressão prévia. Não é necessário bombear durante a aplicação. MODO DE USAR Bombeie de 15 a 20 vezes previamente à pulverização. Não utilize produtos químicos como solventes, ácidos ou tintas. Após o uso, remova o produto, lave e pulverize com água limpa para maior vida útil do pulverizador. GARANTIA; 30 DIAS REF; PULVERIZADOR MANUAL MARCA; SIGMA TOOLS', 42.0, 42.0, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8c1m7z5yfwx7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F911892833%2F21198101314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
