INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697688559', 'Kit 2 Pneus Continental 175/65 R14 82T ContiPowerContact', 'Kit 2 Pneus Aro 14 Continental 175/65 R14 82T ContiPowerContact Sobre o Pneu: Desenvolvido para equipar carros compactos e médios, o pneu Continental ContiPowerContact oferece qualidade de sobra para o uso diário, seja urbano ou rodoviário, com muita segurança e conforto. Sobre a Marca: A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados. Informações Adicionais: - Marca: Continental - Modelo: ContiPowerContact - Medida: 175/65 R14 - Largura: 175mm - Perfil: 65% - Aro: 14 - Índice de peso: 82 - 475 kg - Índice de velocidade: T - 190 km/h - Sidewall: LETRAS PRETAS - Tipo de terreno: HT - Desenho: Assimétrico - Montagem: Sem Câmara - Garantia: 5 anos de Fábrica Aplicações: - FORD: COURIER, FIESTA, KA, KA +, KA II, KA III, KA SEDAN - FIAT: ARGO, CRONOS, GRAND SIENA, MOBI, PALIO, SIENA, TIPO, UNO, UNO II, UNO III - CHEVROLET: AGILE,ASTRA,CELTA,CORSA,PRISMA - HONDA: FIT “POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU”', 908.27, 908.27, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lw4bf38cznz1d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F19697688559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
