INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12342809614', 'DEUS QUE DESTROI SONHOS, O - THOMAS NELSON', 'O Deus cristão não pode ser domesticadoUma tentação constante que cerca a vida cristã é a inversão do chamado: a presunção de que Deus precisa abençoar o meu caminho e me seguir em meus planos e sonhos. Essa postura é enganosa e faz parecer que Deus só é fiel quando me abençoa. Mas e se Deus derrubar o meu sorvete, ele deixa de ser fiel? Claro que não. Às vezes, ele só quer chamar a minha atenção para o caminho certo. Eu já testemunhei gente adulta se comportando como criança por não ter a vida que pediu a Deus. Pediu errado! Neste livro, apresento o caminho do discipulado, o caminho para “sonhar” o que Deus já planejou.', 44.9, 44.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824g7-mffutvx3yux5a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F12342809614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
