INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098076759', 'Chave Catraca STANLEY SCF930B 10mm 20V Com Velocidade Variável', 'A Chave Catraca 10mm 20V STANLEY SCF930B é ideal para apertar e afrouxar porcas e parafusos em espaços apertados com mais rapidez e praticidade. Indicada para oficinas, manutenção automotiva, instalações e serviços mecânicos, a ferramenta oferece liberdade de movimento por funcionar sem fios ou mangueiras. Seu design compacto facilita o acesso em áreas reduzidas, tornando o trabalho mais eficiente e confortável em aplicações profissionais e domésticas. A ferramenta faz parte da plataforma sem fio STANLEY V20, compatível com baterias de íon de lítio 20V. Conta com velocidade variável para maior controle nas aplicações, além de motor potente com até 300 RPM e 47 Nm de torque. O encaixe de 3/8" com pino de retenção oferece mais segurança durante o uso. Possui luz LED integrada para melhor visibilidade e carcaça em nylon com fibra de vidro, proporcionando resistência a óleos e produtos químicos. O projeto ergonômico da bateria melhora o acesso em locais apertados. Principais características • MOTOR POTENTE: até 300 RPM e 47 Nm para aplicações mecânicas • VELOCIDADE VARIÁVEL: mais controle e precisão durante o uso • ENCAIXE 3/8": retenção segura do soquete com pino de trava • DESIGN COMPACTO: facilita o acesso em espaços reduzidos • LUZ LED INTEGRADA: melhor visibilidade em áreas com pouca luz • CARCAÇA REFORÇADA: resistência a óleos e produtos químicos Atenção: Produto vendido sem bateria e sem carregador. O anúncio contempla somente a ferramenta. Robusta, prática e eficiente, a Chave Catraca 10mm 20V STANLEY SCF930B é ideal para quem busca mais agilidade, mobilidade e desempenho em trabalhos mecânicos e automotivos.', 479.0, 479.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820m8-mq3njirjtclc14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1475272551%2F21098076759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205217636', 'Camisa Adulto Motocross Pro Tork Hero Lançamento 2026', 'Confira mais uma opção de camisa desenvolvida pela Pro Tork para a prática do motociclismo off road. O modelo Hero 2026 é confeccionado em poliéster, com grafismos sublimados e gola redonda, oferecendo conforto e segurança para quem curte enrolar o cabo com estilo. Especificações: - Tecido 100% Poliéster; - Grafismos sublimados; - Gola redonda; - Marca: Pro Tork. Dica: - Consulte a tabela de medidas para conferir a numeração indicada. Observação: - Imagem ilustrativa: Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 126.21, 84.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-8260m-mko4lral7p4w37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F58205217636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
