INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41724530804', 'Kit 3 Desinfetante Gel Uso Geral Marine Pato Limpeza Profunda Squeeze 750ml', 'O Kit Contém: 3 Desinfetante Gel Uso Geral Marine Pato Limpeza Profunda Squeeze com 750ml cada unidade. Pato Limpeza Profunda Gel é um limpador completo para o seu vaso sanitário. Ele possui fórmula avançada que atua na remoção de manchas e elimina 99,9% dos germes - bactérias. Além disso, Pato possui um bico de design exclusivo que permite maior alcance embaixo da borda do vaso, limpando de forma eficiente e deixando uma agradável fragrância.', 67.59, 67.59, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258s-mfwll0g3j5ze72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F41724530804', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592479300', 'Kit 4 Fraldas Turma da Mônica Baby Mega P com 62un cada', 'Kit Contém: 4 Pacotes de Fraldas Turma da Mônica Baby Mega P com 62un cada A Turma da Mônica Baby uniu proteção e conforto em uma nova opção de fralda, para garantir que seu bebê cresça feliz e tenha as melhores lembranças da sua infância. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho.', 268.99, 268.99, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rav9-ma47hllo5ifi56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F22592479300', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16213466037', 'Shampoo Anticaspa Clear Men Controle e Alívio da Coceira 400ml', '• O Shampoo Anticaspa Clear Men Controle e Alívio da Coceira foi desenvolvido para homens, pois o couro cabeludo do homem está mais propenso a caspa • Com tecnologia Bio Booster que ajuda a ativar a proteção natural do couro cabeludo, acabando com a caspa recorrente* • Com eucalipto e melaleuca, este shampoo suaviza e acalma o couro cabeludo para um alívio imediato da coceira** • Este shampoo para uso diário é indicado para homens com couro cabeludo oleoso e irritado • O Shampoo Anticaspa Ice Cool Menthol protege o couro cabeludo, nutrindo-o, além de proporcionar uma sensação intensa de refrescância e remoção da oleosidade • O Shampoo Clear Men fortalece o couro cabeludo e acaba de vez com a caspa, deixando seu cabelo saudável e com sensação refrescante O Shampoo Anticaspa Clear Men Controle e Alívio da Coceira, foi desenvolvido para homens, porque o couro cabeludo do homem está propenso a caspa. Formulado com Bio Booster, a nova tecnologia inteligente que ajuda a ativar a proteção natural do couro cabeludo e acaba com a caspa recorrente*. Este shampoo anticaspa com eucalipto e melaleuca, suaviza e acalma o couro cabeludo para um alívio imediato da coceira**. O shampoo Controle e Alívio da Coceira é indicado para homens com o couro cabeludo oleoso e irritado. Ele protege o couro cabeludo, nutrindo-o, além de proporcionar uma sensação intensa de refrescância e remoção da oleosidade, para um visual perfeito. Aplique no cabelo molhado, massageie o couro cabeludo e enxágue. Repita. Para melhores resultados, use diariamente. Quanto mais se esforça, mais seu corpo irá protestar. O suor e a umidade em um dia intenso ou após a prática de esportes, podem deixar você com um couro cabeludo com coceira, o que possivelmente ajudará no aparecimento da caspa. *livre de escamas visíveis com o uso regular. **coceira devido à caspa.', 49.29, 36.38, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rblu-m632dnz6081sc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F16213466037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
