INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794524134', 'Ômega 3 Cúrcuma - 60 Cápsulas - Katiguá', 'O Ômega 3 Cúrcuma de 60 Cápsulas da Katiguá é um suplemento alimentar de alta qualidade, formulado com ingredientes naturais e cuidadosamente selecionados. Este produto combina o óleo de peixe (MEG3), rico em ácidos graxos ômega 3, com o extrato de rizomas de cúrcuma, conhecido por suas propriedades antioxidantes e anti-inflamatórias, e a vitamina E, um poderoso antioxidante. A cápsula é composta por gelatina, glicerina, sorbitol e água purificada, e não contém glúten, tornando-o adequado para pessoas com restrições alimentares. Este suplemento é uma fonte rica de nutrientes essenciais que contribuem para o bom funcionamento do organismo. O Ômega 3 Cúrcuma de 60 Cápsulas da Katiguá é fácil de ser absorvido pelo organismo, proporcionando benefícios à saúde de maneira eficaz. É Uma escolha ideal para quem busca um estilo de vida saudável e equilibrado. Como Tomar Consumir 2 (duas) cápsulas uma vez ao dia de preferência perto das refeições. Este produto não substitui uma alimentação equilibrada e seu consumo deve ser orientado por médico, farmacêutico e/ou nutricionista. Ingredientes Óleo de peixe (MEG3), Extrato de rizomas de Curcuma, Vitamina E (tocoferol). Composição da cápsula: Gelatina, Glicerina, Sorbitol e Água Purificada. NÃO CONTÉM GLÚTEN. ...', 96.8, 96.8, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-8259j-mfwuzt3ia5fz1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F23794524134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
