INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997686449', 'Vonixx Intense 500ml Revitalizador Automotivo para Plásticos Internos com Proteção Solar UV', 'Revitalizador de Plásticos Proteção UV Intense 2009039 Vonixx 500ml Características Intense é um renovador de plástico com proteção UV, cuja fórmula balanceada promove acabamento natural e toque seco, com durabilidade de 6 meses. O produto deve ser utilizado especificamente na parte interna do automóvel, em superfícies como vinil e plástico em geral. Informações Técnicas - Diluição: Pronto uso; - Duranbilidade: Até seis meses de proteção nos plásticos internos; - Intense pode ser utilizado em painéis soft touch; - Não recomendamos o uso do produto em plásticos externos e em couro; - Toque seco; - Proteção UV. Modo de uso 1. Certifique-se que a superfície esteja limpa e seca. 2. Aplique uma pequena quantidade de produto de maneira uniforme com o auxílio de um aplicador de microfibra. 3. Espalhe bem até o total preenchimento da peça. Qualidade: Trabalhamos com produtos de fabricantes reconhecidos em todo mercado brasileiro e internacional. Vendemos produtos de excelente desempenho para uso profissional. Conte com nosso suporte para tirar dúvidas referentes à utilização dos produtos. Observação: - Todas as informações divulgadas são de responsabilidade do Fabricante/Fornecedor; - Imagens meramente ilustrativas, consulte nosso atendimento para mais detalhes.', 48.95, 48.95, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwygkzsp8oeq59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F409830325%2F19997686449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
