INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693658171', 'Royal Canin Pastor Alemão Filhote 10kg', 'A Royal Canin oferece uma variedade de produtos nutricionais, desenvolvidos especialmente para atender às necessidades específicas de gatos e cães em diferentes etapas da vida, tamanhos e condições de saúde. Algumas das principais linhas de produtos incluem:Linha para Filhotes: Fórmulas adaptadas que promovem o crescimento saudável e o desenvolvimento do sistema digestivo dos filhotes.Linha para Adultos: Dietas personalizadas que atendem às necessidades nutricionais de cães adultos, considerando seu tamanho, raça e necessidades específicas.Linha para Idosos: Fórmulas específicas para as necessidades nutricionais dos cães mais velhos, ajudando a manter uma boa saúde na fase madura.Linha Canine Care Nutrition: Nutrição específica para cães com necessidades de cuidado especial, como problemas digestivos ou de pele.Linha para Raças Específicas: Produtos desenvolvidos com nutrientes selecionados especificamente para diferentes raças de cães, proporcionando uma alimentação balanceada e saudável.', 406.09, 324.88, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5ae4md4umr698', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F23693658171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
