INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297764310', 'Descontaminante Ferroso Limpa Rodas Odor Neutro Finisher 1l', 'DESCONTAMINANTE FERROSO 1L - FINISHERCARACTERISTICAS:- Produto desenvolvido para a limpeza profunda de óxidos metálicos em superfícies externas, como rodas, pinturas, vidros e outras- Possui ação desincrustante, sem danificar materiais sensíveis- Produz coloração especial ao identificar óxidos de ferro- Exclusiva tecnologia de suavização do odor característicoAPLICAÇÃO:- Antes de iniciar a aplicação deste produto, certifique-se que a área aplicada está fria e sob proteção solar- Em sujidades leves, borrife o produto na superfície ainda seca e aguarde sua cor alterar para roxo- Assim que iniciar a perda da coloração adquirida(até 2 min), faça o enxágue utilizando uma máquina de alta pressão- Em limpezas de incrustações, borrife o produto na superfície e esfregue com ajuda de um pincel, reaplicando conforme necessário- Faça o enxágue, utilizando água de alta pressão ou proceda usando água corrente com ajuda de um pincel', 99.1, 99.05, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-lzqmwgu4tw1g4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F22297764310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
