INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594300586', '2 Placas Proibido Fumar Plaquinha Não Fume Aviso Lei 20x15', 'Placa "Proibido Fumar" – 15x20cm Por um ar mais puro e saudável! Placa de sinalização “Proibido Fumar” que contribui para um ambiente mais limpo e protege a saúde de todos ao redor. Produzida em Poliestireno (PS) 1mm, é leve, resistente e de fácil instalação. Destaques do Produto: Tamanho: 15x20cm Material: PS 1mm com impressão em silk screen, garantindo excelente durabilidade e nitidez Aplicação Simples: Acompanha fita dupla face de alta fixação Visual Profissional: Cores vivas e de fácil leitura, mesmo à distância e em diferentes horários do dia Resistente à água e umidade: Pode ser usada em áreas internas e externas Instalação Flexível:Fixe com a fita inclusa, parafusos ou abraçadeiras, conforme a necessidade. Conteúdo da embalagem:2 placas + 1 conjunto de fita dupla face', 22.36, 20.34, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-md4ielg0mep2ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F22594300586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
