INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16928889964', 'Livro - Superação', 'Você usa a dor para construir, não para destruir? Tem consciência de que a vida é um grande contrato de risco sem cláusulas definidas? Você culpa os outros pelas derrotas? Como encara as adversidades? Se você já se fez alguma dessas perguntas, este livro de Augusto Cury é para você. Nele, o autor orienta sobre como superar as dificuldades do dia a dia e transformar cada um dos acontecimentos em uma oportunidade criativa para se superar e ter uma vida melhor._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2022_x000D_ Autor: Augusto Cury_x000D_ Idioma: Português_x000D_ Páginas: 64_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.50_x000D_ ISBN: 9786555527315', 19.9, 19.9, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/e7455bef23be2337966330ea2b21a26e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F16928889964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23131708969', 'Kit Livros Almanaque', 'Kit Livros Almanaque Loja Oficial Ciranda Cultural Almanaque - Folclore Agora ficou ainda mais divertido ler histórias em quadrinhos. Além das histórias folclóricas aqui reunidas, tem passatempos divertidos de cada uma das histórias: Iara, Lobisomem, Mula sem cabeça, Saci Pererê e Festa no Céu. Caça-palavras, jogo dos sete erros, sombra correta e palavras cruzadas. Editora: Ciranda Cultural Edição: 1, 2021 Autor: Paloma Blanca Alves Barbieri Ilustrador: Franco de Rosa Idioma: Português Páginas: 96 Dimensões: L 20.10 x A 26.80 x E 0.60 ISBN: 9788538095156 Coleção: Almanaque é diversão Linha Editorial: Ciranda Cultural - Ficção infantil Faixa Etária: + 4 anos Assuntos (tags): Histórias em quadrinhos, Passatempos, Folclore, Lendas, Diversão, Diversidade, Histórias, Caça palavras, Sete erros, Palavras-cruzadas BISAC: Histórias em Quadrinhos & Graphic Novels / Fantasia Linha de Produto: Almanaque Encadernação: Brochura Acabamento: Verniz de máquina Material: Papel Almanaque - Contos clássicos Agora ficou ainda mais divertido ler histórias em quadrinhos. Além de acompanhar neste almanaque os contos clássicos Pinóquio, Os três porquinhos, João e Maria, João e o pé de feijão e O patinho feio, você vai se divertir com caça-palavras, palavras cruzadas e outros jogos. A diversão vai começar! Editora: Ciranda Cultural Edição: 1, 2021 Autor: Paloma Blanca Alves Barbieri Ilustrador: Moacir Rodrigues, Irineu Rodrigues Idioma: Português Páginas: 96 Dimensões: L 20.10 x A 26.80 x E 0.60 ISBN: 9788538094739 Coleção: Almanaque é diversão Linha Editorial: Ciranda Cultural - Ficção infantil Faixa Etária: + 4 anos Assuntos (tags): Histórias em quadrinhos, Contos clássicos, Aventura, Passatempos, Almanaque, Clássicos, Caça palavras, Palavras-cruzadas, Diversão