INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209455617', 'Enxaguante Bucal Zero Listerine', 'Listerine Cool Mint Zero é um enxaguante bucal antisséptico sem álcool, ideal para eliminar germes que causam placa bacteriana, mau hálito e gengivite. Sua fórmula alcança onde a escova e o fio dental não chegam, proporcionando uma higiene bucal completa. * Promove proteção contra germes por até 12 horas. * Possui sabor de menta suave, proporcionando uma sensação prolongada de refrescância. * Recomendado para uso diário após a escovação e o uso do fio dental, pela manhã e à noite. Faça bochechos com 20ml por 30 segundos, sem diluir.', 28.99, 28.99, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8258u-mqnektz9juvf1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58209455617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
