INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193011601', 'Cartão Kit Juiz Árbitro Futebol Society Futsal Salão Quadra Campeonato Treino Profissional - Oficial', 'Cartão Para Juiz Arbitro Oficial Futsal O cartão do árbitro é uma ferramenta oficial de comunicação, graças à qual os jogadores recebem avisos e punições de maneira visível. Juntos, esse item ajuda o árbitro a controlar e manter sua autoridade em campo, garantindo assim um jogo justo e equilibrado. BENEFICIOS: Autoridade e Respeito: acessórios oficiais, como cartão juiz, transmitem autoridade e profissionalismo, garantindo o respeito dos jogadores e do público; Controle de jogo: acessórios ajudam o árbitro a manter o controle da partida, permitindo que ele conduza atentamente da maneira mais justa e equilibrada possível; Visibilidade do cartão: dá uma clara e visível resposta aos jogadores para suas advertências e penalidades, garantindo que sua voz seja ouvida e suas instruções entendidas; Durabilidade – feitos de materiais de alta qualidade, os acessórios duram e melhoram ao longo do tempo. ESPECIFICAÇÕES: Cartão Futsal cores: Amarelo, Azul e vermelho Material: PVC Tamanho: 10,5 X 7,5 CM O QUE ESTÁ INCLUSO? 1 Jogo de 3 cartões Futsal! Clique em "MAIS ANÚNCIO DO VENDEDOR" e veja também outros modelos disponíveis. O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas duvidas diretamente com um de nossos atendentes', 44.94, 23.29, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7b8h8vubzv056', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F22193011601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
