INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45558583446', 'Fogareiro Super Chama Lite Com Ignição Eletrônica Nautika', 'Fogareiro Super Chama Lite com Ignição Eletrônica 6800W Nautika CARACTERÍSTICAS: - Garantia: 3 Meses - Tipo: Fogareiro portátil a gás - Modelo: Super Chama Lite - Potência: 6800W - Acendimento: Ignição eletrônica automática - Combustível: Cartucho tipo Tekgás NTK - Material: Aço inoxidável, alumínio e cobre - Estrutura: Dobrável - Suporte: Panelas até 20 cm de diâmetro - Capacidade de carga: Até 5 kg - Dimensões aproximadas: 16,5 x 11 cm - Peso aproximado: 535 g - Portátil: Sim - Acompanha estojo: Sim - Uso: Camping, trilhas e atividades ao ar livre - SKU: 280471-UN - Marca: Nautika DETALHES: - O Fogareiro Super Chama Lite Nautika é ideal para quem busca alta performance, praticidade e leveza em aventuras ao ar livre. - Com potência de 6800W, garante aquecimento rápido e eficiente, permitindo preparar refeições em menos tempo. - Possui sistema de ignição eletrônica automática, facilitando o acendimento sem necessidade de fósforos ou isqueiros. - Seu design compacto com pés dobráveis facilita o transporte e armazenamento, sendo perfeito para camping, trilhas e pescarias. - Fabricado em aço inoxidável, alumínio e cobre, oferece alta resistência e durabilidade mesmo em condições adversas. - Suporta panelas de até 20 cm e até 5 kg, proporcionando estabilidade e segurança durante o uso. - Acompanha estojo de transporte, garantindo praticidade e proteção no deslocamento. - Ideal para quem busca um fogareiro leve, eficiente e confiável para atividades externas. - Produto indispensável para quem valoriza praticidade, desempenho e segurança em qualquer aventura. - Une potência, portabilidade e resistência em um único equipamento. CONTEÚDO DA EMBALAGEM: - 1 Fogareiro Super Chama Lite Nautika - 1 Estojo para transporte', 229.9, 179.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqc32qn81lou1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F45558583446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
