INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199393975', '60 Pilhas Auditivas Nº A10 / Pr70 Duracell Com 6 Unidades', 'A Duracell fabrica pilhas alcalinas de alta performance, baterias especiais e pilhas recarregáveis. Fundada no início dos anos 40, a empresa se tornou, desde então, uma marca icônica em energia pessoal e confiável por suas pilhas compactas e de maior duração. E no coração disso tudo está o Coelhinho da Duracell. Ouça cada momento com as pilhas auditivas Duracell nº 10 de longa duração. Elas são simples de segurar, substituir e remover, devido ao comprimento do selo EasyTab que facilita o seu manuseio. As embalagens possuem selos de diferentes cores (amarelo, laranja, marrom e azul) para que você não tenha dificuldades em encontrar o tamanho desejado : 10, 13, 312 E 675. A tecnologia de Duracell garante às pilhas auditivas 4 anos de armazenamento. Composição: Zinco, Dióxido de manganês, hidróxido de potássio Mantenha as pilhas fora do alcance das crianças. Se engolidas, consulte um médico imediatamente. Não recarregue ou descarte as pilhas e baterias no fogo. Não transporte pilhas soltas no bolso ou na bolsa.', 299.9, 224.9, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/br-11134207-820mh-mlw8q9njefba50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289840749%2F23199393975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692874681', 'Combo Kit Central Multimidia Android MP5 7 polegadas + Camera de ré + Moldura Gol Parati Saveiro G3', 'Carroussel Auto apresenta: Seu carro merece mais tecnologia com um kit multimídia+câmera+moldura! #APLICAÇÃO# - VW GOL G3: 2000, 2001, 2002, 2003, 2004 e 2005 - VW PARATI G3: 2000, 2001, 2002, 2003, 2004 e 2005 - VW SAVEIRO G3: 2000, 2001, 2002, 2003, 2004 e 2005 Para mais detalhes sobre compatibilidade consulte a(s) foto(s) "APLICAÇÃO" #CONTEÚDO DO KIT# - 1 Central Multimídia - 1 Câmera de Ré Borboleta com Linhas Guias Fixas - 1 Moldura 2 din para acabamento na cor preto* ==================================================================== A multimídia conta com sistema operacional Android que já possui os aplicativos Maps, Waze, Spotify e YouTube; e que permite a instalação de aplicativos pela Play Store. Ela dispõe de conexão Wi-fi, então você roteando a internet do celular navega pela internet na multimídia, baixa aplicativos e faz nela tudo o que faz no celular! E com a câmera de ré você evita acidentes executando manobras com muito mais segurança. ==================================================================== #MULTIMÍDIA# - Tela de 7" Full Touch Capacitiva de Vidro com LCD em LED - 8 opções de cores nos botões laterais - Algumas opções de logotipos de montadoras na inicialização - Saída para Tela Extra (Encosto de Cabeça) - Entrada para câmera de ré - Entrada USB traseira - Muda e navega por pastas do USB - Reprodução de áudio, vídeo e imagens - Conectividade Bluetooth: streaming de áudio no carro e atendimento de chamadas viva-voz pelo microfone embutido - Espelhamento via cabo de celular Android a partir da versão 5.0 - Espelhamento via cabo de celular IOS a partir do 4 - Conexão via cabo AndroidAuto - Conexão via cabo ClarPlay - Rádio FM - GPS integrado (mapas à parte) - Conexão a redes wi-fi - Sistema operacional Android - Processador Quad Core - 1 GB de memória RAM - 16 GB de HD (armazenamento interno) - Potência: 4 canais de 60W RMS cada - Acompanha 2 fios SWC para comando de volante com até 10 funções, para seu funcionamento alguns carros precisam de interface de volante a ser adquirida separadamente ==================================================================== #CÂMERA# - Imagem nítida e colorida com resolução de 420p - Ângulo de Visão: 120° vertical e 170° horizontal - Visão noturna: não tem infravermelho, mas é possível enxergar à noite dependendo da iluminação externa - Linhas guias de estacionamento fixas, ou seja, não acompanham o movimento do volante - Instalação pelo suporte borboleta ==================================================================== #OBSERVAÇÕES# - Garantia de fábrica: 90 dias - Leve esse produto para ser instalado em uma empresa especializada para evitar perder a garantia por erros na instalação - Não acompanha o chaveiro, foto meramente decorativa *É possível ocorrer alguma diferença de cor com em relação ao painel devido à ação do tempo e exposição do veículo ao sol.', 714.0, 641.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lts3zbu57bu4bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1183527021%2F23692874681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
