INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593695347', 'Borboleta Musical Educativa - Diversos Sons Luzes - 14 Botões Interativos - Embalagem - 18cm Inmetro', 'Transforme o aprendizado do seu filho em uma aventura mágica com a Borboleta Interativa! Um brinquedo educativo e divertido, perfeito para estimular o desenvolvimento do seu bebê. Dois modos de aprendizado: Explore o mundo dos animais e das melodias no Modo 1, ou embarque em desafios de raciocínio e memória no Modo 2. Ajuste de volume: Adapte o som para ambientes diferentes, garantindo a diversão sempre! Dimensões: 18x11x3cm 14 botoes interativos Saida para Som 3 Pilhas Benefícios para o desenvolvimento do seu bebê: - Estimula a audição: Melodias e sons de animais que despertam a percepção sonora. - Desenvolve a coordenação motora: Botões e texturas que incentivam o movimento das mãos. - Promove o aprendizado: Apresenta animais, melodias e jogos de forma divertida. - Incentiva a curiosidade: As diferentes funcionalidades exploram a criatividade do bebê. - A Borboleta Interativa é perfeita para bebês a partir de 6 meses. Produto importado a pronta entrega Certificado Inmetro', 89.9, 57.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhc93qe4xxj9cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F22593695347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22296276894', 'Kit Estilo Barbie: Secador, Espelho, Pente, Jogo de Poltrona, Kit Sala | 3 Caixas de Brinquedos de Princesa Imaginação', 'Desperte a imaginação e a magia das princesas com os 10 brinquedos perfeitos! A coleção exclusiva da Kendy Brinquedos foi criada para encantar as meninas e proporcionar horas de diversão e criatividade. Conjunto Mini Secador, Pente e Espelhinho: Permite que sua pequena princesa se sinta como uma verdadeira estrela, cuidando dos cabelos e se admirando no espelho. Jogo de Poltronas: Crie ambientes encantadores e recrie as histórias dos contos de fadas. Kit Sala: Inclui TV, mesa e rack para criar uma sala de brincadeira completa. Três Caixas Exclusivas em um Único Anúncio: Conjunto completo para uma experiência única de brincadeira. Cores Sortidas: As caixas podem conter itens nas cores rosa e laranja. Certificado do Inmetro: Garante a segurança e qualidade dos produtos. Fabricado pela Kendy Brinquedos: Empresa renomada no ramo de brinquedos, que preza pela excelência em cada detalhe. Não perca a oportunidade de presentear sua pequena princesa com os 10 brinquedos perfeitos para estimular a imaginação! Com a Kendy Brinquedos, a diversão está garantida!', 24.9, 17.89, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134201-820lf-mqxmie4jpgqt23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F22296276894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
