INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209454032', 'Sorvete Frutare Uva Kibon', 'Refresque-se com o picolé Fruttare de uva da Kibon! Uma explosão de sabor em cada mordida, perfeito para os dias quentes ou para um lanche rápido e saboroso. Feito com suco de uva concentrado e vitamina C, Fruttare Uva é a combinação ideal de sabor e refrescância.', 9.79, 9.79, NULL, 'Food & Beverages > Dairy & Eggs > Ice cream', 'https://cf.shopee.com.br/file/sg-11134201-8260n-mk1i8a2tyygx47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555072%2F58209454032', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203764010', 'Shorts Saia Feminino em Tecido Linho Dianna Preto', 'Shorts Saia Feminino Dianna, desenvolvido em Tecido Linho, que oferece leveza, elegância e caimento natural. Possui cós frente e costas com revel interno do próprio tecido, garantindo acabamento refinado e maior conforto. Conta com zíper invisível lateral e pences nas costas, que valorizam a silhueta com ajuste perfeito. A barra levemente em A com acabamento em bainha confere movimento sutil e toque moderno à peça.', 79.99, 79.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-825aw-mr06wacpl2bpf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58203764010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998535177', 'Moldura 2 Din Painel Multimídia 7 polegadas GM Astra 1998 a 2011 Preto Ar Analógico Digital', 'ENVIO IMEDIATO! PRODUTO EM ESTOQUE, NOTA FISCAL E GARANTIA! Moldura Painel 2 Din 7" para GM Astra 1998 a 2011 Com Ar Digital ou Ar Analógico A solução ideal para modernizar o interior do seu Astra e estilo! A moldura 2 Din é perfeita para instalação de centrais multimídia de 7 polegadas, proporcionando acabamento preciso, firmeza no encaixe e visual alinhado ao painel original do veículo. Compatibilidade: - GM Astra Hatch e Sedan: 1998 a 2011; - GM Astra Sedan: 1998 a 2011; * Serve nos modelos com ar analógico ou ar digital Características: - Visual moderno para o painel do seu Astra; - Compatível com multimídias de 7 polegadas nos padrões Japonês ou Chinês; - Instalação na medida, sem comprometer a estética original; - Produto leve, resistente e com ótimo acabamento. Especificação Técnica: - Polegadas: 7; - Modelo: 2 din; - Material: plástico ABS; - Cor: preto; - Acabamento: fosco. Itens inclusos: - 01 Moldura; - Suporte para fixação lateral; - 01 Peça para Controle de Ar Digital - 01 Peça para Controle de Ar Analógico - 01 Par de Suporte Lateral e 06 Parafusos - 01 Aro Adaptador. Importante: - Imagens Meramente Ilustrativas; - Recomendamos que a instalação seja feita por profissional especializado, não nos responsabilizamos pelo mau uso do produto. SUBGRAVE A SUA LOJA DE ACESSÓRIOS AUTOMOTIVOS!', 276.44, 276.44, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdm72nq3g7gxb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F22998535177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492886354', 'H''maston LY-13 Fone de Ouvido Sem Fio TWS Bluetooth Intra-Auricular Com Microphone e um Estojo', 'Fones de ouvido intra-auricular sem fio Bluetooth que se adaptam perfeitamente aos seus ouvidos,são leves e confortáveis de usar,ao mesmo tempo que fornecem efeitos sonoros de alta qualidade. Este fone de ouvido é perfeito para acompanhá-lo a qualquer hora e em qualquer lugar.Fones de ouvido Bluetooth homologados pela ANATEL,a qualidade original do produto é garantida. Performance do produto: 1.Conexão Bluetooth estável: Para garantir a transmissão de sinal mais estável,usamos um chip 5.0 para fornecer transmissão de dados mais rápida e estável e reduz atrasos. Ótimo para chamadas de voz,jogos,assistir filmes,fazer exercícios e muito mais. 2.Design ergonômico: Este fone de ouvido sem fio é ergonomicamente projetado para se adaptar a diferentes tamanhos de canais auditivos,proporcionando maior estabilidade e conforto sem prejudicar seus ouvidos. As pontas auriculares garantem um ajuste confortável e seguro. 3.Fácil de transportar: Adota um design de bolso para garantir um uso sem preocupação ao sair. Você pode transportar facilmente o fone de ouvido Bluetooth no bolso. Compartimento de carregamento de 200mAh suporta pelo menos 3-4 cargas. 4.Operação simples: Reproduz/pausar músicas,fazer chamadas e obter informações com um toque sem tirar o telefone do bolso,liberando as mãos. 5.Ampla compatibilidade: Este fone de ouvido Bluetooth possui um sistema integrado perfeito com diferentes modelos de telefones e pode se conectar de forma rápida e estável a dispositivos iPhone e Android,etc. Com apenas alguns toques você pode emparelhar facilmente seus fones de ouvido com seu smartphone e desfrutar de uma conexão confiável,sem necessidade de cabos. 6.Várias cores para escolher: Cores brilhantes de Macaron,6 cores disponíveis,preto,branco,amarelo,verde,vermelho e azul. Parâmetro: Modelo: Fone de ouvido Bluetooth Macaron H''maston LY-13 Versão Bluetooth: V5.0 Bateria do fone de ouvido: 30mAh Bateria do estojo de recarga: 200mAh Tempo de reprodução: 4 horas Tempo em espera: Cerca de 220 horas Distância de transmissão: 10 metros Perguntas frequentes: *Compatível com todos iPhones? / Sim. *Existe um microfones? / Sim. *Também compatível com Android? / Sim. *Tem redução de ruído? / Sim. *Quantas vezes o estojo de recarga pode carregar os fones? Pode recarregar os fones até 4 vezes.', 59.99, 45.99, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwfej69gs70y1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1155571749%2F22492886354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397687198', 'Fita Led Connect 10w 5m 4000K 220V Tensão Direta - Avant', 'Fita LED Connect 5M 220v: Iluminação potente e versátil para seu projeto. A Fita LED Connect 5M 220v é a solução ideal para quem busca uma iluminação potente e versátil para diversos ambientes. Com design moderno e instalação simplificada, essa fita LED se destaca por não necessitar de driver, conectando-se diretamente à tensão de 220v. Sua classificação IP65 garante resistência à água e poeira, permitindo uso em áreas externas, e a dimerização oferece controle da intensidade da luz. PROPRIEDADES: Comprimento: 5 metros Chip LED: 3535 LEDs por metro: 120 LEDs (potência de 10W) Linha de corte: 10 cm (potência de 10W) Eficiência Luminosa: 100 lm/W Material: Plástico e alumínio Conteúdo: 1 rolo de fita de 5M, 2 capas terminal, 2 cabos, 5 suportes de fixação Fita dupla-face: Permite fácil fixação em diversas superfícies. CARACTERÍSTICAS DE FUNCIONAMENTO: Voltagem: 220V Potência: 10W Fluxo Luminoso: 1000 lm Temperatura de Cor: 4000K (branco neutro) Vida Útil: 25.000 horas Dimerizável: Permite ajuste da intensidade da luz. IP65: Resistente à água e poeira, ideal para áreas externas. ESPECIFICAÇÕES TÉCNICAS E COMERCIAIS (Item 148009039): Código do Modelo: LED-FITA-EXT-CONNECT-IP65-10WM-5M-NE4000K-220VCA Código de Barras: 7899452042330 Garantia Oficial Avant: 12 meses para defeitos de fabricação. Sobre a Marca Avant: A Avant é uma empresa líder no mercado de iluminação LED, reconhecida pela qualidade, inovação e compromisso com a sustentabilidade. Com foco em oferecer soluções inteligentes e eficientes, a Avant desenvolve produtos de alta performance que atendem às necessidades de diversos projetos, desde residências até grandes empreendimentos comerciais e industriais.', 168.17, 119.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdvj-lygw4k1cg8yi37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F23397687198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204479988', 'Kit 2 Alto Falantes Subwoofer 8 Pol Bomber Bicho Papão 600 Watts RMS 4 Ohms Compacto Potente', 'Kit 2 Subwoofer 8 Bomber Bicho Papão 600 Watts RMS - 4 Ohms O Subwoofer Bomber SW8BP600-4 reúne potência e eficiência em um formato compacto de 8 . Com 600W RMS em 4 Ohms, responde de 35 Hz a 1,6 kHz e oferece desempenho real entre 61 Hz e 188 Hz, garantindo graves firmes e controlados. Sua bobina de 46,3 mm em Kapton, fio CCAW e 4 camadas entrega alta resistência térmica, enquanto o Xmax de 11 mm assegura boa movimentação sem distorções. Com cone de celulose, centragem em algodão e poliéster e carcaça em aço, pesa 4,37 kg e ocupa apenas 1,44 L dentro da caixa. Um sub compacto, forte e pronto para entregar grave consistente. Especificações Técnicas: • Tamanho: 8 • Potência (RMS): 600 WATTS • Impedância nominal: 4 Ohms • Cor carcaça: Preta • Resposta em frequência (–10 dB): 35 Hz - 1,6 kHz • Resposta em frequência (–3 dB): 61 Hz - 188 Hz • Sensibilidade (Banda efetiva): 87 dB SPL • Diâmetro da bobina: 46,3 mm • Altura do enrolamento / Camadas: 30 mm / 4 • Material do corpo da bobina: Kapton • Material do fio da bobina: CCAW • Altura do gap: 8 mm • Xmax (deslocamento máx. pico): 11 mm • Xlimite (antes do dano): 19 mm • Dimensional do imã: 134 x 36 mm • Material do cone: Celulose • Material da centragem: Algodão e poliester • Material da carcaça: Aço Conteúdo da Embalagem: • 02 Subwoofer Bicho Papão 8 • Certificado de Garantia Importante: • Garantia de 273 dias. • Valor do Par.', 759.8, 759.8, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mk83bhs6bwncb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F58204479988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
