INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20650322116', 'Fita Led Shocklight Dual Color 2 Estágios DRL/Pisca 75cm - 6000K/3000K - (SL-DC75)', 'A Shocklight está lançando no mercado nacional a linha de Fita Dual Color. A fita permite a instalação com flexibilidade no farol do carro, conta com luzes de LED com duas cores e é à prova d''água podendo ser cortada e instalada do jeito que desejar! Especificações Técnicas: • LED Auxiliar Flexível • Tonalidade Branca e Amarela • Temperatura de Cor 6000K e 3000K • Quantidade de LEDs 156 • Funcionamento: Possui 2 Estágios de Cor de Luz na Mesma Barra • 1° Estágio: Luz Branca Fixa DRL (Luz Diurna). • 2° Estágio: Acionando a Seta, Pisca na cor Âmbar • Possibilidade de Reduzir o Tamanho Para Ajuste de Acabamento • Vida Útil de Até 30000hs • Quantidade de Leds: 78 • Lumens: 1716LM • Watts: 4,4W • Cores Branca 6000K e Amarela 3000K no mesmo Produto • Cor Amarela 3000K com Indicador de direção - Pisca/Seta • Adesivo de Alta Fixação (instalação externa) • Resistente a Vibrações • À Prova D''Água • Resistente ao Calor • 12 Volts Conteúdo da Embalagem: • 02 Fitas Led 75 cm • Manual e Certificado de Garantia Importante: • Garantia de 90 Dias. • Valor Unitário • Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal. • A Eletroking recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 124.9, 117.41, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7qvfn-lfju533va1ot1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F20650322116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
