INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298156183', 'Extrator de tubo/cano quebrado 1/2" e 3/4" VONDER', 'Indicado para remoção de canos quebrados dentro da rosca de outro cano, com diâmetros de 1/2" e 3/4". Possui 2 medidas para extração de canos quebrados dentro da rosca de outro cano, uma de 1/2" e outra de 3/4". Acompanha uma alavanca que facilita a remoção do cano quebrado. Conteúdo da Embalagem: 1 Extrator de tubo/cano quebrado com alavanca. Detalhes técnicos: Material: Aço ao Cromo Dimensões: 99 mm x 15 mm x 12 mm Capacidade: 1/2" e 3/4" Massa aproximada (peso): 0,325 kg', 33.0, 29.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ra3q-m5bqxr3o9wem53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F23298156183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
