INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393865698', '1~5 FARINHA ITALIANA 00 NITA PIZZARIA 1KG FULL', 'Farinha de Trigo 00 1kg - Nita Descrição: Farinha de trigo enriquecida com ferro e ácido fólico. A primeira farinha italiana Tipo 00 embalada no Brasil. Uma farinha forte, com W mínimo 280, para pães e pizzas de longa fermentação Principais Aplicações: Para uso profissional, apresenta características ideais para pães de longa fermentação e pizza. Lista de Ingredientes: Farinha de trigo tipo 1, enriquecida com ferro e ácido fólico. Características Físico-químicas Umidade (%): 12,5 – 15,0Cinzas (%): máx 0,60Glúten Úmido (%): mín. 28Falling Number (s): min 280Granulometria (%): 95 – 100 passante na malha de 250 micras. Características Reológicas Absorção Farinográfica (%): 57 - 60.“W” Alveográfico (10-4J): mín. 280 Características MicrobiológicasResolução ANVS nº 331 de 23 de dezembro de 2019. Contém glúten Alergênicos: Contém derivados de trigo e pode conter centeio, cevada, aveia, triticale e soja. Este produto é enriquecido com 4mg a 9mg de ferro/100g e com 140µg a 220µg de ácido fólico/100g. Embalagem: Sacos de papel Kraft branco, totalmente vedada e sem vazamento. Peso líquido 1 kg Prazo de Validade: 300 dias Conservação: Conservar em local seco, fresco e protegido da luz', 38.85, 38.85, NULL, 'Food & Beverages > Baking Needs > Flour', 'https://cf.shopee.com.br/file/sg-11134201-7reoj-m80fen8ucr6v2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23393865698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11334737523', '50 FORMINHAS TEMATICA CAPITÃO AMÉRICA (MODELO 2) PARA DOCES', 'ESTE KIT CONTÉM 50 FORMINHAS DE PAPEL COM 4 PÉTALAS E UM DESIGN INSPIRADO NO CAPITÃO AMÉRICA (MODELO 2). PERFEITAS PARA EMBALAR SEUS BRIGADEIROS 🍫, BEIJINHOS 🥥, BOMBONS DE CHOCOLATE 🍬 E OUTROS DOCINHOS EM FESTAS TEMÁTICAS DO CAPITÃO AMÉRICA, FESTAS DE ANIVERSÁRIO DE SUPER-HERÓIS E OUTRAS CELEBRAÇÕES AVANÇADAS! ADICIONE UM TOQUE HEROICO E COLORIDO À SUA MESA DE DOCES! AS FORMINHAS SÃO ENVIADAS DESMONTADAS PARA EVITAR DANOS DURANTE O TRANSPORTE. TAMANHO: APROXIMADAMENTE 3,5 CM DE LARGURA X 3,5 CM DE COMPRIMENTO (BASE) COM 2,5 CM DE ALTURA 📏 (TAMANHO PADRÃO PARA DOCINHOS). MATERIAL: PRODUZIDAS EM PAPEL OFFSET DE BOA GRAMATURA COM IMPRESSÃO COLORIDA DO TEMA CAPITÃO AMÉRICA (MODELO 2). ATENÇÃO ❗: NÃO ACOMPANHA OS DOCES (AS FOTOS SÃO APENAS SUGESTÕES DE USO 📸). NÃO FAZEMOS PERSONALIZAÇÃO NESTE ITEM 🙅‍♀️. VERIFIQUE O PRAZO DE ENVIO 🚚 ANTES DE FINALIZAR A COMPRA. AS FORMINHAS SÃO ENVIADAS DESMONTADAS PARA PRESERVAÇÃO E FACILIDADE DE ENVIO, MAS SÃO FÁCEIS DE MONTAR 😉. AS CORES E DESENHOS DO CAPITÃO AMÉRICA PODEM VARIAR LIGEIRAMENTE 🌈 DEPENDENDO DO LOTE. DEIXE SUA FESTA COM A FORÇA E O PATRIOTISMO DO CAPITÃO AMÉRICA! CLIQUE EM "VER MAIS PRODUTO DESSE VENDEDOR" PARA DESCOBRIR OUTROS ITENS INCRÍVEIS! ✨', 10.24, 10.24, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/744a7a41999579de0eab39eb9bca6be3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F11334737523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
