INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399034410', 'Serrote Dobrável de Poda 7.1/2" Vonder Aço Carbono', 'Serrote Dobrável de Poda 7.1/2" – VONDER O Serrote Dobrável de Poda Vonder é indicado para cortes rápidos e precisos em galhos secos, verdes e tubos de PVC. Sua lâmina em aço carbono com dentes temperados e afiação ultracortante garante durabilidade e desempenho superior. Compacto e leve, possui sistema de trava que aumenta a segurança no manuseio, sendo ideal para jardinagem, camping e serviços gerais. Itens Inclusos 1 Serrote dobrável de poda 7.1/2" Especificações Técnicas Comprimento da lâmina: 7.1/2" (190 mm) Material da lâmina: aço carbono Material do cabo: plástico rígido ABS Número de dentes por polegada: 7 dentes Dimensões: 3,0 cm (L) x 2,0 cm (A) x 32,0 cm (C) Peso: 0,225 kg Por que escolher este produto? Dentes temperados com afiação ultracortante para cortes precisos Sistema de trava que garante segurança no uso Compacto, dobrável e fácil de transportar Ideal para jardinagem, manutenção e uso doméstico Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 45.99, 45.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mfttor1uw2rw68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F22399034410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
