INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399301273', 'Tesoura para Grama Tramontina - 78322/501', 'Um canteiro ou gramado bem aparado é lindo, não é mesmo? E para deixá-los perfeitos é necessário aparar aqueles cantinhos onde o cortador de grama não chega. Foi pensando nisso que trouxemos para você a tesoura para grama Tramontina em aço com cabo plástico que permite cortes mais precisos para um a Diferenciais: - A tesoura é temperada em todo o corpo da peça, proporcionando maior resistência e menor desgaste durante o uso. - Lâminas fabricadas em aço carbono especial de alta qualidade. - Cabo giratório em 360°, com 16 posições de corte que permitem fazer qualquer contorno. - Base de apoio com regulagem de altura, proporcionando um corte uniforme a grama. - Cabos em plástico leves e ergonômicos, proporcionando conforto durante o uso. - Botão de trava que possibilita operar a tesoura com uma só mão. - Possui uma trava de segurança para fechamento das lâminas quando a tesoura não está em uso. - Leve e prática no uso.', 124.87, 99.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mkznwrrmv75s2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F18399301273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
