INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22499034079', 'Supra Luteina + Zeaxantina - 500mg 60 Cápsulas - Herbamed', 'Visão: A Vitamina A e o Zinco auxiliam na visão. Antioxidante: A Vitamina C,E e Zinco são antioxidantes que auxiliam na proteção dos danos causados pelos radicais livres. Imunidade: A Vitamina A,C e Zinco auxiliam no funcionamento do sistema imune. Como Tomar Ingerir 2 (duas) cápsula ao dia. Ingredientes Luteína, Zeaxantina, Vitamina A (Acetato de retinol), Vitamina C (Ácido ascórbico), Vitamina E (Acetato D-Alfa tocoferol) e Zinco (Zinco bisglicinato). Antiumectante: Silicato de Magnésio. Cápsula: Gelificante gelatina, água purificada, umectante glicerina. NÃO CONTÉM GLÚTEN. ...', 40.64, 19.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-825a1-mfv3hqqs5f66c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22499034079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20704499492', 'Conjunto 5 Potes Vidro Herméticos C/ Tampa de Bambu - Oikos', 'COZ02291 - CONJUNTO 5 POTES VIDRO HERMÉTICOS C/ TAMPA DE BAMBU - OIKOS Esse é o conjunto 5 potes de vidro hermético redondo de 600ml para mantimentos com tampa de bambu da OIKOS. Não julgue pelas aparências, ele não é só um potinho bonito: com a combinação da vedação de silicone e o bambu antibactericida, esse pote se torna um verdadeiro mestre na conservação de alimentos! E não é só de comida que vive esse pote: algodão, cotonete, carregadores, dados, jogos, bola de gude, marshmellows, cápsulas de café, itens de costura e o que mais você quiser guardar - isso que é versatilidade. Esse kit é composto por 5 potes de 600ml. Altura: 15cm Largura: 8,5cm', 191.9, 98.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8260v-mle59zi4lu6b19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F20704499492', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
