INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393845894', 'Mochila Feminina Chenson Original Elemento Gráfico 8485091', 'Mochila Feminina Chenson Original Elemento Gráfico 8485091 Confeccionada em PU, material de excelente qualidade, essa linda mochila possui 2 divisões para pequenos objetos. O forro é em tecido personalizado com o logo Chenson. O fechamento principal é feito com zíper personalizado e botão magnético. A alça em PU oferece conforto, e o acabamento em costura contrastante adiciona sofisticação. Acompanha um lindo chaveiro ursinho Chenson, com detalhes em ferragens douradas, complementando o charme do produto. Medidas Aproximadas: Altura: 26 cm Largura: 13 cm Comprimento: 23 cm Cuidados: Guarde em um local seco e arejado, evitando locais úmidos. Evite colocar excesso de peso no produto para não forçar os zíperes e costuras. Proteja os objetos cortantes e/ou pontiagudos, evitando o contato direto com o produto. Evite altas temperaturas. Cores claras podem manchar ao entrar em contato com objetos ou roupas de cores pigmentadas. Dicas de Limpeza: Para a limpeza, utilize apenas pano úmido com sabão neutro. Não mergulhe na água e não utilize componentes químicos, solventes ou alvejantes. Não deixe de molho e seque à sombra.', 366.92, 366.92, NULL, 'Women Bags > Top-handle Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rd5w-m7mor4j9pkzc4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F22393845894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
