INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493108319', 'Torneira Eletrônica Zagonel Prima Touch 5.500W Branca - 110V', 'Primeira torneira com tecnologia TOUCH do mercado nacional, a torneira Prima Touch foi pensada para ser conceito de conforto e funcionalidade desde sua instalação. Traz em seu design linhas elegantes e modernas, com bica giratória, além da possibilidade de instalação em bancada ou parede. Diferenciais Tecnologia One Touch (água na temperatura máxima ou mínima com um toque) Tecnologia Touch Seletor de temperatura em Braille LED indicador de temperatura Fácil troca de resistência Bica giratória 360° Arejador articulável anti-respingo Registro de 1/4 de volta, com pastilha cerâmica Acionamento com baixa pressão d''água (1,5 m.c.a.) 2 em 1: instalação em bancada ou parede Compatível com sistema de proteção DR Compatível com sistema solar e a gás Sistema de proteção contra choque', 453.62, 362.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mlw4t9y7qqkhaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23493108319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
