INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204575922', 'Máscara Capilar Antifrizz Select One Um Só Passo 1L - Prohall', 'Máscara Capilar Antifrizz Select One Um Só Passo 1L - Prohall A Máscara Capilar Antifrizz Select One Um Só Passo da Prohall é um tratamento profissional multifuncional desenvolvido para proporcionar controle absoluto do frizz, hidratação profunda e nutrição intensa em uma única aplicação. Sua fórmula é enriquecida com ativos de alta performance que atuam diretamente na fibra capilar, promovendo disciplina, maciez e brilho radiante. Além disso, ajuda a alinhar os fios, facilita a escovação e protege contra as agressões externas do dia a dia, garantindo um resultado duradouro de salão em casa. Ideal para todos os tipos de cabelo, especialmente os ressecados, volumosos e indisciplinados. Benefícios: Ação antifrizz imediata Hidratação e nutrição intensas Brilho luminoso e toque sedoso Alinhamento e disciplina dos fios Fórmula de alto rendimento em embalagem de 1L', 465.0, 465.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82604-mk9wrzq7jo5h48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F58204575922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094190211', 'Camiseta Venum Predator Vermelho', 'Camiseta Venum Predator – Estilo e Performance em Qualquer Território A Camiseta Venum Predator é mais do que uma peça de roupa — é uma afirmação de identidade para quem vive no ritmo dos combates, dos treinos e da atitude urbana. Produzida 100% em algodão premium, ela oferece o equilíbrio ideal entre conforto, respirabilidade e resistência, seja dentro da academia, nas ruas ou em qualquer momento do seu dia. A estampa frontal, com design marcante e identidade visual agressiva, foi desenvolvida com tecnologia de sublimação, o que garante que as cores nunca desbotem, descasquem ou percam o brilho — mesmo após muitas lavagens. Você veste um estilo duradouro, que acompanha seu ritmo. Com um corte arrojado, mas tradicional, esta camiseta respeita as raízes do esporte de combate sem abrir mão da modernidade no visual. É ideal para quem busca versatilidade sem renunciar à autenticidade. Mais um lançamento da Venum, a maior marca de esportes de combate do mundo e patrocinadora oficial do UFC. A Camiseta Venum Predator representa o espírito dos atletas que enfrentam seus limites todos os dias — dentro ou fora do octógono. Características: 100% algodão premium Estampa sublimada de alta durabilidade Corte confortável com estilo autêntico Ideal para treino, lazer ou uso casual Produto oficial Venum Vença com estilo. Lute com atitude. Vista Venum. CARACTERÍSTICAS TÉCNICAS • SKU: BR-VENUM-4835-015 • Peso: 200 Gramas • Composição: 100% Algodão • Cor: Vemelho • Camiseta: Algodão • Esporte: Treino • Fabricante: Venum Brasil • Gênero: Masculino • Tipo de artigo: Camisetas • User level: Beginner, Intermediate, Advanced', 119.9, 99.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbfqo91thof62a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054067345%2F22094190211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
