INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399499598', 'Soprador De Folhas Costal A Gasolina 2t 42,7cc 1,70hp Potente Vonder', 'Soprador De Folhas Costal A Gasolina 2t 42,7cc 1,70hp Potente Vonder Ideal para limpeza de folhas, grama cortada e outros resíduos em condomínios, clubes, ginásios esportivos, indústrias e prefeituras, o Soprador Costal SCV 427 oferece alta potência e eficiência. Equipado com sistema Easy Start, que facilita o acionamento da partida manual retrátil, e design ergonômico, ele proporciona conforto durante o uso prolongado. Com motor a gasolina 2 tempos de 1,7 cv, vazão de ar de 720 m³/h e velocidade máxima de 260 km/h, é perfeito para grandes áreas. Itens Inclusos 1 Soprador Costal SCV 427; 1 Tubo principal; 3 Tubos para soprador; 1 Frasco para mistura de combustível; 1 Chave de vela; Manual de instruções. Detalhes Técnicos Potência: 1,7 cv/hp; Cilindrada: 42,7 cm³; Vazão de ar: 720 m³/h; Velocidade do ar: 260 km/h; RPM: 7.000/min; Nível de ruído: 109 dB; Tanque de combustível: 1 litro; Peso: 7 kg. Por que escolher este produto? ✔ Produto novo e original; ✔ Pronta entrega e envio em até 24 horas; ✔ Compra 100% segura.', 749.9, 749.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxb-m16d30ovvgb557', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F20399499598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
