INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898901475', 'NEUTROGENA SUN FRESH DERM CARE PROTETOR SOLAR 40 GRAMAS FPS70 FACIAL PELE CLARA MISTA A OLEOSA', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. O que é e para que serve? Protetor Solar Facial Para Pele Oleosa NEUTROGENA SUN FRESH® Derm Care Pele Clara FPS 70, 40g , controla a oleosidade por 12h, com complexo antioxidante rejuvenescedor e efeito matte de longa duração. C/textura ultraleve e sequinha que não derrete. A exclusiva tecnologia HELIOPLEX®XP oferece alta proteção ampla e eficaz contra os raios UVB, UVA e ajuda contra a luz visível. Benefícios e diferenciais: - C/sílica que atua na oleosidade da pele; - Complexo antioxidante rejuvenescedor formado por: -> Niacinamida: ativo clareador de sinais causados pelo sol; -> Feverfew: Poderoso antioxidante; -> Vitamina C: Antioxidante; - Dermatologicamente testado. Não comedogênico e não obstrui poros. Como usar: Aplique abundantemente antes da exposição ao sol. Reaplicar sempre, após sudorese intensa, nadar ou banhar-se, secar-se com toalha e durante a exposição ao sol. *É necessária a reaplicação do produto a cada 2 horas para manter a efetividade da proteção solar. Uso diário. Conservar em local fresco e ao abrigo da luz solar direta. Composição: Octocrylene, Butyl Methoxydibenzoylmethane, Homosalate, Ethylhexyl Salicylate, Ethylhexyl Triazone, Methylene Bis-Benzotriazolyl Tetramethylbutylphenol, Titanium Dioxide, Bis-Ethylhexyloxyphenol Methoxyphenyl Triazine Precauções: Uso Externo. Evite contato com os olhos. Caso isso aconteça, enxágue-os com água em abundância. Descontinue o uso se surgirem irritações na pele. Se a quantidade aplicada não for adequada, o nível de proteção será significativamente reduzido. O produto ajuda a prevenir as queimaduras solares, mas não oferece nenhuma proteção contra a insolação. Evite exposição prolongada das crianças ao sol. Para crianças menores de 6 (seis) meses, consultar um médico. Conserve fora do alcance das crianças. Em contato com tecido, pode causar manchas.', 66.93, 66.93, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-824jb-mekimhtbl15165', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22898901475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797983462', 'Lixadeira de Bancada Eixo Oscilante Elétrica 220v', 'Lixadeira oscilante com mesa de ferro fundido é ideal para dar acabamento nos mais diversos tipos de trabalhos feitos em madeira. Velocidade: 2.000 rpm Potência do motor: 450W Oscilações por minuto: 58opm Mesa de trabalho: 300 x 370 mm Curso oscilante: 16mm Acompanha: 6 lixas, de diâmetros: 13, 19, 26, 38, 51, 76 mm 5 eixos de lixamento de borracha: 19, 26, 38, 51, 76 mm 6 mangas de lixar: 13, 19, 26, 38, 51, 76 mm 4 discos do eixo: 16, 23, 45, 70 mm', 932.8, 932.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7reol-m1wsyee41m4k4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F18797983462', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
