INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42178471715', 'Lovito Men Camiseta Casual Bordada com Listras Gola Contraste Primavera/verão Marrom para Homens. L175ED028', '✅DESTAQUES -❤️BordadoBordado -❤️Listrado -❤️Colarinho Contraste -❤️Macio e confortável -❤️Primavera e verão ✅DESCRIÇÕES Estampa / Padrão:Listrado Estilo:Casual Tamanho Plus:No Material:Poliéster Composição:100%Polyester Tipo de modelagem:Regular Fit Transparência:No Esticar:Medium Stretch Feito na China ✅O PACOTE INCLUI 1XCamiseta ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 69.5, 48.5, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-81zwk-minvpug2acjk2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1619228039%2F42178471715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17518850806', 'Kit Competição Pistão KMP Premium + Anel RIK CRF 230F 2.00mm (67,5mm)', 'Mais torque com equilíbrio para trilha forte Upgrade de cilindrada de 223 cm³ para aproximadamente 244 cm³, com ganho consistente de força e excelente durabilidade. ________________________________________ ✅ Benefícios • Aumento de cilindrada (223cc → 244cc) • Mais torque em baixa e média rotação • Melhor resposta em subida e retomada • Vedação eficiente com anéis RIK • Ideal para trilha e uso mais exigente ________________________________________ 🏭 Qualidade dos componentes Pistão KMP • Alta resistência térmica • Usinagem precisa • Suporta uso severo Anéis RIK • Alta vedação de compressão • Melhor controle de óleo • Redução de desgaste ________________________________________ 🔧 Especificações • Diâmetro: 67,50 mm • Medida: 2.00 • Cilindrada final: ~244 cm³ Conteúdo: • Pistão • Anéis • Pino • Travas ________________________________________ 🏍️ Aplicação CRF 230F — 2007 a 2019 ⚠️ Uso em cilindro retificado (2.00) ________________________________________ 🛡️ Garantia 90 dias + instalação profissional recomendada ________________________________________ ❓ FAQ É um upgrade leve ou forte? Intermediário — ótimo equilíbrio entre força e durabilidade. Serve em cilindro original? Não. Necessário retífica para medida 2.00. O ganho de potência é perceptível? Sim — principalmente em torque e retomadas. Precisa ajustar carburador? Recomendado para obter o melhor desempenho. É indicado para trilha? Sim, ideal para uso off-road e preparação leve. ________________________________________ 🛒 Upgrade ideal para quem quer mais força sem comprometer o motor. Garanta já.', 252.0, 252.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134