INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9747200688', 'Central Multimidia Kit Radio Som Nissan Versa Leaf Tiida', 'Kit Central Multimidia + Câmera de Ré de Brinde Especificação Técnica Multimídia: - Tela 7 Polegadas - Conectividade Bluetooth - Rádio FM - Entrada para Cabo Auxiliar - Suporte para Câmera de Ré - Visor com Data/Hora Digital - Entrada SD (Até 32 GB) - Entrada USB - Led Botões Coloridos - Tela de LED 7 polegadas - Touch Screen - Agenda Telefônica - Compatível com Formato de Música MP3 - Entrada USB, SD e Auxiliar P2 - Capacidade para Pen Drive e Cartão - Auto procura de Estações de Rádio - Equalizador - Potência de Saída: 4 x 25W RMS - Espelhamento iOs e Android via Cabo - Não Acompanha Cabo* - Resolução 800*480 - Entrada para câmera de Ré - Controle Remoto - Idiomas: Chinês , Inglês , Russo , Espanhol e Português. - Dimensões: 180mm * 103mm (7.08 de polegada * 4.06 polegada) - Saídas SWC Para Comando de Volante (Consultar Compatibilidade) OBS¹: Verificar a compatibilidade com a função de comando de volante no manual do veículo. Caso necessite, você deve adquirir a interface à parte. Atenção: Espelhamento IOS pode não funcionar 100% dependendo da atualização de Software do IOS! Não Acompanha Moldura. Somente Multimidia e Brinde. Descrição Câmera de Ré: Acessório de auxílio aos motoristas na realização de manobras, as câmeras de ré possuem constante procura para uso nos mais diversos carros, proporcionando uma visão privilegiada quanto a obstáculos na parte traseira do veículo durante manobras em marcha ré. Neste modelo 2 em 1 de Câmera de Ré, você conta com a versatilidade de escolha sobre a fixação no para-choque ou na placa, além de contar com ótima resolução, baixa necessidade de iluminação e design compacto com apenas 2 cm de diâmetro, para você equipar seu carro com toda a qualidade e segurança. Características Câmera: - Disponível na Cor Preta - Aplicação no Para-choque ou na Placa - Resolução Horizontal: 400TVL - Iluminação Mínima: <0,5Lux - Lentes: 1,8mm - Alimentação: 12V DC - Consumo de Energia: 100mA - Temperatura de Operação: -20 a 70°C - Sistema de Sinal: PAL e NTSC - Pixels Efetivos: 628x586(PAL), 656x492(NTSC) - Área de Sensoriamento: 5,96x4,28mm(PAL), 4,08x10mm(NTSC) - Diâmetro da Câmera: 2cm - Comprimento dos Cabos: 5,5m Conteúdo da Embalagem: - 01 Central Multimídia - 01 Controle Remoto - Chicotes para Instalação - Kit de Instalação - Manual de Instruções - 01 Câmera de Ré Completa Cabo e Acessorios. Garantia de 3 meses / SAC Pós Venda Qualidade Garantida ou seu Dinheiro de Volta!! Todos produtos postados em até 24h!!', 310.4, 310.4, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/57543db31b5cca2de154d5de8b10128c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388235108%2F9747200688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
