INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993344083', 'Kit Invigo Blonde Recharge Shampoo e Condicionador - Wella', 'Este Kit Contém: 1 - Shampoo Blonde Recharge Invigo 250ml - Wella Professionals 1 - Condicionador Blonde Recharge Invigo 200ml - Wella Professionals Sobre o Produto: Kit de Shampoo desamarelador para cabelos loiros coloridos, naturais ou com mechas, com Condicionador revitalizador que mantém os reflexos multidimensionais dos tons loiros frios, nutrindo intensamente o cabelo COM PIGMENTOS DE COR. Modo de usar: Aplicar o shampoo com os cabelos molhados, emulsionar até formar espuma. Enxaguar. Repetir 1 vez e exanguar novamente. Aplicar o condicionador, com os cabelos ainda úmidos, emulsionar mecha a mecha e deixar agir de 3 a 5 minutos. Enxaguar abundantemente. Cuidados/Restrições: Evite o contato com os olhos. Caso isso aconteça, enxágue com água em abundância. Havendo irritação, suspender o uso e procurar orientação médica. Não ingerir. Manter fora do alcance de crianças. Uso externo.', 485.39, 235.46, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdy2-m0m1nlfygsg25d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F22993344083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598659855', 'Phytomanga Butter Oil Ultranutritiva Ação Condicionante 300g - Widi Care', 'Máscara Phytomanga Butter Oil Ultra Nutritiva Ação Condicionante 300g – Widi Care A Máscara Phytomanga Butter Oil Ultra Nutritiva da Widi Care é um tratamento intensivo que oferece nutrição profunda e ação condicionante para todos os tipos de cabelo. Sua fórmula rica em manteigas e óleos vegetais proporciona hidratação, brilho e maciez desde a primeira aplicação. ???? Benefícios Principais Nutrição intensa: repõe os lipídios essenciais, revitalizando os fios. Ação condicionante: facilita o desembaraço e melhora a maleabilidade. Hidratação profunda: combate o ressecamento e a porosidade. Brilho e maciez: deixa os cabelos mais sedosos e luminosos. Versatilidade: indicada para todos os tipos de cabelo e etapas de nutrição do cronograma capilar. ???? Ativos Naturais Manteiga de Manga: rica em vitaminas A e E, nutre profundamente e combate o ressecamento. Extrato de Pitanga: possui propriedades antioxidantes e hidratantes, promovendo saúde aos fios. Óleo de Abacate: fortalece e dá brilho aos cabelos. Óleo de Moringa: rico em nutrientes, revitaliza os fios. Óleo de Argan: hidrata e combate o frizz. Óleo de Coco: proporciona emoliência e brilho. ????‍♀️ Modo de Uso Após lavar os cabelos com o shampoo de sua preferência, aplique a máscara nos fios úmidos, enluvando mecha por mecha. Deixe agir de 5 a 10 minutos e enxágue abundantemente. Para melhores resultados, utilize de 1 a 2 vezes por semana. ???? Informações Técnicas Peso: 300g pH: 3,5 – 4,5 Indicação: todos os tipos de cabelo Fórmula: vegana, sem sulfatos, parabenos ou petrolatos Cruelty-free: não testado em animais', 97.45, 47.11, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ravo-mb5m35nwwh2b08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F22598659855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
