INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11377617945', 'Valvula Termostatica Astra Zafira Vectra 2.0 2.2 2.4 16v MTE', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Flange Valvula Termostatica - MTE APLICACAO: Astra 2.0 / 2.2 / 2.4 16v De 1999 A 2001 Zafira 2.0 / 2.2 / 2.4 16v De 1999 A 2001 Vectra 2.0 / 2.2 / 2.4 16v De 1999 A 2001 DESCRICAO DO PRODUTO: A valvula termostatica atua controlando a saida do liquido de arrefecimento do motor, para que esse liquido seja resfriado pelo radiador, assim controlando a temperatura do motor.', 186.9, 186.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/7a900861779b142fcbf31942fb41da6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F11377617945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192218387', 'Jogo Tapete de Borracha para Carro Toyota Personalizado 4 Peças - Universal', 'Conjunto Tapetes Personalizado Carpete Automotivo Carro Tapete Volkswagen VW GM Chevrolet Hyundai Honda Citroen Mitsubishi Ford Audi Nissan Bordado Otimizado Reforçado Preto Emborrachado Universal Toyota Yaris Etios Corolla Cross Prius RAV4 Hillux Camry Se você quer um produto de qualidade e com um ótimo preço, você encontra aqui. Nossos produtos são enviados em até 24 horas úteis e embalados com muito cuidado para fornecer pra você uma experiência incrível. Nem todo mundo sabe, mas os tapetes do carro estão entre os acessórios essenciais dos quais o dono precisa providenciar a compra. À primeira vista, pode parecer de pouca importância para o funcionamento do carro. A escolha correta dos tapetes é importante para uma boa aderência na proximidade dos pedais. Caso contrário, a cobertura pode escapar de sua posição e ficar escorregando debaixo dos pés do motorista, comprometendo o controle dos pedais. E ainda trazendo um visual com toque moderno e um carro organizado. A sua peça a um clique! Composição: – Fabricado em PVC (Policloreto de vinila), totalmente sustentável. – 100% reciclado e reciclável. – Altamente resistente, ou seja, maior durabilidade. – Sem odor. – Na cor preta. – Base pinada antiderrapante de PVC. – Etiqueta bordada com a identificação do veículo. Dúvidas Frequentes: • Os produtos são novos? R: Só trabalhamos com produtos novos e com garantia. • Como funciona a garantia? R: Nossos produtos têm uma etiqueta de garantia para nosso controle interno, com essa etiqueta verificamos se o produto é nosso mesmo, portanto NÃO tire a etiqueta do produto. • O produto está disponível a pronta entrega? R: Sim, todos os nossos produtos estão no nosso estoque preparado para ser embalado e enviado pra você! Ficou alguma dúvida? Esclareça sua dúvida no campo de perguntas! Ficamos à disposição para esclarecer qualquer dúvida que tenha surgido, faça sua pergunta no campo de perguntas, vamos lhe atender com o maior prazer!', 48.7, 48.7, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkux4cn5smqw02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800059202%2F22192218387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
