INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46053207892', 'Bolsa Bebê Canguru Classic Assento Ergonômico 3 Modos de Uso Apoio Lombar Suporte de Cabeça Aiebao', 'CARREGADOR ERGONÔMICO AIEBAO COM ASSENTO E BOLSOS – MAIS LIBERDADE COM O BEBÊ SEMPRE PERTINHO Tenha as mãos livres na rotina e mantenha seu bebê confortável e seguro. O Carregador Ergonômico Aiebao distribui o peso de forma inteligente, ajusta rápido ao corpo e oferece suporte firme para passeios, tarefas do dia a dia e deslocamentos mais longos. BENEFÍCIOS NO DIA A DIA - Mais mobilidade para pais e cuidadores, sem perder o contato com o bebê - Conforto prolongado com melhor distribuição de peso - Ajuste fácil para vestir, regular e remover, até sem ajuda - Compacto e dobrável: prático para guardar e levar CARACTERÍSTICAS - Assento/banquinho ergonômico que mantém o quadril do bebê em posição adequada, auxiliando na prevenção de displasia - Suporte de cabeça estruturado e acolchoado para mais estabilidade - Tecido respirável, ideal para dias quentes e passeios longos - Mordedor seguro integrado ao tecido, ideal para a fase oral - Bolsos acessíveis para itens essenciais (mamadeira, fraldas, chaves e outros) - Estrutura reforçada com fivelas firmes para mais segurança - Design premium com ajuste ao corpo dos pais e conforto para o bebê MEDIDAS DO PRODUTO - Altura do encosto: 33 cm - Altura do assento: 14 cm - Base do assento: 22 cm - Cinto de fixação ajustável até: 120 cm INDICAÇÃO DE USO - Até 48 meses - Suporta até 36 kg', 219.99, 189.9, NULL, 'Mom & Baby > Baby Travel Essentials > Baby Carrier', 'https://cf.shopee.com.br/file/br-11134207-820mc-mok195h0c0zp8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390278034%2F46053207892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
