INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203251026', 'Kit de Carregamento Turbo MFi 33W | Grifinória Harry Potter', 'Inspirado no universo de Harry Potter, o Kit de Carregamento Grifinória da Coleção iWill representa a união de tradição, potência e design para os fãs mais autênticos da saga. O Carregador GaN 33W Grifinória entrega carregamento ultrarrápido e seguro, ideal para iPhones e outros dispositivos compatíveis. Compacto, eficiente e resistente ao superaquecimento, graças à tecnologia GaN. O Cabo Lightning MFi para USB-C Grifinória é certificado Apple, possui acabamento premium em poliéster trançado e garante transferência estável e segura. O visual traz símbolos clássicos que remetem à escola mais icônica do universo Harry Potter. Um lançamento Harry Potter feito para quem vive conectado — e carrega suas raízes por onde for. Especificações do Carregador: - Porta: USB Tipo C - Potência de saída total: 33W (máx) - Voltagem de entrada: 100-240V (50/60 Hz) - 0.8A - Saída: 5V/3A | 9V/3A | 11V/3A | 12V/2.5A | 15V/2A | 20V/1.5A - Tecnologia GaN (Nitreto de Gálio) para maior potência e eficiência - Proteção quádrupla: OCP (sobrecarga), OVP (sobretensão), OTP (superaquecimento), SCP (curto-circuito) - Garantia: 2 anos - Certificação: ANATEL - Garantia de 2 anos contra defeitos de fabricação. Especificações do Cabo MFi Lightning: - Compatível com iPhones 14 ou inferior - Revestimento em poliéster trançado duplo e termoplástico antidesgaste - Taxa de transferência: 480 Mbps (máx) - 4 camadas de reforço interno com aramida - Testado 20.000 a torção - Velocidade de transferência de dados: 480Mbps - Carregamento rápido com corrente de até 3A - Chip homologado Apple - Comprimento: 1,2m - Certificação MFi Garantia: 5 anos A garantia engloba os 3 meses de Garantia Legal. Imagens ilustrativas. As cores podem variar de acordo com o monitor ou lote de fabricação.', 249.9, 184.9, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjeir9oq2ryab3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013839557%2F58203251026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792569114', 'Máquina Geradora de Fumaça Smoke Injector para Detecção de Vazamentos - Raven', 'Loja do Mecânico - O que você precisa, nós temos! A Máquina Smoke Injector é um equipamento que gera fumaça, de forma segura, para detecção de vazamentos, rachaduras, trincas em mangueiras, tubulações, escapamentos, etc. - Ligado no interior do veículo, também permite verificar se há vazamentos em vedações de porta. - Funciona com fluido. - Alimentação 12V na bateria do veículo - Gabinete em aço, com alça para facilitar o transporte e pés de borracha. - Acompanha 8 adaptadores cônicos para teste de mangueiras, intercooler, escapamentos, etc, além de outros acessórios. - Garantia: 6 meses', 1448.99, 1282.47, NULL, 'Spare Parts and Accessories for Vehicles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rblb-ln1vwtydcyzw23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22792569114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
