INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203364178', 'Rolamento Dianteiro Mitsubishi Pajero Io Tr4 Mirage Colt - IR18074', 'Especificações Técnicas • Marca: IRB Automotive • Cód. OEM: MB808442 / MR449797 • Posição: Roda Dianteira • Integrado com ABS: Não • Tipo de rolamento: Duplo • Cód. de similares: ASH 4074 W6 / ALR-0060 / BAH 0060 / R173.22 / BAH-0060A / VKBC 20026 Medidas: • Diâmetro Interno (mm): 40 • Diâmetro Externo (mm): 74 • Espessura (mm): 36 Aplicações: - Mitsubishi Pajero Io 1.8 (1999 – 2002) - Mitsubishi TR4 1.8 / 2.0 (2003 – 2014) - Mitsubishi Colt 1.6 GLXI 16V (1994 – 1997) - Mitsubishi Lancer 1.6 / 1.8 16V (1992 – 1994) - Mitsubishi Mirage (1991 – 1995) - Nissan Sentra 1.6 / 1.8 / 2.0 16V (2000 – 2006) Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar ano, modelo e se o veículo é com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 79.9, 74.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjiu7ebr3bi9bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F58203364178', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
