INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498329617', 'Limpador de Tecidos em Geral 500mL WAP Limpa Tecidos – Limpeza Profunda e Sustentável', 'Limpador de Tecidos em Geral 500mL WAP Limpa Tecidos – Limpeza Profunda e Sustentável O WAP Limpa Tecidos 500ml é a solução perfeita para limpeza de estofados, tapetes, carpetes, colchões e tecidos em geral. Sua fórmula de pH neutro garante proteção para você, para o tecido e para o meio ambiente, enquanto remove sujeiras orgânicas como poeira, poluição e gordura do corpo. Com fragrância sofisticada de cereja e avelã 🍒🌰, o produto vem pronto para uso. Basta aplicar diretamente na superfície a ser limpa. Para uma limpeza ainda mais completa, utilize o Aspirador de Pó e Água da WAP, obtendo resultados profissionais em casa ou no trabalho. 💎 Destaques do produto: ✅ Limpeza profunda de tecidos, estofados e carpetes ✅ Pronto para uso – sem diluição ✅ Fórmula biodegradável e pH neutro ✅ Fragrância de cereja e avelã que perfuma o ambiente ✅ Seguro para superfícies e meio ambiente ✅ Ideal para uso residencial ou profissional ⚙️ Especificações Técnicas: Tipo: Limpador de estofados, tapetes, colchões e tecidos em geral Indicação: Estofados, tapetes, carpetes, colchões e tecidos Conteúdo: 500 mL Com gatilho: Sim Composição: Tensoativo não iônico, tensoativo aniônico, neutralizante, fragrância, conservantes e veículo Fragrância: Cereja e Avelã pH: 7,0 ± 0,5 (neutro) Biodegradável: Sim Viscosidade: 200 a 400 mm²/s Densidade: 1,090 a 1,120 g/cm³ Validade: 24 meses Código WAP: CP3243 Peso bruto: 565 g Cor: Incolor Garantia: 30 dias Dimensões do produto (C x L x A): 11,5 x 5 x 27,3 cm Exclusivo: Sim 🌿 Soluções de Limpeza e Cuidado com o Ambiente: É WAP!', 48.5, 46.08, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfyadu6g9t6t45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543611227%2F21498329617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
