INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897460050', 'Refil Hydro Boost Neutrogena Water Gel Hidratante 50g', '"O hidratante facial Neutrgena Hydro Boost Water Gel combina uma exclusiva textura ultraleve gel não oleosa, de rápida absorção e refrescante com uma hidratação intensa de 48. Com Ácido Hialurônico, ajuda a restabelecer seus níveis saudáveis de água da pele e estimula a sua renovação, fortalecendo sua barreira natural. Com ácido hialurônico, ele ajuda a restabelecer os níveis saudáveis de água na pele e estimula a sua renovação, fortalecendo assim sua barreira de proteção natural. Tem um textura ultraleve, que é rapidamente absorvida pela pele e não deixa ela pegajosa. Não obstrui os poros, hipoalergênico e oil-free."', 99.19, 99.19, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfs9x3z242kl3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F818390117%2F23897460050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43823440526', 'Spray Finalizador Multibenefícios com Ozônio Skazi - Proteção Térmica e Hidratação Instantânea 250ml', '🌬 Skazi Ozônio – Fluido Multibenefícios com Termoproteção e Hidratação Profunda O Spray Multibenefícios com Ozônio Skazi é um finalizador líquido de alta performance, desenvolvido para revitalizar e proteger os fios contra os danos térmicos e ambientais. Sua fórmula une tecnologia de ozônio com aminoácidos, sericina, arginina e cisteína, promovendo brilho, maciez e reconstrução profunda, sem deixar resíduos e sem pesar. ⸻ 💧 Principais benefícios: • 🔥 Termoproteção contra secador, prancha e modeladores. • 💦 Hidratação imediata e toque sedoso. • ✨ Brilho e vitalidade com efeito antifrizz. • 💪 Reposição de aminoácidos e reconstrução da fibra capilar. • 🌿 Selagem e alinhamento das cutículas, deixando os fios mais disciplinados. • 🌬 Textura leve, ideal para uso diário e todos os tipos de cabelo. ⸻ 💙 Indicado para: Todos os tipos de cabelo — especialmente fios ressecados, danificados ou quimicamente tratados. ⸻ 💡 Modo de uso: Borrife o Spray Multibenefícios com Ozônio Skazi nos fios limpos e úmidos, distribuindo de forma uniforme antes da escovação ou prancha. Também pode ser utilizado nos fios secos para finalizar, alinhar e realçar o brilho. ⚠ Uso externo. Não aplicar diretamente no couro cabeludo. ⸻ 🧴 Resultado: Cabelos protegidos, macios, hidratados e com brilho radiante — com a leveza e tecnologia exclusiva da Skazi.', 69.9, 44.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820mf-mlqybi65wirk22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F725026030%2F43823440526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
