INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23164204154', 'Lovito Férias Conjuntos De Biquíni Ditsy Floral Flowers Conjuntos De Biquíni Para Mulheres LNE50229', '✅DESTAQUES -❤️Flores -❤️Sensação Suave ✅DESCRIÇÕES Estampa: Floral Estilo: Casual Plus Size: Não Material: Poliéster Composição: 90% Poliéster + 10% Elastano Tipo de Caimento: Slim Fit Transparente: Não Elasticidade: Alta Região de Origem: China Continental ✅O PACOTE INCLUI 1X Conjunto ✅APRESENTAÇÃO LOVITO Lovito é uma marca emergente que acredita no poder feminino, comprometida em fornecer opções de roupas modernas e acessíveis para diferentes estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, libertadora e fazer você se sentir bem. Afinal, o melhor acessório para qualquer look é a autoconfiança. ✅OBSERVAÇÕES DE COMPRA Por favor, consulte a sua altura e a tabela de tamanhos antes de comprar. Há 2-3% de diferença de acordo com a medição manual. Todas as fotos de produtos nesta loja são 100% reais. Devido a diferentes luzes e telas, uma sutil diferença de cor e pequenos erros são normais. Siga nossa loja e descubra novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, fale conosco e responderemos o mais breve possível.😊', 81.5, 45.34, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/sg-11134201-7ra3z-m5awz33w5ndjbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F23164204154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21305984506', 'Keravit Pomada Oftalmológica Vetnil', 'MODO DE USAR Aplicar uma camada fina sobre a borda palpebral, 3 a 4 vezes ao dia. Depois de obtida resposta satisfatória, reduzir gradativamente o número de aplicações diárias. Se necessário, realizar prévia limpeza do globo ocular, retirando as secreções porventura existentes. A fórmula especial de Keravit® permite manter sobre o globo ocular e bordas palpebrais uma camada uniforme de medicamento que não é diluída e nem arrastada pela secreção lacrimal, o que assegura a ação prolongada dos princípios ativos. Manter o tratamento por 48 horas após o desaparecimento dos sintomas.', 111.65, 93.29, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/8459dd3a1180fa811884d51eb022aaff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F21305984506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
