INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209712812', 'Chicken Crispy Tradicional Seara', 'O Chicken Crispy Seara é feito com 100% peito de frango, sem hormônios, como estabelece a legislação brasileira. Suavemente temperado com alho, cebola, pimenta branca e alecrim, possui uma casquinha sequinha e super crocante, que transforma cada mordida em um momento especial. * Mantenha congelado a -18ºC para melhor conservação. * Ideal para preparar na air fryer ou forno.', 13.79, 13.79, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mqnekqkl65u327', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F58209712812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
