INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13111955091', 'Tiuran Aerossol 125ml Contra Sarna Fungo Cães e Gatos Duprat', 'TIURAN é indicado para o tratamento das sarnas que acometem os animais domésticos, nas mais diversas regiões do corpo. Na sarcóptica, suas lesões iniciam-se na cabeça e espalham-se pelo corpo do cão, suíno e cabras; nos ovinos localizam-se na cabeça; nos bovinos na região interna das coxas, base da cauda, peito e pescoço; nos equinos localizam-se no pescoço e na cabeça. Na sarna knemidocóptica as lesões localizam-se nos pés e pernas dos frangos, perus e pássaros ? nos psitacídeos, periquitos e papagaios ? além dos pés e pernas, acometem bicos e narinas. Na sarna psoróptica os ácaros atacam principalmente os cavalos, bovinos e ovinos nas regiões de pelos longos. Na sarna corióptica as lesões se localizam nas patas e pernas dos bovinos, equinos e ovinos (além de atacar a região escrotal e o olhos. Na sarna demodécica os ácaros atacam as glândulas sudoríparas dos suínos ocasionando pústulas por toda a pele, assim como nos cães, as glândulas sebáceas. As sarnas otodécica (ataca cães, gatos e outros mamíferos) e psoróptica (ataca cabras e coelhos), acometem o pavilhão auricular desses animais, na Notoédrica as lesões ainda evoluem para a face dos animais.', 66.65, 40.0, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/27706e24d9403b5da2729f2af127495d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F13111955091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
