INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697115313', 'Bíblia Sagrada Com Espaço para Anotações | Letra Grande Leitura Perfeita NVI | Capa Luxo Roxa', 'Quantas vezes estamos na igreja e ouvimos algo tão tocante que queremos registrar, mas não podemos porque não temos onde anotar? Você até gostaria de escrever na própria Bíblia, para que aquela informação complementasse seus estudos bíblicos, mas ela não tem espaço. Esta Bíblia chegou para resolver esse problema. Pensada para você que gosta de registrar comentários e anotações que enriqueçam a compreensão do texto bíblico, Sua Bíblia foi elaborada, agora em letra grande e com textos dispostos em coluna única, para incluir anotações sem prejudicar a leitura das Escrituras. Com papel diferenciado que dá mais destaque às suas anotações e mais visibilidade ao texto, graças à fonte Leitura Perfeita, especialmente desenvolvida pela Thomas Nelson Brasil, esta é a ferramenta ideal para aqueles que desejam aprofundar seu relacionamento com a Palavra. Detalhes do Produto: Editora: Thomas Nelson Brasil Acabamento: Capa Luxo Dimensões: 16 larg. X 24 alt. Número de páginas: 1664', 119.9, 119.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvdk-lirlmtlanthcf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F20697115313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198971134', 'Frescobol de Madeira Revestida Aloha - Verde', 'Para entreter adultos e crianças na praia ou no campo, o Frescobol de Madeira Revestida Aloha é uma ótima opção. Além de ser um esporte muito divertido, é também super saudável e vai colocar todos pra jogar! O kit é composto por duas raquetes em madeira com cabos revestidos em E.V.A para maior conforto das mãos e uma bolinha de borracha para iniciar o jogo assim que o Frescobol chegar na sua casa. Você ainda pode escolher a sua cor preferida entre verde, laranja, azul e vermelho.', 41.0, 41.0, NULL, 'Travel & Luggage > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gx-mfb9ujgu330r31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F22198971134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
