INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17321581733', 'Tinta Spray Lab Color Gold Rose Automotivo 350ml', 'As tintas labcolor são produzidas com matérias-primas de boa qualidade e foram devidamente testadas para perfeito desempenho e qualidade do serviço. -Instruções gerais: Lixe bem a área a ser pintada retirando impurezas e gorduras. Quando necessário aplique primer ou fundo LabColor. Agite bem a lata. Mantendo uma distância de 20 cm do objeto a ser limpado, aplique a tinta em movimentos constantes e uniformes em forma de leque. Aplicar várias demãos, sempre em camadas finas e intermitentes para evitar escorrimento da tinta', 32.9, 31.26, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/a83fee1ea803039f62c31c3953dc9e6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557320114%2F17321581733', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
