INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393698074', 'União Regular 3/8 x 5/16 Hulter HT2UNRED38516P', 'União Regular 3/8 x 5/16 Hulter HT2UNRED38516P Componente essencial para otimizar suas conexões hidráulicas. Desenvolvido pela renomada marca Hulter, este produto oferece qualidade e confiabilidade excepcionais para atender às suas necessidades industriais e domésticas. Projetado para garantir uma conexão segura e eficiente em sistemas hidráulicos. Fabricado com materiais de alta durabilidade, este componente resiste a condições adversas, proporcionando uma vida útil prolongada e desempenho consistente. Este produto versátil é adequado para uma variedade de aplicações, desde sistemas hidráulicos industriais até projetos residenciais. Com um design intuitivo, sua instalação é rápida e descomplicada. Sua facilidade de uso garante que mesmo aqueles sem experiência técnica possam incorporar esse componente em seus sistemas com facilidade, economizando tempo e esforço.', 17.9, 17.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rbk3-m5ynd3rra8owab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22393698074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293732989', 'Calço de Borracha Quadrado com Mini Parafusos 44X35 Hulter HT1CBMI01P', 'Calço de Borracha Quadrado com Mini Parafusos 44X35 Hulter HT1CBMI01P Solução versátil e eficaz projetada para uma variedade de aplicações industriais e domésticas. Composto por borracha durável e resistente, este calço oferece estabilidade e absorção de choque em superfícies irregulares, ajudando a nivelar e proteger equipamentos, móveis e estruturas contra danos. Seu design quadrado proporciona uma base sólida e confiável, enquanto os mini parafusos permitem ajustes precisos de altura, adequando-se a diferentes necessidades de elevação. Além disso, a facilidade de instalação torna este item acessível a uma ampla variedade de usuários, desde entusiastas de bricolagem até profissionais de diversas indústrias. Ideal para uso em ambientes internos e externos, este calço de borracha é uma solução prática para estabilização e nivelamento, tornando-o uma adição valiosa para qualquer kit de ferramentas ou inventário de produtos para venda.', 15.9, 15.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rbku-m644jg5kvkobd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22293732989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
