INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201587196', 'Kit 3 Pinceis N16 Kers Detalhamento Externo E Interno Macio', 'Kit Pincéis de Detalhamento Externo Interno e Delicado Kers Conteúdo: 1 - Pincel para Detalhamento Externo Cerda Agressiva Kers nº16 1 - Pincel para Detalhamento Interno Cerda Macia Kers nº 16 1 - para Detalhamento Interno Delicate Touch Cerdas Ultra Macias Kers nº 16 Pincel para Detalhamento Externo Cerda Agressiva Kers Pincel de Detalhamento Externo Cerda Agressiva é indicada para detalhamento da parte externa do veiculo, como rodas, escapamento, chassis, parafusos, cantos de vidros, motor, grades, cantos de faróis, soleiras, para-choques, cantos do para-brisas, para-lamas, maçaneta da porta, corrente da moto e outros. Adequado para qualquer superfície exterior e interior; Limpa facilmente; Fibras resistentes e fortes para uso duradouro; Resistente à ácidos; Resistente à químicos; Resistente à solventes; Fibras não arrancadas ou derramadas; Enxaguar abundantemente após o uso em água corrente e deixar secar; Pincel tamanho N°16 --- Pincel para Detalhamento Interno Cerda Macia Kers Pincel de Detalhamento Interno Cerda Macia é indicada para detalhamento da parte interna do veiculo, como black piano, fibra de carbono, costura de banco de couro, banco de tecido, partes plásticas, maçaneta, faróis, volante, rádio, saída de ar condicionado, painel, teto, emblemas, grade frontal, botões e outros locais delicados. Adequado para superfícies delicadas interior; Limpa facilmente; Fibras resistentes e fortes para uso duradouro; Fibras não arrancadas ou derramadas; Pincel tamanho N°16 --- Pincel para Detalhamento Interno Delicate Touch Cerdas Ultra Macias Kers Pincel de Detalhamento Interno Delicate Touch Cerda Ultra Macia é indicada para detalhamento da parte interna do veiculo, como black piano, fibra de carbono, saída de ar condicionado, emblemas, botões e outros locais delicados. Adequado para superfícies delicadas interior; Limpa facilmente; Fibras resistentes e fortes para uso duradouro; Fibras não arrancadas ou derramadas; Pincel tamanho N°16', 89.98, 56.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-822yw-mhxjtj1oi2a087', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1228411998%2F58201587196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
