INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493400148', '2 Filtro De Combustivel Partida Fria', 'O Filtro de Combustível para Partida Fria é projetado para garantir o fornecimento adequado de combustível em condições de baixa temperatura. Este filtro atua como uma barreira contra impurezas e partículas, protegendo o sistema de injeção e o motor. Sua função é essencial para otimizar a performance do motor durante as partidas em climas frios, evitando entupimentos e garantindo que o combustível flua de forma eficiente. Características: Filtragem Eficiente: Retém contaminantes, como sujeira e água, que podem comprometer o funcionamento do motor. Resistência a Temperaturas Baixas: Projetado para funcionar de forma eficaz mesmo em condições climáticas adversas, garantindo partidas rápidas e confiáveis. Facilidade de Instalação: Compatível com a maioria dos sistemas de combustível, facilitando a substituição e manutenção. Ideal para veículos que enfrentam temperaturas frias, este filtro é essencial para garantir uma partida rápida e uma operação suave do motor, prolongando a vida útil do sistema de injeção', 19.99, 19.99, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0t47elw861s2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F23493400148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199447284', 'Filtro De Ar Condicionado Asx Outlander CES 0406', 'Filtro de ar condicionado para ASX e Outlander Aplicações específicas consultar a gente antes da compra! Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820li-mmg5fwi316vaa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F20199447284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098474806', 'Capacete Moto Fechado Infantil Liberty 4 Kids Tamanho 54 Menino Menina Cor Preto Criança - Pro Tork', '# Auto Equip # Seja bem-vindo(a)!!! --- Descrição: CAPACETE LIBERTY FOUR KIDS INFANTIL TAMANHO 54 Desenvolvido com materiais de alta qualidade e resistência, o modelo visa fornecer ao usuário maior proteção e conforto. O Capacete Pro Tork New Liberty 4 Kids visa fornecer ao usuário maior proteção e conforto. Fabricado em ABS resistente, possui forro antialérgico e viseira em policarbonato. Viajar pelo mundo sobre duas rodas é ainda melhor quando você tem na sua cabeça um capacete da Pro Tork. Por dentro, você poderá desfrutar da paisagem com uma visão clara e em um espaço confortável e arejado. Do lado de fora, seus companheiros de estrada apreciarão sua alta qualidade e design moderno. De qualquer ponto de vista, a segurança é garantida. Rigidez e segurança é feito com materiais de primeira qualidade que absorvem a energia e lhe conferem maior rigidez. No caso de um impacto, ele lhe dará a proteção que você precisa, amortecendo o golpe em um único ponto. Especificações: - Marca: ProTork;- Cor: PRETO - Injetado em ABS de alto impacto; - Forro antialérgico; - Cinta jugular confeccionado em engate rápido; - Viseira com 1,5mm de espessura; - Viseira em policarbonato de alto impacto com tratamento anti-risco; - Acompanha adesivo refletivo; - Capacete aprovado pelo INMETRO, com selo autenticando; - Fabricado somente no tamanho: 54; - Peso aproximado: 0,925 g; Dicas: - É importante escolher um capacete bem justo, pois a tendência é que ele se alargue com o uso. Portanto, se a sua medida é 56 ou 57 cm, escolha um 56 sem medo. Como fazer a limpeza: - No caso de capacetes sem forração removível, o indicado é utilizar um pano úmido com detergente neutro e passá-lo nas partes internas, depois deixar secar na sombra. Se você deixar secá-lo no sol, a alta temperatura pode danificar os materiais internos do capacete e, por consequência, fazê-lo perder suas propriedades de proteção. IMPORTANTE: Não use produtos em embalagens com aerosol, pois contêm substâncias que danificam os orifícios de ventilação e o visor." Conteúdo da Embalagem: - 01 CAPACETE LIBERTY FOUR KIDS INFANTIL TAM. 54 Importante - Garantia de 03 meses; - Pedidos aprovados até 12h00 de segunda a sexta será enviada no mesmo dia; - Enviamos em até 24h úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - Imagens meramente ilustrativas; - A cor do produto pode variar de acordo com a tela do seu smartphone ou computador; - Utilize o campo de "Perguntas e respostas" e esclareça suas dúvidas com nosso suporte técnico.', 130.9, 109.0, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-7rfg3-m9ogvm9ra2ll34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600306931%2F23098474806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999126334', 'Cama Luuna Bambu, Design Natural, Fácil Montagem, 12 meses de Garantia', 'CAMA LUUNA BAMBU | DESIGN BOHO NATURAL | RESISTENTE E FÁCIL DE MONTAR Uma base que complementa qualquer ambiente — e dura muito mais do que parece. Feita em bambu natural, a cama Luuna une design limpo e contemporâneo com a resistência natural da madeira de bambu. Fácil de montar, compatível com qualquer colchão. PRINCIPAIS BENEFÍCIOS • BAMBU NATURAL — RESISTÊNCIA E APELO SUSTENTÁVEL: O bambu é um dos materiais mais resistentes e renováveis do mundo — a base une durabilidade real com estética natural que combina com diferentes estilos de decoração. • DESIGN MINIMALISTA ADAPTÁVEL: Visual limpo e natural que se adapta a quartos modernos, escandinávos ou boho — sem se impor ao ambiente, complementa sem competir. • FÁCIL MONTAGEM: Estrutura simples e instruções claras para montagem rápida sem ferramentas especiais. • COMPATÍVEL COM TODOS OS COLCHÕES LUUNA: Suporta qualquer colchão da linha — da espuma ao viscoelástico. (Não compatível com a base articulada Rise.) • TAMANHOS: Solteiro 88x188 | Solteiro King 96x203 | Casal 138x188 | Queen 158x198 | King 193x203. ESPECIFICAÇÕES TÉCNICAS • Marca: Luuna • Modelo: Cama Bambu • Material: Madeira de bambu natural • Estilo: Boho / Minimalista / Natural • Tamanhos disponíveis: Solteiro | Solteiro King | Casal | Queen | King • Compatibilidade: Todos os colchões (não compatível com Rise) • Garantia: 10 anos PARA QUEM É INDICADO Indicado para quem valoriza materiais naturais, busca um design minimalista e versátil, ou quer uma base resistente com apelo sustentável para o quarto. DURMA MELHOR COM LUUNA Design que não grita. Material que dura. A base de bambu é para quem quer montar um ambiente bonito e funcional sem abrir mão da qualidade.', 2800.0, 1949.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgfl4aml1j400a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1592293113%2F23999126334', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58264711306', 'Kit Pele de Porcelana FPS20 + Pele de Porcelana + Olhos de Gueixa e Creme Gota de Colágeno Kokeshi', 'Kit com 4 (quatro) produtos: 1 - Pele de Porcelana (Hidratante e renovador facial) 30g 1 - Olhos de Gueixa (Hidratante e renovador para área dos olhos) 15g 1 - Creme Facial com FPS 20 - 30g 1 – Creme Gel Regenerador Facial Gota de Colágeno 45g PELE DE PORCELANA E OLHOS DE GUEIXA Inspirado na cultura asiática que é referência mundial na elaboração de cosméticos, principalmente na Coreia e Japão onde gueixas usavam da matéria-prima do arroz para atingir a perfeição da pele, a Kokeshi Cosméticos traz para o Brasil formulações que são sucesso na Ásia, adaptado ao nosso clima com produtos de qualidade reconhecidos. ATIVOS: Chá Verde (Olhos de Gueixa) Extrato De Mel (Olhos de Gueixa) Sálvia (Olhos De Gueixa) Rosa Mosqueta (Pele de Porcelana / Olhos de Gueixa) Arroz (Pele De Porcelana / Olhos de Gueixa) Panthenol (Pele De Porcelana / Olhos De Gueixa) Óleo Amêndoa Doce (Pele De Porcelana / Olhos de Gueixa) OLHOS DE GUEIXA COMPOSIÇÃO: Water/Aqua, Panthenol, Rosa Canina Fruit Oil, DMDM Hydantoin, Fragrance/Parfun, Cetearyl Alcohol/Sodium Cetearyl Sulfate, Oryza sativa (rice) bran oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Oryza sativa powder, Salvia Officinalis Leaf Extract, Mel Extract, Camellia Sinensis Leaf Extract. Livre de petrolatos e parabenos. MODO DE USAR: Aplicar delicadamente (pequena quantidade) com movimentos partindo do interior para o exterior do contorno dos olhos. Aplicar de manhã e início da noite. PELE DE PORCELANA COMPOSIÇÃO: Aqua, Panthenol, Rosa Canina Fruit Oil, DMDM Hydantoin, Fragrance/Parfun, Cetearyl Alcohol / Sodium Cetearyl Sulf, Oryza Sativa (Rice) Bran Oil, Prunus Amygdalus Dulcis (Sweet Almond) Oil, Oryza Sativa Powder. Livre de Petrolatos e Parabenos. MODO DE USAR: Uso noturno. Espalhe no rosto com a pele limpa e seca até a absorção. Não precisa enxaguar. Uso Diurno: Espalhe no rosto com a pele limpa e seca até a absorção, após utilizar protetor solar. Não precisa enxaguar. PRECAUÇÕES: Em caso de irritação/alergia, enxaguar e suspender o uso. Contêm alérgicos. Conservar em local seco, arejado e ao abrigo da luz. Manter longe do alcance das crianças. CREME FACIAL COM FPS 20 – 30G O creme facial com FPS 20 contribui para proteger e hidratar a pele, promovendo aparência mais lisa, com linhas de expressão suavizadas. Modo De Uso: Aplique no rosto e espalhe com movimentos circulares até a completa absorção. PRECAUÇÕES: ESTE PRODUTO NÃO É UM PROTETOR SOLAR. Uso externo. Não aplicar sobre a pele irritada ou lesionada. Evite o contato com os olhos. Em caso de contato acidental com os olhos, enxaguar abundantemente. Havendo irritação, suspenda o uso e procure por orientação médica. Mantenha fora do alcance das crianças. Mantenha o produto ao abrigo da luz e do calor. COMPOSIÇÃO: Aqua, Octocrylene, Ethylhexyl Salicylate, Homosalate, Phenylbenzimidazole Sulfonic Acid, Glycerin, Butyl Methoxydibenzoylmethane, Caprylyl Methicone, Methyl Soyate, Potassium Cetyl Phosphate, Cetearyl Alcohol, Cyclopentasiloxane, Carbomer, Calcium Starch Octenylsuccinate, PEG-7 Glyceryl Cocoate, Imidazolidinyl Urea, Parfum, Phenoxyethanol, Glyceryl Stearate, Triethanolamine, Ceteareth-20, Cetyl Palmitate, PEG-40 Hydrogenated Castor Oil, Dimethicone Crosspolymer, Polysorbate 60, Hexyl Cinnamal, Caprylic/Capric Triglyceride, Caprylyl Glycol, Linalool, Benzyl Salicylate, Alpha-Isomethyl Ionone, Limonene, Amyl Cinnamal, Coumarin, Citronellol, Oryza Sativa (Rice) Bran Oil, Oryza Sativa Hull Powder, Panthenol, Prunus Amygdalus Dulcis Oil, Rosa Canina Fruit Oil. GOTA DE COLÁGENO 45g Gota de colágeno é um creme gel facial, indicado para todos os tipos de pele, e formulado a partir do óleo de girassol ozonizado combinado ao óleo de copaíba. Benefícios: • Alto poder hidratante; • Regenera o colágeno da pele; • Pele com mais elasticidade; • Ação secativa, tônica e adstringente, auxiliando nos cuidados com a pele oleosa. Modo de usar: De manhã e à noite, com a pele limpa e seca, aplicar com movimentos ascendentes, massageando todo o rosto, pescoço e colo. COMPOSIÇÃO: water/aqua, myristyl alcohol, cetearyl Fabricado por: alcohol/sodium cetearyl sulfate, carbomer, citric acid, disodium edta, propylene glycol, dmdm hydantoin, polysorbate 80, butyrospermum parkii (shea) butter, prunus amydalus dulcis oil, parfum, camphor, menthol, triethanolamine. Kit Pele de Porcelana Kokeshi, Kit Skincare Kokeshi, Kit Cuidados Faciais, Kit Hidratante Facial, Kit Antiidade Facial, Pele de Porcelana, Olhos de Gueixa, Creme Facial FPS20, Gota de Colágeno, Creme Gel Facial, Hidratante para Olhos, Creme para Área dos Olhos, Hidratação Facial, Renovação da Pele, Colágeno Facial, Rosa Mosqueta, Panthenol, Arroz Cosmético, Chá Verde, Extrato de Mel, Pele Lisa, Linhas de Expressão, Rotina de Skincare,Cosméticos Kokeshi, Kit Facial Completo, Cuidados com a Pele, Hidratação Profunda, Elasticidade da Pele, Uso Diário Facial, Skincare Facial', 149.9, 104.93, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-820lp-mqxkekrrcmiv38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395166866%2F58264711306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793486571', 'Medidor De Distância Trena Digital Com Rodas Vonder', 'Medidor De Distância Trena Digital Com Rodas Vonder Construído com matéria prima de alta qualidade, buscando facilitar e deixar seu trabalho mais qualitativo. Com corpo Construído em alumínio, muito resistente e cabo com empunhadura plástica, que deixa a pegada muito ais firme e confortável. A roda do Medidor e Totalizador é de Plástico, porém muito resistente com diâmetro de 100 mm. Sua medida pode chegar ao Maximo de 999,9 Metros. Características Gerais do Produto: Capacidade Máxima de Medição: 999,9 m; Comprimento Do Cabo: Telescópico (43 cm, 65 cm e 88 cm); Diâmetro da Roda: 100 mm; Material: Da roda: plástico com revestimento em borracha termoplástica; Do cabo: alumínio com empunhadura plástica; Números de Dígitos: 04 dígitos.', 201.94, 152.31, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m36o07lym4agf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22793486571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099350090', 'Rack Movelove 2 Portas e 1 Gaveta com Painel para TV 70 Polegadas Sevilla 183cm', 'Rack Com Painel Sevilla Para Tv Até 70 Polegadas 183cm Jequitibá/Off White OConjunto Rack com PainelSevilla é uma excelente opção que irá transformar o seu ambiente, oferecendo praticidade e estilo para o seu dia a dia, produto de alta qualidade desenvolvido pela Lukaliam Móveis há 30 anos no mercado moveleiro. Dimensões do Conjunto Sevilla Montado: Altura 245 cm Largura 183 cm Profundidade 38,40 cm Diferenciais do produto: Tampo em MDP 25mm Prateleira 25mm com regulagem de altura Puxador pontual em ABS Gaveta com corrediça telescopica Pés em madeira maciça Espaço para Tv até 70 Polegadas Produto de Alta Qualidade Estilo e Modernidade Para Sua Sala Acompanha Manual de Montagem OBSERVAÇÕES IMPORTANTES: Produto não deve ficar exposto diretamente ao sol, calor e umidades excessivas. Recomendações de Limpeza: Utilize somente pano seco ou levemente umedecido. O produto pode sofrer alterações de tonalidade conforme o seu monitor. Imagens meramente ilustrativas, produto não acompanha objetos de decoração. Ao receber, verifique a embalagem. Se detectar irregularidade ou violação na mesma, recuse o recebimento e nos contate. Não nos responsabilizamos, no ato da entrega, por subir escadas/elevadores. Nós não nos responsabilizamos pela montagem e por problemas causados pela montagem realizada por você ou montador contratado. Enfatizamos a recomendação aos nossos clientes de contratar um montador profissional. Eventualmente, se faltar qualquer móvel ou acessório no produto, nos contate e enviaremos a móvel/acessório sem custo adicional. A Loja Não Oferece Serviço De Montagem. Todos os nossos móveis possuem manual de montagem com passo a passo para você ou seu profissional de confiança montá-lo. A Loja oferece total apoio e responsabilidade até a entrega do produto ao cliente e também asseguramos o direito de troca e devolução nos primeiros 7 dias após o recebimento do produto. Tudo para garantir a você cliente, conforto e segurança em sua compra.', 1321.06, 989.9, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkds8w4eeygx61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F444869236%2F18099350090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499201393', 'Lancheira Menino Infantil Astronauta Espaço 4734342', 'Lancheira Menino Escolar Infantil Astronauta Espaço 4734342 A Lancheira Escolar Infantil Astronauta Espaço 4734342 combina praticidade e diversão para a rotina escolar. Feita em Nylon600D resistente e fácil de limpar, traz estampa temática do espaço com painel frontal de capacete de astronauta que encanta as crianças. Compartimento térmico para conservar lanches e bebidas. Fechamento em zíper com puxadores personalizados. Bolso lateral em tela para garrafinhas. Alça de ombro ajustávelalça de mão. Material: Nylon600D. Medidas Aproximadas Altura: 21 cm Largura: 14 cm Comprimento: 22 cm 9.0" Polegada Cuidados Guardar em local seco e arejado, evitando umidade. Limpar com pano úmido e sabão neutro; não usar solventes ou abrasivos. Evitar objetos cortantes em contato direto com o interior. Não lavar em máquina nem submergir em água.', 138.4, 138.4, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-822xj-mi0mga3eq8lge6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1690020804%2F23499201393', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899447490', 'Atum Sólido Ao Natural Coqueiro', 'O Atum Sólido ao Natural Coqueiro é feito com o lombo do peixe, a parte mais nobre, garantindo um sabor suave e uma textura macia. Fonte de proteínas, vitamina D e ômega 3, o atum é perfeito para incrementar suas refeições de forma saudável. Ideal para saladas, sanduíches e massas.', 14.79, 14.79, NULL, 'Food & Beverages > Food Staples > Canned Food', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnel4kddektf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F22899447490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259698265', 'Ferrero Rocher', 'Ferrero Rocher oferece uma experiência de sabor única com suas camadas contrastantes: uma avelã inteira, um recheio cremoso de avelã, um wafer crocante coberto com chocolate e pedacinhos de avelã. Cada bombom é embalado individualmente em papel dourado, tornando-o perfeito para presentear. Compartilhe momentos especiais com Ferrero Rocher, seja em datas comemorativas ou como um mimo para você.', 35.99, 35.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8257x-mqnkre04chkx05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555175%2F58259698265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
