INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24939292238', 'BIOHEAL BOH Probioderm 3D Lifeting Cream Essence, 100ml', 'Descrição da descrição Resolva a perda de elasticidade da pele e levante as preocupações com o Probiodermo™ Essência de creme de elevação 3D essência de creme de elevação 3D. Preencha a umidade, construa elasticidade e brilhe brilhantemente! Modo de usar Imediatamente após a limpeza, com a cabeça levemente levantada, feche os olhos 10 ~ 20 cm e pulverize uniformemente em todo o rosto para absorver. Elasticidade umidificada Para elasticidade umidificada: Pulverize perto da pele e espalhe como um creme. Para camadas elásticas e brilhantes: Pulverize como uma névoa com 10 ~ 20 cm de distância da pele. Área alvo: Rosto Tipo de pele: Todos os tipos de pele: todos os tipos de pele', 213.8, 213.8, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-7rfhv-m3lt3q2ru21z21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24939292238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
