INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11690578274', 'Kit 10 Creme Dental Colgate Luminous White Carvão Ativado 70g', 'O Kit contém: 10 Creme Dental Colgate Luminous White Carvão Ativado com 70g cada. A Colgate® Luminous White Carvão Ativado possuí uma nova tecnologia que possui carvão ativado para um sorriso ainda mais deslumbrante, promovendo o branquemaento dos dentes e a remoção das manchas. Possui carvão ativado para um sorriso ainda mais deslumbrante. Promovendo o branquemaento dos dentes. Remoção das manchas. Escove os dentes adequadamente após cada refeição, três vezes ao dia durante dois minutos. Enxágue completamente depois da escovação.', 191.39, 191.39, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/52c29edff59aa26baaeaeacdf59d628e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F11690578274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
