INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11554310093', 'A cigarra e a formiga', 'A cigarra passava os dias cantando, despreocupadamente, enquanto a formiga trabalhava sem parar. O inverno chegará... Quem estará mais preparada para enfrentar essa estação? Acompanhe a história e descubra a importância da solidariedade e da amizade verdadeira._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2021_x000D_ Autor: Ciranda Cultural _x000D_ Idioma: Português_x000D_ Páginas: 12_x000D_ Dimensões: L 28.00 x A 28.00 x E 1.00_x000D_ ISBN: 9786555009804', 12.9, 12.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/24dcc742a43656b506e64ee55a36177a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11554310093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
