INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10354316510', 'O livro dos mártires', 'O Livro dos Mártires é uma crítica rigorosa ao catolicismo e influenciou por séculos a opinião popular acerca dessa vertente do cristianismo na Inglaterra. Nesta obra, John Fox e expõe a perseguição religiosa apresentando a história dos mais importantes mártires cristãos. Iniciando com Jesus Cristo, relata o sofrimento dos protestantes até o término do reinado de Maria I, conhecida como rainha sanguinária por conta das perseguições marianas._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2020_x000D_ Autor: John Foxe_x000D_ Idioma: Português_x000D_ Páginas: 496_x000D_ Dimensões: L 15.50 x A 22.60 x E 2.50_x000D_ ISBN: 9786555521665', 39.9, 39.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/27cb1180fa9204a7a9bce09ade1a376e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10354316510', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17573104991', 'Livro - Dinossauros', 'Prepare-se para fazer muitas descobertas sobre as criaturas mais fascinantes que habitaram a Terra há 65 milhões de anos. Com este livro, você vai aprender curiosidades fantásticas sobre diferentes dinossauros: Velocirraptor, Pterodáctilo, Tiranossauro Rex e muito mais. Use a lanterna mágica para iluminar as páginas e ver as imagens se formarem. Essa aventura vai surpreender você!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2020_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 32_x000D_ Dimensões: L 24.00 x A 26.50 x E 0.30_x000D_ ISBN: 9786555003895', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/9631060ccde3dc28177a8c7e33a91694', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F17573104991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
