INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13967429179', 'Livro - Hot Wheels - Animais e criaturas', 'As pistas que os pilotos Hot Wheels percorrem são animais! Cheias de curvas e com obstáculos complicadíssimos, só um carro veloz é capaz de fazer as incríveis manobras para chegar ao fim da corrida. Divirta-se, enquanto colore os carros e as criaturas que só as pistas Hot Wheels tem._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2021_x000D_ Autor: Paloma Blanca Alves Barbieri_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 35.00 x A 27.00 x E 0.40_x000D_ ISBN: 9788538094838', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/df5097845b2ec5955168ea8927a37ddf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F13967429179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10113483331', 'Livro - A dama de espadas - Principis', 'Em uma roda de amigos em volta de uma mesa de baralho, a história da condessa e do misterioso segredo para vencer no jogo de cartas vem à tona e desperta a curiosidade de ambicioso Hermann. Ele então põe em prática seu plano para descobrir o mistério, mas mal pode imaginar com o que vai se deparar. Editora: Principis Edição: 1, 2019 Autor: Alexandre Pushkin Idioma: Português Páginas: 80 Dimensões: L 15.80 x A 23.00 x E 0.60 ISBN: 9788594318732', 19.9, 19.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/2c10dc82baa428188fc004711015d1e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10113483331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
