INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499207312', 'Espaleira Anantômica 3/4 - 4/4 com Breu para Violino SIEG PREMIUM', 'Kit Contém; 01 Espaleira Anatômica Regulável 3/4 - 4/4 para Violino 01 Breu Sieg Premium Sobre o Breu: O Breu Premium Sieg é um acessório ideal para ser usado em instrumentos de cordas de orquestra como violino e viola de arco ou violoncelo. Além de permitir uma tocabilidade mais precisa, o Breu Sieg proporciona o atrito perfeito entre a corda e o arco possibilitando uma sonoridade com ótima projeção. É um breu feito em resina de goma, cera de abelha natural, óleo de mamona. ESPECIFICAÇÕES TÉCNICAS: -Diminui o atrito entre a corda e o arco -Composição: Resina de goma, cera de abelha natural, óleo de mamona Informações Importantes: _Antialérgico _Não esfarela Sieg Todos os ingredientes naturais combinados a um processo muito especial tornam este breu perfeito tanto para a crina animal quanto a crina sintética. A bonita embalagem adapta-se bem aos estojos e o tecido facilita seu agarramento. Fabricado no Brasil; Peso Total: Aprox. 35g ( somente breu );', 39.95, 39.95, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsil5m4tki7v6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F20499207312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594530061', 'Creme Reparador Calmante La Roche-Posay Cicaplast Baume B5 + FPS50 40ml', 'Creme Reparador Calmante La Roche-Posay Cicaplast Baume B5+ FPS50 40ml – Proteção solar e reparação intensiva para a pele sensibilizada O Cicaplast Baume B5+ FPS50 da La Roche-Posay é um creme multirreparador calmante com alta proteção solar, ideal para peles sensibilizadas, ressecadas ou que passaram por procedimentos dermatológicos. Sua fórmula avançada com Tribioma, Pantenol (vitamina B5) e Madecassoside promove hidratação profunda, alívio imediato e reparação da barreira cutânea, enquanto o FPS50 protege contra os raios UVA/UVB. Indicação Para rosto, corpo e lábios, o Cicaplast Baume B5+ FPS50 é perfeito para quem busca cuidado completo com ação calmante, regeneradora e protetora em um só produto, inclusive para uso pós-sol ou pós-procedimento. Benefícios: - Reparação intensa da pele sensibilizada - FPS50: alta proteção contra radiação UVA e UVB - Ação calmante e hidratante imediata - Ajuda na renovação da barreira cutânea - Textura leve, sem resíduos esbranquiçados - Pode ser usado em áreas com atrito, pós-tatuagem ou exposição solar Principais ativos: - Tribioma: complexo prebiótico que reequilibra o microbioma da pele - Pantenol (Vitamina B5): promove hidratação e acelera a regeneração da pele - Madecassoside: derivado da Centella Asiática, com ação calmante e cicatrizante - Cobre, Zinco e Manganês: complexo com ação antimicrobiana e reparadora Como usar? Aplique o Cicaplast Baume B5+ FPS50 duas vezes ao dia, sobre a pele limpa e seca. Pode ser usado no rosto, corpo e lábios. Evite o contorno dos olhos. Ideal para uso diário em qualquer época do ano. Por que escolher o Cicaplast Baume B5+ FPS50? O Cicaplast Baume B5+ FPS50 une o poder da regeneração intensiva ao da proteção solar de amplo espectro, sendo perfeito para a pele fragilizada por ressecamento, atrito, pós-sol ou após procedimentos. A combinação entre ativos calmantes e fotoproteção torna esse cuidado essencial para manter a pele saudável, protegida e confortável.', 194.4, 194.4, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-82599-mfxzxwjzzwuja1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23594530061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
