INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594446793', 'Sapatilha Infantil Bailarina com Cauda de Sereia com Paetê Pampili', 'Inspirada na magia dos oceanos, essa sapatilha rosa foi pensada para aumentar o conforto e o estilo das meninas de forma lúdica.O fecho em fita aderente em formato de cauda de sereia, coberto por paetês brilhantes que refletem a luz suavemente é o detalhe principal que encanta em cada movimento. O modelo é anatômico, com forro absorvente e respirável que mantém os pezinhos sempre sequinhos e arejados durante o uso. A palmilha macia e o solado emborrachado antiderrapante garantem conforto e estabilidade, ideal para o dia a dia. Além de linda, essa sapatilha infantil promove autonomia com o fecho fácil de ajustar, perfeita para as meninas que já começam a se vestir sozinhas. Com brilho delicado, ela é perfeita para usar tanto de dia quando a noite. Aposte! Combine com vestidos leves e uma tiara divertida para celebrar ocasiões especiais, ou use com um shortinho e camiseta para passeios casuais cheios de conforto.', 159.9, 119.93, NULL, 'Baby & Kids Fashion > Girl Shoes > Flats', 'https://cf.shopee.com.br/file/br-11134207-820me-mmahe783cqgw3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547100334%2F23594446793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
