INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20375555782', 'A Evolução e a Queda | James K. A. Smith', 'A Evolução e a Queda Implicações da Ciência Moderna para a Teologia Cristã A pergunta que sempre é feita: Como ficam as doutrinas da Queda e do Pecado Original se a evolução biológica realmente ocorreu? Há mais de 150 anos, a teoria da evolução biológica proposta por Charles Darwin e Alfred Wallace vem sendo tema de discussão e debate, tanto por seus méritos científicos quanto pelas suas implicações e aplicações em diversas áreas do conhecimento. Mas, sem dúvida, o debate mais acalorado se deve à sua interação com a religião cristã especialmente por causa dos desafios que coloca à tradicional doutrina da Queda e à doutrina do Pecado Original. Se os seres humanos são fruto de um longo processo evolutivo, do qual emergiram como descendentes de primatas não-humanos, qual seriam as implicações para um entendimento cristão das origens humanas e da origem do pecado? Há possibilidade de acomodação para um Adão e Eva históricos no relato evolutivo das origens humanas? Se não, quais as implicações para a doutrina da Queda e para a noção de uma Queda histórica? A evolução e a Queda traz à tona a contribuição de uma equipe multidisciplinar e ecumênica de estudiosos de primeira linha para discutir essas e outras complexas questões que envolvem perspectivas nas áreas de biologia, teologia, história, estudos bíblicos, filosofia e política. Título: A evolução e a queda Subtitulo: Implicações da ciência moderna para a teologia cristã Autor: James K.A. Smith, William T. Cavanaugh, Tiago Garros (Tradutor) Páginas: 320 Formato: 21 x 14 x 1 cm Peso: 440g ISBN: 9786556891798 Editora: Thomas Nelson', 42.81, 42.81, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-sgs2qvlnihovc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20375555782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
