INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262085942', 'Tênis Mizuno Goya 3 - Feminino - Todas as Cores', 'O Produto Nome: Tênis Mizuno Goya 3 Feminino Gênero: Feminino Indicado para: Corrida Material: Têxtil Categoria: Amortecimento Composição: Cabedal: Mesh com material interno em têxtil; Entressola: EVA; Peso: 317g Ref. Núm. 40 (O peso do produto varia de acordo com a numeração) Diferenciais do Produto: Aderência e durabilidade. Solado: Borracha Pisada: Neutra Garantia do Fabricante: Contra defeito de fabricação Origem: Nacional Marca: Mizuno O tênis ideal para te acompanhar em todas as suas atividades. Sua entressola de Eva proporciona mais conforto e seu solado possui borracha garantindo aderência e durabilidade. Além disso, seu cabedal possui um tecido que garante respirabilidade e flexibilidade para os pés.', 329.98, 329.98, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/sg-11134201-823pd-mp71fi2yahak8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F354869565%2F58262085942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
