INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298707185', 'Cooler para Notebook Hp Compaq Presario CQ43-306LA', 'Cooler para Notebook Hp Compaq Presario CQ43-306LA | Interno ste é um Cooler bringIT compatível com o notebook Hp Compaq Presario CQ43-306LA. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.50A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL036-HP-0002', 44.62, 44.62, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mq6rm3radpfy0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23298707185', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
