INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22221488757', 'Condicionador Pet Hydra Groomers Pro Brilho e Desembaraço 5L (1:10)', 'O PRO Brilho e Desembaraço Condicionador possui fórmula exclusiva e extremamente concentrada que permite sua diluição em 10 partes de água, gerando economia e rentabilidade. Contém óleo de semente de uva e extrato de aveia que tem ação hidratante e suavizante. Possui fácil enxágue. Indicações: Indicado para uso profissional em cães e gatos de todas as raças e tipos de pelagem. Modo de Usar: Uso tópico. Banhe o animal com o PRO Shampoo mais adequado e enxágue. Dilua o PRO Brilho e Desembaraço Condicionador em 10 partes de água. Espalhe o produto por toda a pelagem, massageando bem. Enxágue bem. Precauções: Evitar a ingestão ou contato com os olhos. Usar em animais com idade superior a 4 semanas. Manter o frasco fechado, em local seco, fresco e arejado, fora do alcance de crianças e animais domésticos, ao abrigo da luz solar direta. Armazenar longe de alimentos, bebidas, produtos de higiene pessoal e medicamentos. Em caso de irritação, lavar o local com água abundante e suspender o uso imediatamente.', 546.9, 492.21, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbmg-lm6kltxqeok0ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F22221488757', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10461598212', 'Pino Dobradiça Dianteira Traseira Direita Esquerda Para Elba Fiorino Uno Prêmio', 'Comprando até 12h30, enviaremos seu pedido no mesmo dia (em dias úteis). Receba seu produto rápido. Temos garantia de 3 meses e tiramos todas as dúvidas necessárias no chat. Pontos importantes: Pino da dobradiça da porta, essencial para manter a integridade e funcionalidade das portas Dianteira teiras e traseiras. Compatível com diversos modelos da Fiat, incluindo Elba, Fiorino, Prêmio, Uno e Uno Mille. Peça original de qualidade, garantindo durabilidade e desempenho confiável. Ideal para substituir pinos danificados ou desgastados, restaurando a funcionalidade das portas do veículo. Fácil instalação, proporcionando praticidade ao usuário. Aplicação: Compatível com os seguintes veículos Fiat: Elba Fiorino Prêmio Uno Uno Mille Identificação do Produto: Marca: Universal Código Universal do Produto (EAN): 7895272704717 Código IPI: 87082999 Código NCM: 8871 SKU Universal: 70471 Renove a funcionalidade das portas do seu Fiat com o pino de dobradiça original de qualidade. Adquira já e tenha maior segurança e praticidade ao utilizar seu veículo! Estamos à disposição para ajudá-lo no que precisar. Tags e palavras-chave para SEO: Pino Dobradiça, Dianteira teira, Traseira, Direita, Esquerda, Elba, Fiorino, Uno, Prêmio, Peça Original, Acessórios Automotivos.', 18.11, 16.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/8317df8a33fb8b37bd1ac2e4f8f535e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F10461598212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9991117817', 'Kit 2 Óculos Proteção Antiembaçante Incolor Premium Promoção', 'EPI - Óculos de Segurança Modelo Croma Óculos de Proteção com lente e hastes confeccionadas em policarbonato com tratamento antirrisco, antiembaçante e proteção UVA/UVB Tipos de Lente Incolor - Âmbar - Fumê - Verde Produto Certificado – CA 36655 validade 2026 Norma Técnica – ANSI/ISEA.Z.87.1/2015 Indicação de Uso Proteção dos olhos do usuário contra impactos de particular volantes Conservação e Higienização: - Manter em local seco e arejado, protegido da luz solar e de intempéries. - Quando fora de uso, devem ser acomodados em local limpo com as hastes dobradas (fechadas) e com as lentes viradas para cima, para evitar riscos. - Limpar previamente com água corrente, sem friccionar para remoção de poeira. - Caso haja resíduos de gordura, aplica uma gota de sabão neutro e realizar movimentos circulares e enxague até a remoção total dos resíduos. - Secar com pano macio. - Não aplicar nenhum outro tipo de produto químico para não comprometer as características físicas dos óculos. OBS – Não utilizar papel para secar os óculos para não riscá-la Vida Útil Tempo indeterminado desde que a integridade física das lentes, hastes e armação estejam preservadas Aplicação - Clínicas Médicas - Manutenção Industrial - Hospitais - Construção Civil - Laboratórios - Metalúrgicas - Clínicas de odontologia - Esporte e Lazer', 16.58, 14.93, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/br-11134201-820l9-motp889jp05i49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290883399%2F9991117817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
