INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52800325129', 'Relógio Digital Champion Troca Pulseiras CP40977C Prova D''Água 100m', 'O Champion Troca Pulseiras vem com uma caixa metálica de 42mm e 4 pulseiras de plástico em cores incríveis, para você variar e combinar com qualquer look e ocasião. A caixa metalizada e o relógio digital trazem ainda mais elegância e modernidade a este modelo icônico. E o conjunto vem recheado de novidades: - Uma linda caixa, perfeita para presentear - Um cordão para celular ou para incrementar seu visual - Um gancho para pendurar o relógio onde quiser Resistente à água e confortável, ele é o acessório perfeito para quem busca estilo e personalidade Veja as PRINCIPAIS CARACTERÍSTICAS do Relógio Champion Troca Pulseiras Informações Básicas Marca: Champion Modelo: CP40977C Gênero: Unissex Resistência à Água: 10 atm – 100 mts: Pode ser usado para nadar, mar e piscina Medidas do Relógio Tamanho (DIÂMETRO): 4,2 cm (MÉDIO) Espessura: 1,2 cm Comprimento da Pulseira: 18,5 cm Peso: 44 gramas Peso Bruto: 574 gramas Materiais do Relógio Composição do Vidro: Acrílico Material da Caixa: Plástico Material da Pulseira: Plástico Hipoalergênico Material da Tampa: Aço Inox Características do Relógio Mecanismo: Quartz Alimentação: Bateria com vida útil 2 anos Fecho: Fecho Fivela (Buckle) Fundo: Pressão Cores Mostrador: Digital (Led Vermelho) Caixa: Lilás Brilhante Pulseiras: (Lilás Brilhante, Preto, Rosa, Branco) Funções Especiais Calendário Garantia 1 ano de garantia em todo território nacional com a rede autorizada Conteúdo da Embalagem O relógio vai no estojo original, Pulseira Lilás Brilhante, Pulseira Preta, Pulseira Rosa, Pulseira Branca, com a nota fiscal, certificado de garantia e manual de instrução. VAMOS CONHECER MELHOR SOBRE A LOJA RBM RELOGIOS? Somos uma das melhores e maiores lojas de relogios no Brasil. Todos os relógios vendidos pela nossa loja são 100% originais, contém nota fiscal, certificado, manual de instruções e garantia de 12 meses com a rede de assistência em todo o Brasil. Dúvidas? Pergunte, e será um enorme prazer lhe atender!', 599.0, 459.0, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mgdxouu8cidr4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356201012%2F52800325129', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
