INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19869927452', 'Câmara de Ar Michelin 16MD TR4 2.50-16 2.75-16 3.25-16 80/80-16 90/80-16 Nex Intruder 125', 'Descrição: Camara AR Michelin 16 MD para pneus com a medida de (2.50-16, 2.75-16, 80/80-16, 90/80-16). Todas as câmaras de ar Michelin para motos são desenvolvidas na França, seguindo as especificações técnicas e normas de qualidades mais exigidas a nível mundial. O compromisso da Michelin é satisfazer sempre o cliente em conjunto com a comprovada experiência da marca em pneus e câmaras. Características: - Feita com matérias de altíssima qualidade. - Não tem validade. - Não tem limite de velocidade. - Ideal para todo tipo de calibragem. - Indicada para diferentes tipos de pneu. - Para pneus com a medida (2.50-16, 2.75-16, 80/80-16, 90/80-16). Foto Ilustrativa', 157.0, 157.0, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/sg-11134201-22120-0ldnuqgwymlv21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F912455413%2F19869927452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498035094', 'Kit Cadiveu Professional Açaí Oil 110 Extra (2 unidades)', 'Kit Cadiveu Professional Açaí Oil 110 Extra (2 unidades) Este Kit Contém Cadiveu Professional Açaí Oil - Óleo Capilar 110ml (2 unidades): é responsável por restaurar, nutrir e proteger os cabelos danificados, deixando-os macios, brilhantes e flexíveis com proteção térmica. Conselho de Aplicação Oil: aplique uma pequena quantidade nas palmas das mãos e espalhe sobre todo o comprimento dos fios limpos e úmidos. Pode ser utilizado também nos cabelos secos.', 171.75, 144.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rcc1-m68glsn953yw12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F19498035094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698118204', 'Acquaflora Sequestra Metal - Spray Pré-Química 250ml', 'Acquaflora Sequestra Metal – Spray Pré Química 250ml O Spray Pré-Química Sequestra Metal Acquaflora foi desenvolvido exclusivamente para proteger os cabelos durante os procedimentos de coloração, mechas ou descoloração. Sua formulação é constituída por moléculas naturais obtidas do limão, maçã e pepino + complexo inteligente que neutralizam e removem os íons metálicos e as toxinas depositadas na fibra capilar. Fortalece os fios evitando o emborrachamento, diminuindo o risco de quebra e conferindo hidratação. O resultado são cabelos mais resistentes e com maior vibrância na cor. Conselho de Aplicação Aplicar nos cabelos secos antes dos procedimentos de coloração, mechas ou descoloração. Divida os cabelos em quatro partes e aplique o Spray Pré-Química Acquaflora uniformemente do couro cabeludo às pontas. Realize o procedimento de coloração, mechas ou descoloração como de costume. Após o tempo de pausa, enxágue bem os cabelos e aplique o Shampoo Sequestra Metal Acquaflora para higienizar os fios. Em seguida, utilize o Tratamento Condicionante Sequestra Metal Acquaflora para hidratar e reestabelecer o pH. Finalize com o Leave-In Sequestra Metal Acquaflora para proteção prolongada.', 112.8, 64.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82624-mkv3rwjpvg1sec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F18698118204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694046590', 'Bio Extratus Umectante Óleo de Coco Condicionador 1L', 'Bio Extratus Umectante Óleo de Coco Condicioandor 1L Condicionador Bio Extratus Umectante oleo de Coco para cabelos desidratados. Traz todo o poder do oleo de coco em uma mistura única de ingredientes que vai tratar de dentro para fora. O resultado e hidratação maxima, nutrição profunda e reparação dos danos. Modo de Usar: Conselho de aplicação Após lavar os cabelos, aplique o condicionador por toda extensão dos fios, massageando suavemente, deixe agir por alguns minutos e enxágue. Benefícios: - Possui um óleo com alta emoliência, que nutre, hidrata, promove brilho e saúde. - Reconstroem o fio de dentro pra fora, uniformizando sua textura.', 231.4, 231.4, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ratx-ma482qi2o24vae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22694046590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198287040', 'Floracyd Ciclos da Mulher Brisa - Sabonete Líquido Íntimo 200ml', 'Floracyd Ciclos da Mulher Brisa - Higiene Equilibrada com Frescor Prolongado Oferece higiene delicada diária, com fórmula suave e tecnologias prebiótica e probiótica que equilibram a flora vaginal. Proporciona frescor e proteção por até 24 horas, é hipoalergênico, testado dermatológica e ginecologicamente, sem corantes para minimizar irritações. Conselho de Aplicação Aplique uma pequena quantidade na região íntima externa durante o banho, massagear até formar espuma e enxaguar abundantemente. Uso diário recomendado.', 42.9, 26.9, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-824j5-me8t0kzn198m2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21198287040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799127070', 'MACAQUINHO FITNESS FEMININO COM DECOTE QUADRADO LOGOMANIA REFLECTIONS DLK', 'Macaquinho Fitness Feminino Com Decote Quadrado Logomania Reflections Design e Funcionalidade Se você busca desempenho, proteção e sofisticação nos seus treinos, o Macaquinho Fitness Feminino Com Decote Quadrado é a escolha perfeita. Com design moderno e alças largas para maior conforto, ele se ajusta perfeitamente ao corpo, sendo ideal para te acompanhar em suas atividades físicas. Conforto e Proteção UV Feito em tecido super macio, este Macaquinho Fitness possui o fundo opaco com textura da logomania brilhante. O tecido traz sofisticação e modernidade ao seu look de academia, enquanto o toque suave oferece o máximo de conforto. A modelagem garante liberdade de movimento e muita elegância durante o seu treino. Além disso, este macaquinho oferece proteção UV 50+, ideal para você realizar os seus exercícios ao ar livre com segurança e tranquilidade. Seja na academia, corrida ao ar livre ou em treinos intensos, ele oferece a combinação perfeita entre estilo, funcionalidade e conforto.', 149.99, 149.99, NULL, 'Women Clothes > Jumpsuits, Playsuits & Overalls > Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-8259w-mgdpq2852yh6b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F23799127070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398406532', 'Mesa de Jantar Orgânica 6 Lugares Off White/Freijó - Dalla Costa', 'Descrição: A Mesa de Jantar TM88 combina design sofisticado e funcionalidade para transformar seu ambiente. Com formato orgânico e linhas curvas elegantes, ela acomoda até 6 lugares com conforto. Sua estrutura é fabricada em 100% MDF de 18mm, garantindo resistência e durabilidade. Pintura UV em Freijó realça os tons quentes, enquanto o tampo em Off White traz um toque contemporâneo e sofisticado. Ideal para compor salas de jantar modernas e aconchegantes. A compra do produto não acompanha montagem/desmontagem. Cadeiras e objetos decorativos não acompanham o produto. As cores dos objetos podem sofrer alterações devido à luminosidade, configurações do monitor e até mesmo a percepção do usuário. Imagens meramente ilustrativas. Características: - Material da Estrutura: 100% MDF - Espessura da Estrutura: 9 mm e 18 mm - Possui Gavetas?: Não - Possui Portas?: Não - Possui Espelho?: Não - Possui Prateleiras?: Não - Possui Puxadores?: Não - Possui Pés?: Sim - Quantidade de Pés: 4 - Material dos Pés: MDF - Possui Rodízios ?: Não - Linha: Lisboa - Tipo: E-commerce - Necessita de Montagem: Sim - Grau de Dificuldade da Montagem: Médio - Sistema de Montagem: Parafusos, cavilhas e Minifix. - Pode Ser Montado Invertido?: Não - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Escala de brilho: Fosco e Brilho - Garantia (dias): 180 - Indicação de Uso: Sala de Jantar - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. Imagens meramente ilustrativas. Produtos do mesmo modelo ou de modelos diferentes podem apresentar variações de tonalidade. - Recomendação de Manutenção: Para conservar a cor e os aspectos originais do produto, leve em consideração: Levantar a peça ao deslocá-la, o que ajuda a evitar danos à base e aos pés; Não utilizar água em abundância na peça, somente um pano levemente umedecido para a limpeza ou um espanador seco; Utilizar panos preferencialmente brancos, para evitar manchas e seque bem o móvel após a limpeza; Utilize somente água, nunca produtos químicos, abrasivos, solventes, ceras, sabonetes não neutros ou produtos de limpeza doméstica, visto que podem danificar o acabamento; Não coloque objetos quentes diretamente em cima do móvel para não causar bolhas, manchas ou outros danos, opte por utilizar um apoio; Se possível, não exponha sua peça diretamente ao sol, utilize cortinas ou persianas para bloquear os raios de luz, para que a pintura não desbote. Esses cuidados são muito simples e auxiliarão seu produto a permanecer em perfeito estado por muitos anos. - Revestimento /Acabamento: Pintura UV - Formato da Mesa: Oval - Acompanha Cadeiras: Não - Quantidade de Lugares: 6 - Acompanha Tampo: Sim - Material do Tampo: MDF - Peso Suportado no Tampo: 40 kg - Possui Vidro: Não - Vidro Temperado: Não', 669.8, 669.8, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7reot-m8glz72zyhld65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226105437%2F22398406532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45607788511', 'Óculos de Sol Hexagonal Premium Dourado e Preto Classico Virginia Tendencia Blogueira Elegante uv400', '', 99.99, 59.99, NULL, 'Fashion Accessories > Eyewear > Sunglasses', 'https://cf.shopee.com.br/file/br-11134207-820le-mmatdemrxgcneb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009389128%2F45607788511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42011644133', 'Tênis Infantil Menino Kidy Original Baby Primeiros Passos Conforto Macio Equilíbrio Anatômico', 'O Tênis Kidy Equilíbrio Preto e Laranja é ideal para meninos que estão começando a dar seus primeiros passos com segurança, conforto e muito estilo. Desenvolvido especialmente para a fase inicial da caminhada, este modelo une visual moderno com tecnologias que cuidam do desenvolvimento saudável dos pezinhos. O solado em TR é superleve, flexível e antiderrapante, garantindo mais firmeza e estabilidade a cada passo. O fechamento em fita adesiva proporciona um calce prático e um ajuste seguro, facilitando o dia a dia dos pais. A tecnologia Equilíbrio foi criada para dar mais sustentação e apoio aos pés em formação, incentivando um caminhar natural e seguro. Além disso, o design anatômico oferece conforto prolongado para que os pequenos brinquem e se movimentem com liberdade. Um calçado pensado nos mínimos detalhes para acompanhar com carinho os primeiros passos das crianças. Kidy: cuidando do equilíbrio desde o início da jornada.. Formato Anatômico Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico que auxilia no crescimento e desenvolvimento saudável dos pés. Tamanhos: do 16 AO 22 ; Fechamento: Calce Facil ; Cabedal: Sintético ; Forro: Têxtil ; Palmilha: EVA ; Sola: TR ;', 149.99, 135.0, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjiilwg2blkxb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F42011644133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43019513562', 'Tênis Infantil Menino Kidy Energy Baby Respitec Calce Fácil Slip On Leve Confortável Antiderrapante', 'O Tênis Kidy Energy Baby Respitec foi desenvolvido especialmente para acompanhar os pequenos em cada descoberta. Com calce fácil, ele proporciona praticidade para os pais e autonomia para as crianças. Seu solado em TR antiderrapante garante muito mais segurança e andar estável nos primeiros passos, enquanto o design anatômico e flexível cuida do desenvolvimento saudável dos pezinhos. Além disso, conta com a tecnologia Respitec, que proporciona maior respirabilidade e conforto térmico, mantendo os pés sempre fresquinhos durante as brincadeiras. Ideal para os pais que buscam um calçado moderno, seguro e cheio de benefícios para o dia a dia infantil! Formato Anatômico Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico que auxilia no crescimento e desenvolvimento saudável dos pés. Tamanhos: do 22 AO 27 ; Fechamento: Calce Facil ; Cabedal: Têxtil; Forro: Têxtil ; Palmilha: EVA ; Sola: PVC ;', 169.99, 146.29, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfsjd7m55qtja9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F43019513562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
