INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293981324', 'Cervejeira Venax Blue Light 209 Litros Preto Porta Invertida - 220V', 'Cervejeira Venax Blue Light 209 Litros Preto Porta Invertida - 220VÉ a escolha ideal para quem busca praticidade, design moderno e eficiência na conservação de bebidas. Seu diferencial está na porta com abertura invertida, que abre da direita para a esquerda, proporcionando mais liberdade para instalação em diferentes ambientes. Com capacidade para até 204 latas de 350ml, 148 latas de 473ml, 108 long necks de 355ml, 71 garrafas de 600ml ou 40 garrafas de 1 litro, esta cervejeira atende perfeitamente a diferentes necessidades de armazenamento. O sistema de refrigeração por compressor, aliado ao gás ecológico R134A e ao isolamento térmico em poliuretano, garante um resfriamento potente e estável, com controle de temperatura digital regulável de 6°C a -6°C. A porta de vidro duplo Low-E com aquecimento reduz a formação de condensação e preserva a visibilidade interna, enquanto o puxador em alumínio escovado reforça a estética sofisticada do equipamento. A iluminação interna em LED azul oferece um visual moderno e facilita a visualização das bebidas, mesmo em ambientes com pouca luz. Pensando na funcionalidade, a cervejeira Venax conta com quatro prateleiras reguláveis que se adaptam a diferentes tamanhos de embalagens, pés frontais ajustáveis e traseiros com rolete para facilitar o deslocamento, além de sistema de degelo automático com dreno traseiro e recipiente para coleta. Tudo isso aliado à robustez e tecnologia que fazem deste modelo uma excelente opção para quem valoriza desempenho, praticidade e estilo na conservação de bebidas.', 4402.17, 4402.17, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mkl91har6329ca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23293981324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
