INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798345402', 'Bolsa Pasta Pequena Transversal Náilon Executiva Up4you', 'Apresentamos a Bolsa Executiva Modelo EX20075UP, projetada para combinar funcionalidade e estilo em qualquer ocasi?o. Com um design social e confeccionada em nylon resistente, essa bolsa ? a escolha perfeita para o uso di?rio, seja no trabalho ou em momentos de lazer. Ela conta com um bolso frontal com z?per para f?cil acesso aos itens essenciais e um bolso interno com z?per para manter seus pertences organizados com seguran?a. A al?a transversal ajust?vel e a al?a de m?o resistente garantem conforto e versatilidade durante o uso, oferecendo duas formas pr?ticas de carregar a sua bolsa. O acabamento com detalhes em ouro light e o elegante logo em metal light adicionam um toque sofisticado ao design, tornando-a ideal para quem busca praticidade com um toque de eleg?ncia. Caracter?sticas principais: Modelo: EX20075UP Bolso frontal e interno com z?per Logo em metal light e detalhes em ouro light Dimens?es: 21x16x5,5 cm Material: Nylon resistente Cuidados com a sua Bolsa: N?o lave na m?quina. Evite esfregar ou usar produtos qu?micos. N?o passe ferro ou utilize secadora Limpeza: Mantenha sua bolsa sempre impec?vel utilizando apenas ?gua e sab?o neutro. Passe um pano macio para remover a sujeira e preservar o tecido. Se voc? procura um acess?rio resistente e sofisticado para acompanhar o seu dia a dia, essa bolsa executiva ? a escolha perfeita!', 59.9, 59.9, NULL, 'Travel & Luggage > Luggage', 'https://cf.shopee.com.br/file/sg-11134201-825bd-mqs11pztombz15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F23798345402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
