INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10021856171', 'Livro - A Cidade das Esmeraldas de Oz - Capa comum - Principis', 'Os tios de Dorothy estão com problemas na fazenda. Eles não têm dinheiro suficiente para pagar todas as contas e podem ser expulsos. Dorothy os convida para morar em Oz com ela, e Ozma concorda com a ideia. Então, mais uma vez, nos encontramos na bela Terra de Oz, onde Dorothy passará por grandes façanhas e conhecerá novas pessoas. A Cidade das Esmeraldas de Oz é o sexto livro de L. Frank Baum ambientado na Terra de Oz e a sequência de A estrada para Oz. Editora: Principis Edição: 1, 2021 Autor: L. Frank Baum Idioma: Português Páginas: 192 Dimensões: L 15.50 x A 22.60 x E 1.00 ISBN: 9786555523058', 24.9, 24.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/9c51525e96410de414eacacc428f3c92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10021856171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26138570172', 'Livro Cartonado When I Feel Scared W.Books', 'How are you feeling today?_x000D_ Children experience all kinds of feelings in a single day, but they can’t always name them or talk about them easily._x000D_ This essential series focuses on the six major emotions experienced by very young children. Each book uses non-gendered characters to illustrate, identify and talk about a single feeling, suggesting coping strategies where relevant._x000D_ Perfect for developing empathy, resilience and a positive sense of self._x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Child s Play_x000D_ Ilustrador: Paula Bowles_x000D_ Idioma: Inglês_x000D_ Páginas: 12_x000D_ Dimensões: L 20.30 x A 20.30 x E 1.00_x000D_ ISBN: 9786552940957_x000D_ Coleção: Primeiras emoções/First feelings_x000D_ Linha Editorial: W. Books - Infantil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Emoções, Sentimentos, Medo, Inglês_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Temas Sociais / Emoções e Sentimentos_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Cartonado', 19.9, 13.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdyo-mc0pm7qnqnny12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26138570172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
