INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094723693', 'JMJN Ventilador Portátil com Recarga Solar e Power Bank - Fácil de Carregar, Ideal para Acampamentos e Viagens', 'Descrição do Produto: Ventilador Portátil com Recarga Solar e Função de Power Bank‌ Apresentamos o ventilador portátil mais versátil e conveniente do mercado! Com recarga solar e a capacidade de carregar seu smartphone, este ventilador é a solução perfeita para acampamentos, viagens, ou mesmo para uso diário em casa. ‌Características Principais:‌ ‌Recarga Solar:‌ Com painel solar integrado, este ventilador pode ser recarregado usando energia solar, economizando energia e sendo ecológico. ‌Power Bank:‌ Não só é um ventilador, mas também funciona como um power bank, permitindo que você carregue seu smartphone ou outros dispositivos eletrônicos em qualquer lugar. ‌Portátil e Leve:‌ Projetado para ser leve e portátil, você pode levá-lo facilmente para qualquer lugar, seja para acampar, viajar ou apenas para usar em casa. ‌Fácil de Usar:‌ Com controles simples e intuitivos, você pode ajustar a velocidade do ventilador e monitorar o nível de bateria com facilidade. ‌Design Durável:‌ Construído com materiais de alta qualidade, este ventilador é resistente e durável, garantindo um uso prolongado. Não perca a oportunidade de adquirir este ventilador multifuncional e ecológico. Compre agora e desfrute do conforto e da conveniência que ele oferece!', 300.0, 135.99, NULL, 'Mobile & Gadgets > Accessories > USB & Mobile Fans', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhtuwu5n93ba2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430000636%2F22094723693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
