INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593107004', 'Diário de uma garota nada popular 13', 'É o aniversário de Nikki! E uma data especial merece uma festa épica, mas as coisas não saem bem como a menina planejou... Depois de conquistar o público brasileiro, Nikki Maxwell&#160 compartilha mais um&#160 volume de seu&#160 Diário de uma garota nada popular, que já vendeu milhões de copias no mundo todo. &#160 É aniversário da Nikki no volume 13 da série best-seller Diário de uma Garota Nada Popular! Nikki e suas melhores amigas, Chloe e Zoey, estão planejando uma festa de proporções épicas! Só tem um problema: A mãe dela disse que não vai liberar a grana necessária para que a festa aconteça. Nikki está pronta para cancelar os planos, mas algumas reviravoltas do destino podem tirar essa decisão de suas mãos, e a ajuda acaba vindo da pessoa que ela menos espera. De um jeito ou de outro, este será um aniversário que a Nikki nunca vai esquecer! Da série que já conquistou milhares de meninas (e meninos também!) Pelo Brasil, com&#160 milhões de&#160 exemplares vendidos,&#160 Diário de uma garota nada popular&#160 traz novas aventuras de Nikki e seus amigos para cativar e divertir o leitor ainda mais.&#160 Se aventure com essa vida escolar nada fácil e deixe o seu lado nada popular brilhar ainda mais!', 57.9, 57.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd3l-lwszo744hjdeee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23593107004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
