INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697707235', 'Amplificador Receiver 250W RMS Bluetooth USB RCA Classe D Bivolt THS 4600 Taramps - 900885', 'Amplificador receiver 250W RMS, bluetooth, som ambiente, USB, RCA, Classe D, Bivolt Ths-4600 Taramps - 900885 O THS 4600 é um Receiver Multicanal desenvolvido pelo Grupo Taramps com tecnologia para integrar diferentes ambientes. Compacto e potente, pode ser usado em som ambiente para lojas, comércios, clínicas, área de lazer, espaço gourmet, dentre outros, promovendo uma sonorização de alta qualidade. Com suas diversas opções de entrada de áudio, como BLUETOOTH, AUX e USB, é bivolt automático podendo ser ligado em qualquer tomada entre 90 e 240V, atingindo uma potência de total de 250 Watts RMS, sendo dois canais de 125 Watts RMs à 4 ohms. Além de todas essas funções, conta com proteção de baixa impedância e uma saída LINE OUT que permite enviar o sinal de áudio não amplificado para outro equipamento, como por exemplo um subwoofer ativo. Modernidade, tecnologia e qualidade para que seu ambiente seja cada vez mais confortável. Características: - Marca: Taramps - Modelo: 900885 *Imagens meramente ilustrativas. Especificações técnicas: - Potência: 250W RMS - Entradas: Bluetooth, USB, MicroSD, Radio FM, AUX frontal e traseira, RCA, microfone, ótica - Impedância nominal de cada canal: 4 Ohms - Impedância de entrada MIC: 2,2K Ohms - Alimentação: Bilvolt (Automático) - Peso: 1,97 kg - Dimensões Aproximadas: 38,6 x 5,9 x 18,0 cm Conteúdo da Embalagem: - 1 Amplificador receiver 250W RMS, bluetooth, som ambiente, USB, RCA, Classe D, Bivolt Ths-4600 Taramps - 900885', 1158.66, 1042.79, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-lyp8cn9akeb8fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F22697707235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
