INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697763628', 'Guarda-Roupa de Canto Reto 1 Porta Kappesberg Adapt Nogueira/Azul Profundo 100cm', 'Para quem sempre sonhou com um quarto planejado, o Modulado Adapt da Kappesberg é a escolha ideal. Produzido em MDP, material de alta qualidade, o módulo de Canto Reto N530 é ideal para todas as composições, otimizando espaço e garantindo ainda mais beleza. Com uma porta e seis prateleiras, ele é ideal para guardar peças de roupa dobradas e calçados, deixando seu espaço sempre organizado. E com pintura de sete camadas, ele conta com uma combinação de cores única e muito moderna, entre o Nogueira e Azul profundo, combinando facilmente com todos os ambientes, além de garantir a sensação de aconchego e conforto. Os destaques ficam por conta do sistema de amortecimento na porta, proporcionando um fechamento suave e sem ruídos, e do puxador em MDF, que completam os diferenciais do produto. Renove seu quarto com toda a qualidade e beleza que o Modulado Adapt da Kappesberg oferece e aproveite cada momento. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1792.18, 1099.99, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-8261g-mm9d6vl077yb7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F22697763628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
