INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11962912412', 'Papete Infantil Menino Sandália Casual Calce Fácil 15.01i', 'Papete é um modelinho clássico que sempre está presente na vida dos pequenos! Além da praticidade, conforto e a segurança que nossos calçados oferecem. DESCRIÇÃO Confeccionado em tecido, com forração super confortável e palmilha em EVA de excelente qualidade. Possui solado antiderrapante, dando maior aderência em cada passo e com fechamento fácil, para mais praticidade no dia a dia. DETALHES DO PRODUTO Material Externo: Tecido Material Interno: Tecido Material da Palmilha: EVA Material da Sola: PVC Micro Expandido Fechamento: Calce fácil Embalagem: Caixa individual Nós da Pópidi cuidamos com carinho da relação pré e pós-venda, afinal a satisfação de nossos clientes é muito importante para nós! Atendimento: Segunda à sexta: 07:00 às 19:00 Sábado: 09:00 às 13:00 TABELA DE MEDIDAS 22 --- 15,0 cm 23 --- 15,5 cm 24 --- 16,0 cm 25 --- 16,4 cm 26 --- 17,5 cm 27 --- 18,0 cm COMO MEDIR Coloque o pé em cima de uma folha de papel e risque em volta dele com um lápis ou caneta. Meça o comprimento do topo até a base do contorno e adicione 0,5 cm de folga. LIMPEZA E CONSERVAÇÃO Evite usar substâncias abrasivas como álcool, detergentes ou solventes nos calçados. Nunca os mergulhe na água, os deixe de molho ou lave na máquina. A secagem dos produtos deve ser feita à temperatura ambiente e na sombra, nunca no sol ou em máquinas. SOBRE A EMPRESA VISÃO Estar em constante expansão e inovação, de uma forma consistente e arrojada. MISSÃO Proporcionar o bem-estar dos nossos clientes, satisfazendo-os em um ambiente agradável e cortês com produtos a preços justos e de qualidade. VALORES Respeito, Dedicação, Conexão e Atitude. Boas compras e volte sempre!!!', 79.9, 69.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcb0t7tx71ez6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318839552%2F11962912412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
