INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50550536322', 'Giz de Cera Retrátil Para Banho c/ 2 cápsulas de esponja surpresa Leo&Leo Leonora - 10224', 'O Giz de Cera Retrátil para Banho com 2 Cápsulas de Esponja Surpresa Color Joy - Blister com 6 Cores Leo&Leo é um verdadeiro mergulho no mundo da diversão. Este é um novo jeito de transformar o banho dos pequenos em um momento de criatividade e alegria. Atendendo às necessidades das crianças com sensibilidades sensoriais, o giz retrátil para banho Color Joy foi projetado para deixar a hora do banho mais agradável e divertida. Cada giz de cera vem com uma capa de plástico resistente e um mecanismo retrátil protege a ponta. Além dos gizes coloridos, este produto incrível inclui duas cápsulas surpresas que, ao serem imersas em água quente, se transformam em esponjas de limpeza. Não conte para as crianças antes, mas elas vêm em forma de animais - um pato amarelo e uma baleia azul. Assim, os pequenos vão poder desenhar no boxe do banheiro, com um giz ergonômico na hora de escrever e depois limpar com as esponjas. Porque no Mundo Leo&Leo a diversão precisa fazer parte do universo de toda a criança. Características: 6 gizes de cera com capa de plástico resistente, mecanismo retrátil, inclui 2 cápsulas surpresa que se transformam em esponjas (pato amarelo e baleia azul) Giz - 1,2 cm x 1,4 cm x 9,6 cm Cápsula - 0,7 cm x 0,7 cm x 2,1 cm Dimensões da embalagem: 1,2 cm x 14 cm x 16 cm Peso: 55 g Ficha Técnica: Vidro e superfícies lisas, evitar superfícies porosas Corpo em resinas termoplásticas, giz de cera com ceras, carga mineral inerte e pigmentos orgânicos, cápsula de gelatina e esponja Características: - Marca: Leonora - Modelo: 10224 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Giz de Cera Retrátil Para Banho C/ 2 Cápsulas de esponja surpresa color joy - blister C/ 6 cores', 19.72, 17.75, NULL, 'Stationery > Others', 'https://cf.shopee.com.br/file/sg-11134201-821e5-mggjtvbudwjw76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F50550536322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
