INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997804940', 'Kit 2 Gavetas Kappesberg Adapt Branco 33cm', 'Para quem sempre sonhou com um quarto planejado, o Modulado Adapt da Kappesberg é a escolha ideal. Produzido em MDP, material de alta qualidade, o Kit 2 gavetas 33cm é o complemento necessário para quem quer ajustar a parte interna dos roupeiros. Com corrediças telescópicas e um encaixe e montagem facilitados, ele pode ser utilizado nos módulos N531 e N534, ajustando a distribuição do espaço interno do seu roupeiro e o deixando do jeito e com o espaço que você precisa. E com pintura brilho de sete camadas na cor branco, ele combina facilmente com todos os ambientes. Renove seu quarto com toda a qualidade e beleza que o Modulado Adapt da Kappesberg oferece e aproveite cada momento. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 294.1, 259.99, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-82629-mm9cwt3j1w5c1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F20997804940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
