INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4491920402', 'Livro - 365 caça-palavras português-inglês - Capa comum - Ciranda Cultural', 'Atualize-se sobre diversos assuntos, enriqueça seu vocabulário e melhore sua memória enquanto se diverte com os incríveis 365 caça-palavras com diagramas para você encontrar palavras em português e inglês. Editora: Ciranda Cultural Edição: 1, 2020 Autor: Ciranda Cultural Idioma: Bilíngue Páginas: 288 Dimensões: L 15.50 x A 23.00 x E 1.60 ISBN: 9786555000962', 19.9, 19.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/01085bc5c7ebbbfddafe8af774743bee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F4491920402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6892643812', 'Livro - Gramática da Língua Portuguesa - Capa comum - Ciranda Cultural', 'O aprendizado da língua inicia-se quando o falante faz uso de suas primeiras palavras. O conhecimento sistematizado vem com o aprimoramento do uso e depende de muita dedicação e estudo. Este manual de estudos aborda os tópicos da gramática da Língua Portuguesa de forma prática e objetiva, proporcionando maior conscientização sobre suas características e seu funcionamento. Editora: Ciranda Cultural Edição: 2, 2020 Autor: Vera Massabki Idioma: Português Páginas: 400 Dimensões: L 12.00 x A 16.90 x E 1.90 ISBN: 9786555003451', 19.9, 13.93, NULL, 'Books & Magazines > Books > Education & School', 'https://cf.shopee.com.br/file/4c4df9566a1751c9de29a5a8e821c134', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F6892643812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998820335', 'Par de Cadeiras em Madeira Maciça Kappesberg Lola Boucle Bege (Tela Bege)', 'Resistente e robusta, a Cadeira Lola da Linha Sala de Jantar Premium da Kappesberg é ideal para quem busca por um ambiente moderno e estiloso. Entregue montada, ela é produzida em madeira de eucalipto, garantindo resistência e durabilidade, e suportando até 120kg, é perfeita para todos os momentos. Com medidas de 92,5cm de altura, sendo 50cm a altura do assento, 44,5cm de largura e 55,5cm de profundidade, para mais comodidade, a cadeira conta com assento estofado recoberto com tecido boucle bege, o que garante um toque suave e gostoso. E para completar o design e conforto, o encosto possui telinha na cor bege, que além de um diferencial único, proporciona um acabamento ideal para uma sua sala de jantar mais completa. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; A Tonalidade do produto pode variar conforme cada tecido; Este anúncio acompanha duas cadeiras em madeira maciça; O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 1827.09, 1827.09, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-mdarxby0a8n418', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F23998820335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597600904', 'Cachimbo Longo Condutor IBBL para Bebedouros GFN2000, GFQ2000 e COMPACT', 'O Cachimbo Longo Condutor IBBL, é compatível com os Bebedouros dos modelos GFN2000, GFQ2000 e COMPACT da IBBL.&nbsp; O Cachimbo Longo Condutor IBBL tem a finalidade de compor a montagem dos Bebedouros, sendo responsável por conectar o reservatório de água à torneira por onde a água purificada é dispensada. Adquira já o Cachimbo Longo IBBL para garantir um bom funcionamento dos seus Bebedouros! Meta Tag Description: Compre o Cachimbo Longo Condutor IBBL para Bebedouros GFN2000, GFQ2000 e COMPACT, com 5% de desconto no PIX e Boleto! Compatibilidade: Compatível com os Bebedouros GFN2000, GFQ2000 e COMPACT da IBBL.&nbsp; Especificações Técnicas: Marca: IBBL Modelo: Cachimbo Longo Condutor Código do Produto: 10210022 Código EAN: Dimensões: A 3,8 cm x L 2,8 cm x C 11,6 cm&nbsp; Peso: 20,8 gr Garantia: 3 meses pelo fabricante Fabricante: IBBL Informações adicionais: Itens Inclusos: 1 Cachimbo Longo Condutor', 35.0, 35.0, NULL, 'Home Appliances > Small Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5l-lwp0n19ktahvdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F770257431%2F22597600904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253827415', 'BERMUDA CICLISTA FEMININA SOUL DLK', 'A bermuda ciclista foi criada para te acompanhar com firmeza em cada passo, pedalada ou treino. Com modelagem mais alongada e compressão média, essa peça entrega segurança nos movimentos e valoriza a silhueta com caimento ajustado. O cós anatômico reforça o conforto, abraçando a cintura sem apertar, essencial para quem quer performance com bem-estar. MOTIVOS PARA AMAR - Modelagem ciclista que cobre melhor as pernas e evita atrito - Cós anatômico que modela com conforto e liberdade - Tecido de poliamida com compressão média e toque macio - Alta durabilidade e elasticidade que respeitam o corpo em movimento - Possui proteção UV INFORMAÇÕES ADICIONAIS Composição do tecido: 85% Poliamida 15% Elastano Compressão: Média Sobre a cor do produto: Pode haver variação na cor do produto final de acordo com o brilho do monitor ou tela do celular. Garantia: Contra defeito de fabricação SOBRE A MARCA - Somos uma das maiores marcas de moda fitness do Brasil. - Entregamos as melhores roupas esportivas há mais de 10 anos. - Já chegamos a mais de 5 mil cidades em todo o país. - Contamos com mais de 2,6 milhões de DLK Lovers.', 113.99, 113.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mjsjrl4l8phjec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F58253827415', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597629174', 'Kit Farol Milha Auxiliar Voyage G6 2013 2014 2015 2016 Botão Modelo Universal', 'Kit Farol De Milha Auxiliar Gol Voyage G6 2013 2014 2015 2016 Botão Modelo Universal Características: Produto novo de ótima qualidade; Lente lisa em acrílico. Especificações Técnicas: Encaixe de lêmpada H11; Suporta lêmpadas ate 55wts; Regulagem de foco manual. Conteúdo da Embalagem: 2 Faróis de milha; 2 Grades do milha; 1 Relê; 1 Chicote elétrico; 1 Botão modelo universal. Compatível com os modelos: Gol G6 2013; Gol G6 2014; Gol G6 2015; Gol G6 2016; Voyage G6 2013; Voyage G6 2014; Voyage G6 2015; Voyage G6 2016. Obs: Valor anunciado referente ao kit. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços! Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 205.56, 185.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv1ssssygs652e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1147747289%2F19597629174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597606851', 'Stain Preservativo Montana Osmocolor Transparente 900ml - 33B010100', 'Osmocolor Stain é um acabamento acetinado que protege e realça os veios e desenhos naturais da madeira. O principal diferencial do Stain é que o produto penetra nas fibras e acompanha os movimentos da madeira e por isso, não forma a película rígida dos acabamentos convencionais, que se deterioram rapidamente. Além disso o Osmocolor Stain contém em sua formulação fungicida, resinas e pigmentos que protegem a superfície da madeira contra a ação dos raios UV, fungos manchadores e emboloradores, ação hidrorrepelente que reduz o empenamento das madeiras. Utilize o acabamento Osmocolor Stain em ambientes externos ou internos, em estruturas de madeira em geral, aplainadas, lixadas ou rústicas como portas, janelas, portões, beirais, forros, estruturas de telhado, gazebos, varandas, pérgulas, móveis rústicos e de jardim, cercas, guarda-corpos, entre outros.', 92.37, 73.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-825zu-ml8f23kkz1tw75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23597606851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209244569', 'Valvula de Escoamento Para Cuba de Apoio de Banheiro Pingoo - Preto', 'A Válvula de Escoamento para Cuba de Apoio de Banheiro é sofisticada e funcional com sistema click, que permite abrir e fechar o escoamento com apenas um toque, sendo compatível com cubas sem ladrão. O design moderno é ideal para compor banheiros e áreas gourmet com elegância, enquanto o material em cerâmica e aço inox 201 é resistente à corrosão, proporcionando maior durabilidade e prolongando as características originais. Modelos compatíveis: Calcedônia, Cornalina, Crisoprásio, Fluorita, Gota, Larimar, Morganita, Coral (preto), Obsidiana Medidas: 6,7 (C) x 6,7 cm (L) x 10,4 cm (A) Cor: Preto Tipo de produto: Válvula Local de Uso: Banheiro eÁrea gourmet Material: Cerâmica e Aço inox 201 Acabamento: Fosco Forma de instalação: Encaixe Peso do produto: 0,24Kgs Conteúdo da embalagem: 1 Válvula de escoamento', 64.41, 64.41, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zul-mn63cnha4r2bb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1758065666%2F58209244569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2956742617', 'O príncipe da privataria: 9', 'Uma grande reportagem, 400 páginas, 36 capítulos, 20 anos de apuração, um repórter da velha guarda, um personagem central recheado de contradições, poderoso, ex-presidente da República, um furo jornalístico, os bastidores da imprensa. Eis o conteúdoprincipal da mais nova polêmica do mercado editorial brasileiro - ´O Príncipe da Privataria - A história secreta de como o Brasil perdeu seu patrimônio e Fernando Henrique Cardoso ganhou sua reeleição´.', 24.9, 24.9, NULL, 'Audio > Home Audio & Speakers > Home Theater Systems', 'https://cf.shopee.com.br/file/feb31524f11ff4f02777294f7ae9b68a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F2956742617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293942965', 'Ração Quatree Gourmet Cães Filhotes Mix Carnes e Leite - 3Kg', 'Ração Quatree Gourmet Cães Filhotes Mix Carnes e Leite - 3Kg - Alta palatabilidade; - Livre de corantes artificiais; - Rica em vitaminas e minerais; - Ômegas 3 e 6: pele saudável e pelagem brilhante; - Com leite em pó integral: fonte de cálcio e fósforo; - Feita com peixe, carne e frango: fontes de proteína animal para um bom desenvolvimento; - Pode ser utilizada por fêmeas a partir da sexta semana de gestação até o desmame total do filhote; - Polpa de beterraba e prebiótico: maior absorção de nutrientes, auxilia no trânsito intestinal, volume e odor de fezes reduzido. Detalhes A Ração Quatree Gourmet Cães Filhotes Mix Carnes e Leite - 3Kg é um alimento elaborado com matérias-primas nobres para fornecer uma alimentação completa e perfeito desenvolvimento do seu cão filhote. A seleção de excelentes fontes de proteína garante um crescimento forte e saudável. Reúne em sua fórmula fibras naturais: prebiótico (MOS) e polpa de beterraba, para melhorar as defesas do organismo e promover a saúde intestinal. Quatree Gourmet Filhotes é um alimento completo e saboroso, rico em vitaminas e minerais, que proporcionará uma nutrição equilibrada. Possui também leite em pó integral, fonte nutrientes importante para a fase mais importante da vida dos filhotes. Indicado também para fêmeas a partir da sexta semana de gestação até o desmame total dos filhotes. Dicas Especiais Forneça diariamente a Ração Quatree Gourmet Cães Filhotes dividida em duas porções, de acordo com o peso do animal ou conforme orientação do médico veterinário. Um copo de 250 mL equivale a aproximadamente 125g. Quantidade Recomendada Peso Estimado Miniatura Pequeno Médio Grande Gigante do Cão Adulto até 5 kg 5 a 10 kg 10 a 30 kg 30 a 40 kg Acima de 40 kg 1 a 3 meses 25 a 105 g 45 a 180 g 130 a 440 g 220 a 590 g 260 a 735 g 3 a 6 meses 40 a 142 g 60 a 240 g 175 a 475 g 350 a 695 g 475 a 800 g 6 a 12 meses 30 a 160 g 105 a 260 g 180 a 600 g 440 a 670 g 520 a 740 g 12 a 18 meses - - - - 600 a 880 g Indicação: Cachorros Porte/Raça: Grande, Médio, Pequeno Idade: Filhotes Composição: Farinha de vísceras de frango (mín. 10%), farinha de carne e ossos (mín. 8%), farinha de peixe (mín. 1,0%), milho integral moído², gordura de frango, gordura suína, óleo de soja refinado¹ (mín. 0,5%), quirera de arroz, farelo de trigo, farelo de glúten de milho-60², proteína isolada de suíno, levedura de cerveja, levedura autolisada de cana-de-açúcar, leite em pó integral (mín. 1%), polpa de beterraba (mín. 0,5%), cloreto de sódio (sal comum), extrato de yucca (mín. 0,025%), cloreto de colina, mananoligossacarídeo (MOS), hidrolisado de fígado de frango e suíno, BHT/BHA, acidificante, premix vitamínico mineral, glucanos, vitaminas (A, D3, E, B1, B2, B6, B12, K3, biotina, niacina, ácido fólico, ácido pantotênico), minerais (sulfato de cobre, sulfato de ferro, sulfato de zinco, monóxido de manganês, selenito de sódio, iodato de cálcio), minerais quelatados (manganês, selênio e zinco). Sorgo integral moído, farelo de soja¹, farelo de arroz integral, farinha de soja micronizada. Espécies doadoras do gene: Agrobacterium tumefaciens (1,2), Bacillus thuringiensis (1,2), Streptomyces viridochromogenes (1,2), Zea mays (2) e Arabidopsis thaliana (1). Apresentação: 3Kg; 10,1Kg; 15Kg; 20Kg', 70.49, 49.31, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-7rffo-m95a677kbas9bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23293942965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098471943', 'Diasin Homeopatia Homeo Pet Real H - 14g', '- Diarreia aguda em cães, gatos e animais de companhia; - Sem contraindicações; - Sem riscos a saúde em caso de superdosagem; - Ausência total de toxidez. * Consulte sempre o medico Veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes O Sistema de Terapia Real H Homeo Pet Diasin - 14 g é um Gel de uso ora, homeopático, para tratamento de diarreias agudas em cães, gatos e outros animais de companhia. Em 85% dos casos elimina o problema com apenas uma aplicação. A diarreia em cães e gatos pode estar relacionada a problemas de alimentação, verminoses e doenças infecciosas. A diarreia é um sintoma e indica que algo não esta bem no organismo de seu pet. Dicas Especiais Posologia e Modo de Usar Uso oral. Expor a parte interna da bochecha e aplicar o produto colocando o bico da seringa no espaço existente entre os dentes. Dosagem padrão - Para cães com diarreia: fornecer de 2 a 7 gramas/dose, conforme o porte do animal e o histórico do problema. Se os sintomas persistirem, repetir as doses quantas vezes for necessário. - Para gatos com diarreia: de 2 a 4 gramas/dose, conforme o porte do animal e o histórico do problema. Na maior parte dos casos se obtém os resultados esperados com doses de 12 em 12 horas, até cessarem os sintomas. A frequência e número das doses podem ser alteradas a critério do Médico Veterinário. Conforme o caso clinico pode ser necessária a utilização de medicação de suporte. Precauções Armazenar o produto em temperatura ambiente, ao abrigo do sol e calor (fogão). Manter sempre afastado de fontes de radiações eletromagnéticas (rádio, telefone, microondas, etc) bem como de produtos químicos (alvejantes, desinfetantes, etc). Contra Indicações Não existem. Em caso de dúvidas consulte um Médico Veterinário. Composição Mercurius vivus 7 CH......................................... 1,66 mL Colibacilinum 9 CH............................................. 1,66 mL Colocynthis 9 CH................................................ 1,66 mL Enterococcinum 9 CH........................................ 1,66 mL Podophyllinum peltaltum 15 CH........................ 1,66 mL Arsenicum album 6CH........................................ 1,66 mL Véiculo (Q.S.P)..................................................... 100,0 mL', 120.95, 90.88, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7qvd9-lg8xdztx5ygwf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F19098471943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594012771', 'Amortecedor Capô Duster Amortecedor Dianteiro Capô Renault Duster Pistão a Gás Capô Duster', 'O Amortecedor Besser é um dispositivo utilizado para controlar o movimento de abertura e/ou fechamento de porta-malas/capô/vidro de um veículo. Possui tecnologia alemã que utiliza um sistema de gás pressurizado, que oferece movimento suave e controlado, garantindo assim total funcionalidade, estabilidade e segurança. Com apenas três passos é possível realizar a instalação de seu AMORTECEDOR BESSER: 1º passo: Verificar a compatibilidade da peça adquirida com o MODELO e ANO do veículo, cada amortecedor possui sua singularidade, variando entre pressão e dimensão; 2º passo: Utilizando uma chave de fenda, basta folgar as travas dos encaixes da atual peça instalada no veículo. Após isso, seguir com a remoção total dos amortecedores antigos; 3º passo: Para finalizar a instalação dos amortecedores novos, basta posicioná-los no mesmo local onde as peças antigas estavam e aplicando uma pequena pressão entre ás peças e o encaixe, verifique se os mesmos estão seguros e bem fixos a aplicação. Teste: Após finalizar a instalação, basta abrir e fechar algumas vezes o porta-malas/capô/vidro do veículo para confirmar o funcionamento das novas peças. Aplicação: Renault Duster Todos Características: Cor: Preto Fixação: Por encaixe Produto: Novo Importante: O valor do anúncio é referente a unidade Acompanha Nota Fiscal Envio imediato É super importante o cuidado ao manusear as peças e ferramentas no ato da instalação. Caso surja alguma dúvida ou insegurança, é recomendável buscar ajuda de um profissional especializado em manutenção automotiva.', 78.99, 42.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfbhba4wgsg655', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1505013914%2F23594012771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398483597', 'Par Palheta Limpador Parabrisa Land Rover Freelander 10 À 18', 'Projetadas para oferecer desempenho superior em todas as condições climáticas, nossas palhetas combinam tecnologia de ponta e materiais de qualidade premium para garantir uma limpeza eficaz do seu para-brisa. Especificações: Tamanho: 24" e 16" Encaixe: U Compatibilidade: Audi A3 2007 à 2012 Audi A3 Sportback 2007 à 2012 BMW Série 3 318i, 320i, 325i, 328i 2010 à 2018 BMW X1 2010 à 2018 Land Rover Freelander II 2007 à 2018 Principais características: - Borracha de alta qualidade que proporciona uma limpeza suave e eficiente, sem deixar marcas ou riscos - Design aerodinâmico que reduz o ruído e proporciona uma operação silenciosa - Fácil instalação, compatível com uma ampla variedade de veículos Importante: Valor referente ao par Acompanha nota fiscal Garantia de 180 dias contra defeitos de fabricação Envio imediato', 49.99, 42.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rffw-m9rso2vjqs7wd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1505013914%2F22398483597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597321796', 'Intestin Homeopatia Homeo Pet Real H - 30 mL', '- Diarreias crônicas; - Seguro e benéfico; - Contém propriedades super eficazes; - Trata de dentro para fora, sem agredir o animal; - Diarreias em situações de estresse (desmame, período de vacinação, viagens). * Consulte sempre o médico Veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes O Sistema de Terapia Real H Homeo Pet Intestin - 30 mL é um produto indicado para tratar diarreias aguda e crônica de cachorros e gatos. Cura e previne, inclusive as provocadas por trocas de ração ou ingestão de alimentos caseiros. É ainda recomendada sua utilização para evitar a ocorrência de diarreias em situações de estresse, tais como: desmame, período de vacinações, viagens, etc... Dicas Especiais Administrar as doses indicadas na água do bebedouro ou sobre os alimentos (rações, leite, etc), borrifando o produto imediatamente antes de oferecer o alimento ao animal. Pode-se utilizar o produto diretamente na mucosa oral do animal, expor a parte interna da bochecha (mucosa bucal) e dirigir as borrifadas sobre ela, facilitando o contato direto do medicamento. Armazenar o produto em temperatura ambiente, ao abrigo do sol e calor (fogão). Manter sempre afastado de fontes de radiações eletromagnéticas (rádio, telefone, microondas, etc)bem como de produtos químicos (alvejantes, desinfetantes, etc). Composição Mercurius corrosivus 6 CH....................... 14,29 mL Cinchona officinalis 6 CH......................... 14,29 mL Natrum muriaticum 9 CH......................... 14,29 mL Veratrum album 6 CH............................... 14,29 mL Podophylum peltaltum 15 CH................. 14,29 mL Aethusa cynapium 6 CH ...........................14,29 mL Colocynthis 9 CH...................................... 14,29 mL Véiculo (Q.S.P).......................................... 100,0 mL', 111.21, 81.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrdoecg3udr8dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22597321796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993231727', 'Kit 2 Suplemento Vitamínico Organnact Omega 3 Dog 1000 - 30 g', '- Transporta oxigênio para o organismo; - Regula os hormônios; - Previne e controla alergias e inflamações; - Melhora o funcionamento dos órgãos vitais e articulações dos cães; - Antioxidante natural, ajuda na eliminação dos radicais livres; - Dá brilho na pelagem; - Evita queda dos pelos. * Consulte sempre o Médico Veterinário de sua confiança para o uso apropriado deste produto. Leia a bula ou informações descritas na embalagem. Detalhes O Suplemento Vitamínico Organnact Omega 3 Dog 1000 é fonte pura de ômega 3 em cápsulas gelatinosas, que facilitam a administração, não possuem odor nem sabor forte de peixe. Por muito tempo a suplementação com ômega 3 era indicada apenas para melhorar a qualidade da pele e da pelagem dos cães, mas após muitas pesquisas descobriu-se que os benefícios dessa suplementação iam muito além, sendo utilizado para a recuperação de alergias, controle da inflamação, saúde das articulações e a função de outros órgãos dos cães, melhorando a qualidade de vida e a longevidade do animal.O Ômega 3 é um ácido graxo essencial, que não pode ser sintetizado pelo organismo dos cães, dessa forma devem ser ingeridos através da dieta ou suplementação. Dicas Especiais Fornecer diariamente por via oral: Cápsulas 1000 mg: 1 a 2 cápsulas por dia para cada 20 kg de peso do cão. Pode ser colocado junto a ração seca ou oferecido diretamente ao seu pet. Cuidados: Leve seu pet ao médico veterinário de sua confiança sempre que possível, passeie ou faça exercícios com ele para que nãos e torne um pet sedentário e evite assim problemas de saúde relacionados ao sedentarismo. Ofereça sempre alimento e água fresca a ele. Não dê medicamentos por conta própria. Composição Vitamina E, B.H.T. (hidróxido de tolueno butilado), Óleo de Peixe Refinado.', 242.0, 174.99, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lz82vfc5pzc5b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22993231727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497605247', 'Armário Porta Toalha Sem Tampo Americana Henn 20cm', 'O Armário Porta Toalha Americana Henn é ideal para complementar cozinhas moduladas com praticidade e melhor aproveitamento do espaço. Com design compacto e funcional, ele é perfeito para ambientes menores, oferecendo suporte lateral para toalhas e contribuindo para uma cozinha mais organizada. Produzido em 100% MDF com acabamento em pintura UV, o móvel garante maior durabilidade, resistência e facilidade de limpeza no uso diário. Seu formato estreito de 20 cm de largura permite encaixe perfeito entre outros módulos da cozinha, mantendo o ambiente harmonioso e funcional. O modelo não acompanha tampo, permitindo que seja utilizado com tampo separado ou integrado ao projeto da cozinha conforme a necessidade. CARACTERÍSTICAS: Marca/Fabricante: Henn Modelo: Americana Material: 100% MDF Caixa: MDF 15mm Interno: MDF 15mm Fundo: MDF 3mm Suporte lateral para: Toalhas Design: Compacto e funcional Não acompanha: Tampo Tipo de acabamento: Pintura Texturizada UV DIFERENCIAIS/DETALHES: - Não inclui tampo *vendido separadamente. - Altura do balcão sem o rodapé: 67,5cm TIPO DE PÉS: - Inclui pés? Não, somente Rodapé. - Material do rodapé: MDF 15mm - Pode instalar suspenso? Sim, já acompanha kit ferragens para fixação na parede. - Pode usar sem rodapé? Sim, de forma suspensa ou se houver um sóculo ou base para apoiar o móvel. EMBALAGEM: Caixa em: 1 volume Peso total: 10,00 kg - Cuidados: Necessita de montagem, sugerida que montagem seja efetuada por um profissional. - Manutenção e limpeza: Para manter seu móvel novo por muito mais tempo, evite locais úmidos, mantenha-o distante de líquidos e de fontes de calor; - Evite a exposição prolongada ao sol; - Para limpá-lo com segurança utilize uma flanela seca sem produtos abrasivos e nem lustra móveis. Dimensões do Produto: Altura: 82 cm Largura: 20 cm Profundidade: 49,5 cm Peso: 10 kg Garantia: 3 meses ⚠️ Observações Importantes: - As imagens são meramente ilustrativas e não acompanham objetos de decoração e eletros; - Pode haver alguma diferença de tonalidade entre a imagem e o produto, por conta do tratamento de imagens e a calibração de cores da sua tela; - Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados ou imprevistos com a entrega do produto; - A Lojas MM não se responsabiliza por montagens e instalações dos produtos.', 254.9, 254.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820la-mlqltogbqtqedf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F23497605247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993963540', 'Prateleira organizadora tripla Ou Linha Keep', 'A Prateleira Organizadora garante organização e cuidado para o seu dia a dia. Possibilita o máximo aproveitamento de espaço nos armários, para uma rotina com mais tranquilidade e bem-estar. O bambu promove a sustentabilidade de um material 100% renovável, e traz sofisticação para decorar a sua casa. Seu formato vertical auxilia na otimização de espaço e a sua disposição permite a acomodação de diferentes tamanhos de louças e objetos. Eleve o nível da organização com a Linha Keep e guarde o que há de melhor em cada momento. INFORMAÇÕES TÉCNICAS Dimensões: LxAxP: 25x24x25 cm. Material: Bambu CUIDADOS Sugere-se higienizar com sabão neutro e esponja macia, evitando produtos abrasivos no processo de limpeza. CONTEÚDO DA EMBALAGEM 1 prateleira organizador tripla em bambu SOBRE NÓS Somos apaixonados pelo que fazemos e utilizamos o design como meio de fazer você se sentir em casa onde estiver. Criamos produtos com carinho e cuidado para atender as suas necessidades diárias, levando bem-estar, aconchego e conforto para seu lar. Somos minimalistas e funcionais pois queremos que você tenha um estilo de vida mais leve e organizado, para atingir o máximo do seu potencial. Prazer, somos Ou.', 149.9, 149.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rfge-m9g90m63kzhe61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1477305422%2F22993963540', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
