INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794540339', 'Top Fitness Feminino com Bojo e Elásticos Activity DLK', 'Esse top apresenta bojo removível, recorte vazado nas costas e elástico personalizado DLK, entregando sustentação e visual moderno. O equilíbrio entre respirabilidade e funcionalidade o torna perfeito para diferentes treinos. VANTAGENS - Recorte vazado nas costas que ajuda na ventilação - Elástico firme e personalizado na base para o suporte perfeito - Bojo removível que proporciona versatilidade - Tecido com toque macio, proteção UV e alta durabilidade INFORMAÇÕES ADICIONAIS Nível de compressão da peça: Médio Sobre a cor do produto: Pode haver variação na cor do produto final de acordo com o brilho do monitor ou tela do celular. Garantia: Contra defeito de fabricação MEDIDAS DA MODELO Altura: 1,64 cm Busto: 93 cm Cintura: 67 cm Quadril: 100 cm A modelo está vestindo tamanho P SOBRE A MARCA - Somos uma das maiores marcas de moda fitness do Brasil. - Entregamos as melhores roupas esportivas há mais de 8 anos. - Já chegamos a mais de 5 mil cidades em todo o país. - Contamos com mais de 2,6 milhões de DLK Lovers no Instagram.', 129.99, 129.99, NULL, 'Women Clothes > Tops > Tube Tops', 'https://cf.shopee.com.br/file/br-11134207-820lt-mq3hd5663zeq9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F23794540339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
