INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254644180', 'Blush Stick Rosa On The Go By Nah Cardoso 5g', 'O Blush Stick Rosa On The Go By Nah Cardoso entrega cor e um visual natural para rosto e boca com acabamento sequinho. Autêntico e versátil, é um blush bastão On The Go por sua fácil aplicação, uma tendência do universo da make que transforma a beleza em possibilidades ilimitadas! Quais os benefícios deste blush? Alta pigmentação e alta fixação Possibilita a construção de camadas Com acabamento sequinho, não deixa sensação de pele pegajosa Proporciona efeito luminoso natural Desliza com facilidade Fácil de esfumar Não mancha a pele Não remove a maquiagem Longa duração. A linha Nah Cardoso te convida a descobrir sua versão mais autêntica com produtos de fácil aplicação, alta performance e sensorial surpreendente. Sua beleza em movimento! Nenhum produto Quem Disse, Berenice? é Testado em animais, ou seja, este item possui selo Cruelty Free.', 64.9, 64.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-82613-mkbboje6bdoo93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1671118112%2F58254644180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
