INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41500645909', 'Livro Força | Encontrando Paz e Esperança | Katara Washington Patton', 'Livro Força Katara Washington Patton Neste devocional, Katara Washington Patton aborda temas sensíveis com profunda empatia, compartilhando suas experiências pessoais para oferecer às leitoras um espaço de acolhimento, livre de julgamentos e repleto do amor de Deus. Ideal para campanhas de saúde mental, este livro traz reflexões sinceras e fundamentadas na Bíblia sobre ansiedade, tristeza profunda e depressão, proporcionando conforto e orientação para o público feminino. Especificações do livro: Título: Força Subtítulo: Encontrando Paz e Esperança em Dias Sombrios Autor(es): Katara Washington Patton Ano de Edição: 2024 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Papel Offset Páginas: 272 Dimensões: Altura: 20,5 cm Largura: 13,5 cm Profundidade: 1,5 cm Peso: 0,300 kg ISBN: 9786553504844 Editora: Editora Pão Diário', 32.29, 32.29, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ks1w3ojby141', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41500645909', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
