INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200066439', 'INJETOR OLEO JET COOLER PARA FRONTIER 2.5 16V 2008 A 2012', 'INJETOR OLEO JET COOLER PARA FRONTIER 2.5 16V 2008 A 2012 **** PEÇA NOVA ********* GARANTIA E NOTA FISCAL ***** PRODUTO: INJETOR OLEO JET COOLER MARCA: FRONTIER CODIGO: 77944 ITENS INCLUSOS: 01 UNIDADE INJETOR OLEO JET COOLER COMPATIVEL COM: NISSAN FRONTIER 2.5 16V - 2008 A 2012 Conheça a MRA Auto Peças Fundada em 1998 na cidade de Ribeirão Preto/SP, a MRA Auto Peças consolidou-se ao longo dos anos como uma referência no setor automotivo, oferecendo qualidade, confiança e atendimento especializado. Com mais de duas décadas de experiência no mercado, somos especialistas em peças para VANS, UTILITÁRIOS, veículos importados e SUVs, atendendo com excelência tanto clientes particulares quanto oficinas e frotistas. Nossa matriz está localizada em Ribeirão Preto/SP, e contamos ainda com filiais nas cidades de Araraquara e Franca, ampliando nosso alcance e fortalecendo nosso compromisso com a agilidade na entrega e o suporte técnico qualificado. Na MRA Auto Peças, você encontra as melhores marcas, preços competitivos e um time pronto para oferecer as soluções certas para o seu veículo. MRA Auto Peças – Tradição, confiança e qualidade desde 1998. NISSAN / FRONTIER SEL 2.5 16V / 2008 / 2012 / MRA', 56.81, 56.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8259b-mgccrj2zysjuec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1223398266%2F58200066439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198816347', 'Kit 3 Biscoito Pedigree Biscrok Multi Cães Adultos 1kg', '- Indicado para cães adultos; - Deliciosos biscoitos assados e crocantes; - Com ômega 6 para pelos mais brilhantes; - Com cálcio para o fortalecimento de ossos e dentes; - Proteínas para o desenvolvimento muscular; - Vitamina e mais sabor para seu cachorro; - Sabor irresistível que seu cão vai adorar; - Momentos de carinho e conexão com o seu cachorro; PEDIGREE® acredita que os cães alimentam o que há de melhor em nós e queremos alimentar o que há de melhor neles, traduzindo qualidade em petiscos que eles vão adorar. ​Os cães precisam de amor e petiscos ajudam a dizer a eles o quanto são amados por seus donos e que são parte da família. Os petiscos podem ser usados para treinar e recompensar, são perfeitos para momentos de conexão, além de poderem ajudar a manter a saúde oral do seu cão. ​É por isso que BISCROK™ oferece biscoitos crocantes em formato de ossos, enriquecidos com cálcio e ômega 6. Ideais para treinar, recompensar e mimar seu cão a qualquer hora do dia. Fortaleça o relacionamento entre você e seu cão dando-lhe o que há de melhor! INGREDIENTES Composição básica do produto: Farinha de trigo, quirera de arroz, farinha de vísceras com ossos, canjica de milho*,gordura de ave, glúten de trigo, leite integral em pó, açúcar, cenoura desidratada, espinafre desidratado, metabissulfito de sódio, sorbato de potássio, hidrolisado de fígado de ave esuíno, BHT e corantes (amarelo tartrazina, amarelo crepúsculo, azul indigotina, vermelho ponceau 4R).* Espécies doadoras do gene: Agrobacterium tumefaciens, Bacillus thuringiensis, Streptomyces viridochromogenes, Zea mays, Sphingobium herbicidorovans, Dicossoma sp., Diabrotica firgifera, Thermoccocales spp, Bacillus substilis. Cloreto de sódio - sal comum -, fosfato bicálcico.', 95.7, 95.7, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/sg-11134201-7qvfd-lk77k1108v4n4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F18198816347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
