INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210460691', 'TINTA SPRAY TEKBOND ALUMINIO ALTA TEMPERATURA 350ML', 'Bem vindo!! Você está em uma loja especializada em soluções automotivas seguras e confiáveis. Aqui, cada detalhe é pensado para cuidar do que move você: sua família, sua segurança e seus melhores momentos na estrada. 🔥 Tinta desenvolvida com alta tecnologia, ideal para aplicações em áreas externas de objetos e superfícies metálicas expostas a altas temperaturas. Indicada para escapamentos de motos, churrasqueiras, fogões, chaminés e lareiras. Possui resistência térmica de até 600°C. 🛠️ Preparo da superfície: 1️⃣ Remova resíduos de tinta antiga, ferrugem, gordura e poeira da superfície. 2️⃣ Proteja as áreas que não serão pintadas utilizando papel, papelão ou plástico. 3️⃣ Para aplicações em metais ferrosos e não ferrosos, com ou sem oxidação, recomendamos a aplicação do SUPERCOLOR USO GERAL FUNDO PRIMER. Após a secagem, lixe com lixa d’água grão 400 para garantir melhor acabamento. 4️⃣ Aplique de 2 a 3 demãos para obter uma pintura uniforme e de excelente acabamento. Na primeira demão, aplique uma camada fina para melhor aderência das próximas aplicações. 5️⃣ Aguarde entre 4 e 9 minutos entre cada demão. ⏱️ Tempo de secagem: ✔️ Secagem ao toque: aproximadamente 30 minutos. ✔️ Para manuseio da peça: aguarde cerca de 3 horas. ✔️ Cura total: 24 horas. 🔧 Para testes mecânicos, recomenda-se aguardar 72 horas. 📏 Rendimento aproximado: De 1,1 m² a 1,3 m² por embalagem. Adquira agora a Tinta Spray Aerossol Alta Temperatura Tekbond Aluminio 350ml/250g em uma de nossas Lojas Oficiais: Camillo Parts, Genuine Automotive ou Edumac Parts, e tenha a certeza de estar comprando um produto de alta qualidade, com a garantia e o suporte que você merece. Proibimos o uso, cópia ou alteração de nossas fotos, imagens e conteúdo presentes nos anúncios. Conforme a Lei 9.610/98, qualquer violação será tratada legalmente, pois possuímos direitos autorais sobre este material.', 45.9, 35.35, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-820ls-mo41q9xa3itk4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1237026799%2F58210460691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692859952', 'KIT 50~250 LAÇO FÁCIL PREMIUM ORGANZA HOLOGRÁFICO 39 CM X 1,8 CM CORES//', 'DEIXE SEUS PRESENTES E EMBALAGENS AINDA MAIS ESPECIAIS COM ESTE KIT DE LAÇOS FÁCEIS PREMIUM EM ORGANZA HOLOGRÁFICA! 😍 COM UM BRILHO IRIDESCENTE E FÁCIL DE MONTAR, SÃO PERFEITOS PARA DAR UM TOQUE DE ELEGÂNCIA E CHARME. IDEAIS PARA FESTAS, LEMBRANCINHAS E PRESENTES EM GERAL! 🎉🎁 TAMANHO OU CAPACIDADE 39 CM X 1,8 CM 📏 MATERIAL ORGANZA HOLOGRÁFICA PREMIUM ✨ CORES: VARIEDADE DE CORES (CONSULTE AS OPÇÕES DISPONÍVEIS) 🎨 ATENÇÃO: QUANTIDADE: VARIAÇÃO DE 50 A 250 UNIDADES (SELECIONE A DESEJADA). 🔢 NÚCLEOS: DISPONÍVEIS EM DIVERSAS NÚCLEOS (VERIFIQUE A SELEÇÃO). 🌈 NÃO ACOMPANHA O PRESENTE (OU O PRODUTO ALEATÓRIO QUE ESTIVER NA FOTO) ⚠️ NÃO PERSONALIZAMOS 🚫✍️ CONFIRA O PRAZO DE ENVIO NO ATO DA COMPRA. 🚚💨 A COR PODE VARIAR DE ACORDO COM O MONITOR. 🎨🖥️ CONFIRA TODA A NOSSA LINHA DE PRODUTOS CLICANDO EM "VER MAIS PRODUTO DESSE VENDEDOR" 😉🛍️', 30.95, 30.95, NULL, 'Stationery > Gift & Wrapping > Ribbons', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsbffdcgrodg44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23692859952', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
