INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797688458', 'Cadeira de Barbeiro Dompel Square Black Reclinável Com Apoio e Encosto Preto', 'A Cadeira para Salão Square Black Reclinável da Dompel combina perfeitamente design, praticidade e conforto. Com uma estrutura resistente e confortável, a cadeira Square Black possui estofamento construído em espumas laminadas de alta densidade e sua estrutura de aço tubular é resistente e duradouro. Sua base pentapé antiderrapante, proporciona maior aderência e estabilidade. Além disso, conta com sistema hidráulico, garantindo precisão durante a regulagem de altura e freio. Aproveite a qualidade Dompel para seu Salão de Beleza e Barbearia! Especificações: - Comprimento: Mínimo 85 cm / Máximo 108,5 cm - Largura: 66 cm - Altura (Chão até Apoio de Cabeça): Mínima 104,5 cm / Máxima 130,5 cm - Altura (Chão até Assento): Mínima 55,5 cm / Máxima 70 cm - Ângulo de Reclínio: 30 - Encosto: Apoio de cabeça com regulagem de altura, sistema reclinável a gás com acionamento por alavanca lateral de aço cromado - Apoio de Braços: Construída em aço, revestida com polímero de alta resistência, conferindo design elegante e diferenciado - Apoio de Pés: Estrutura em aço tubular preto, amplo e confortável - Base: Pentapé pintada, antiderrapante, proporcionando maior aderência e estabilidade, sistema hidráulico com regulagem de altura e freio - Estrutura: Aço tubular, proporcionando maior durabilidade - Acabamento: Acabamento preto, combinando materiais plásticos, estofados e metais - Estofamento: Feito com espumas laminadas de alta densidade e design moderno - Capacidade de Peso Máximo: 170 kg - Cor: Preto Plus - As configurações do seu monitor ou dispositivo móvel podem afetar a tonalidade da cor do produto. Conferir na descrição. - Recomendação de Limpeza: Limpar com pano seco para retirar o pó. Não aplicar produtos abrasivos. - Produtos de Enfeite e Eletrônicos Não Estão Inclusos.', 2519.88, 1829.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-lyiqwhdbouvu30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F23797688458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
