INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3016994805', 'Fita Led Dual Color Drl Shocklight Farol Dianteiro 75cm', 'Descrição Fita LED DRL Dual Color Branca e Amarela - Shocklight: A Shocklight está lançando no mercado nacional a linha de Fita Dual Color disponível em quatros tamanhos: 30cm, 45cm, 60cm e 75cm. A fita permite a instalação com flexibilidade no farol do carro, conta com luzes de LED com duas cores e é à prova d''água podendo ser cortada e instalada do jeito que desejar! Especificação Técnica: - Código: SL-DC75 - Tamanho: 75cm - Funcionamento: Possue 2 Estágios de Cor de Luz na Mesma Barra - 1º Estágio: Luz Branca Fixa DRL (Luz Diurna) - 2º Estágio: Acionando a Seta, Pisca na Cor Âmbar - Possibilidade de Reduzir o Tamanho para Ajuste de Acabamento - Vida Útil de 30000 Horas - Cor: Branca 6000K / Amarela 3000K - LED: 335 - Quantidade de LEDs: 195 - Lúmens: 3120LM - Volts: 12V - Watts: 6.8W - Composição: Barra de Silicone, LEDs, Plástico PP, Fio de Cobre e Componentes Eletrônicos Conteúdo da Embalagem: - 02 Fitas Flexíveis de LEDs Importante: Garantia de 12 meses. A Auto Equip recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 129.9, 129.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-22120-2re69dnlkolv5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402093902%2F3016994805', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
