INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598131305', 'Jogo De Chaves Torx Hexalobular Aço Cromo Vanádio Cabo Reto T10 A T40 Ponta Magnetizada 6 Peças Vonder', 'Kit 6 Chaves Hexalobular Cabo Reto T10 T15 T20 T25 T30 T40 Vonder As Chaves Hexalobular Vonder são ferramentas essenciais para quem busca qualidade e precisão em suas aplicações. Possuem cabo com formato reto e material que garante conforto e segurança durante o uso, reduzindo o esforço e proporcionando um melhor controle da ferramenta. Ideais para o aperto e desaperto de parafusos, oferecendo alto desempenho e resistência. Características: > Cabo anatômico em polipropileno que oferece maior conforto no manuseio; > Produzida em aço cromo vanádio, proporcionando maior resistência e durabilidade; > Possui acabamento cromado fosco que oferece maior proteção contra a oxidação/corrosão; > Ponta magnetizada e com furo guia que facilita tanto a colocação quanto a retirada de parafusos em locais de difícil acesso. Especificações Técnicas: > Material do cabo: polipropileno; > Material da haste: aço cromo vanádio; > Acabamento da haste: cromado fosco. > O kit acompanha: - 1 chave T10 de 195mm de comprimento; - 1 chave T15 de 195mm de comprimento; - 1 chave T20 de 195mm de comprimento; - 1 chave T25 de 205mm de comprimento; - 1 chave T30 de 205mm de comprimento; - 1 chave T40 de 265mm de comprimento. - Marca: Vonder - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 80.54, 60.17, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rff5-m97ga6jml8lc87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F20598131305', NULL, NULL,