INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29542466130', 'Kit Controle Longa Distancia JFA K600 600 metros Modo Memória 10 peças', 'O Controle K600 da JFA tem um dos melhores alcances em área aberta do mercado, o que faz toda a diferença durante os eventos de som automotivo, quando vários controles são usados simultaneamente. - Alcance de até 600 metros em área aberta; - Teclas de silicone com alta resistência, gravadas em baixo relevo; - Design e ergonomia que facilitam o uso; - 03 combinações de cores; - Memória com mais de 220 aparelhos já cadastrados para áudio e vídeo. ESTE KIT É REFERENTE A : - 10 CONTROLES JFA K600 - 10 CENTRAIS DE CONTROLE - 10 CORDÕES CORES DISPONÍVEIS: - Branco com Tecla Cinza - Preto com Tecla Verde - Preto com Tecla Laranja', 799.99, 609.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf9v6tbyd0xy27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F29542466130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098955934', 'Shampoo Tresemmé Reconstrução e Força 650ml', '•O Shampoo TRESemmé Reconstrução e Força possui fórmula enriquecida com colágeno e arginina e atua em todas as camadas dos fios, revitalizando-os e recuperando sua vitalidade e toque macio •Cabelos mais fortalecidos com menos quebras desde o primeiro uso •Esse shampoo possui ativos reparadores para uma reconstrução e proteção máxima antiquebra •Shampoo de reconstrução capilar que reduz a quebra dos fios em até 99% menos quebra desde o 1º uso* •Ação intracelular que promove a restauração desde as camadas mais profundas dos fios para cabelos mais fortes •O Shampoo TRESemmé Reconstrução e Força é aprovado por 9 em cada 10 cabeleireiros Tenha cabelos mais fortalecidos e com menos quebras desde o primeiro uso! Conheça a linha TRESemmé Reconstrução e Força que reduz a quebra dos fios em até 99% desde o primeiro uso*. Com a avançada tecnologia de ação intracelular, seus cabelos ficarão visivelmente mais fortes e saudáveis. O shampoo TRESemmé Reconstrução e Força possui ação intracelular com colágeno e arginina que restaura desde as camadas mais profundas para um cabelo mais forte e reduz a quebra dos fios em até 99% desde o primeiro uso para uma reconstrução e proteção máxima antiquebra. A linha TRESemmé Reconstrução e Força oferece: 1. Reduz a quebra dos fios: Com uma fórmula exclusiva especialmente desenvolvida para fortalecer os cabelos, e diminuindo até 99% da quebra desde o primeiro uso*. Tenha fios mais resistentes e menos propensos a danos; 2. Ação intracelular: Com uma tecnologia de ação intracelular única, consegue penetrar profundamente nos fios, nutrindo e fortalecendo-os desde o interior; 3.Cabelos mais fortes desde o primeiro uso: Com a fórmula enriquecida com proteína, colágeno e aminoácidos, potencializa a ação do tratamento, proporcionando um fortalecimento intensivo aos fios. TRESemmé, a marca aprovada por 9 em cada 10 cabeleireiros**. *Teste instrumental vs shampoo sem agentes condicionantes. Com o uso da linha completa. **Pesquisa realizada com profissionais de salão de beleza no Brasil.', 55.59, 45.22, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7repg-m1ybdxnuieg08c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F18098955934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
