INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257439583', 'Comando Bravo Cg 150 Titan Bravo 310° Ww3 Competição', 'ARVORE COMANDO WW3 RACING Nº2 LEVANTE ALTO 6.5mm , 310° GRAUS Nº2 310 Graus. Elevante de 6.50mm. Compatível com: Cg 150 2004 Diante - Bros 150 2006 Diante - Cg 125 2009 Diante - Bros 125 2013 Diante - Fan 150 Maior enchimento do cilindro. Maior duraço na abertura das válvulas. Melhora em todas faixas de rotaço. Maior arrancada. Retomadas mais rápidas. Melhor velocidade final. Feito com material de 1ª qualidade. Ótima durabilidade.', 111.99, 111.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-820lm-mm6dkrif1wxzda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545730812%2F58257439583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16285116411', 'Capacete Aberto Joy23 By Taurus Bege Fosco com Viseira Acoplada Urbano', 'O capacete Joy23 By Taurus é um capacete aberto bege fosco com viseira acoplada. Sua fabricação é artesanal e seu design exclusivo, com casco leve e compacto. Informações Técnicas: - Selo de aprovação NBR7471 do Inmetro; - Casco injetado em ABS natural; - Fecho micrométrico com puxador; - Jugular com capa para melhor conforto e dois pontos de fixação; - Viseira injetada cristal 2mm em policarbonato de alta resistência, com sistema de troca rápida; - Design alongado permite uma área maior de cobertura do rosto; - Maior apoio e conforto para o pescoço em espuma; - Forração em tecido confortável, com tratamento antibacteriano; - Acabamento em couro das bochechas, removível e lavável; - Perfil de vedação que minimiza a entrada de água da chuva. Acerte no Tamanho! Para escolher o tamanho ideal do seu capacete utilize uma fita métrica para medir a circunferência da cabeça, passando na horizontal um dedo acima da sobrancelha e acima das orelhas, a fita métrica deve estar confortável na cabeça, sem apertar demais. É importante escolher um capacete bem justo, pois a tendência é que ele se alargue com o uso. Portanto, se a sua medida, por exemplo, é 56 ou 57 cm, escolha um 56 sem medo. A sensação de desconforto no início é normal, mas logo ele tomará a forma da sua cabeça e ficará mais confortável.', 274.61, 274.61, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nre1ktem824b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F789664648%2F16285116411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599549622', 'Banqueta Plástica Dobrável Azul 220 Mm Encosto Vonder', 'Banqueta plástica dobrável, azul, altura 220 mm, com encosto, VONDER Antiderrapante, dobrável, com alça para transporte (fechada) e encosto. Prática, leve e fácil de transportar, é ideal para camping, pescarias, passeios, uso doméstico, entre outros. Especificações: Material da banqueta: Polipropileno Capacidade de carga: 150 kgf Dimensões (fechada): Comprimento: 320 mm x Largura: 65 mm x Altura: 428 mm Dimensões (montada): Comprimento: 320 mm x Largura: 250 mm x Altura: 220 mm (Altura com encosto: 428 mm) Cor da banqueta: Azul Massa aproximada (peso) (kg): 1,48 kg Conteúdo da Embalagem: 1 Banqueta dobrável.', 85.68, 64.36, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m288p73ozkg6f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F18599549622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16793187014', 'Caneca 3D Homem-Aranha - Marvel', 'Caneca 3D Homem-Aranha ? Marvel depois de um dia salvando o mundo, você precisa de uma mãozinha para derrotar a sede? A gente te ajuda! Com essa caneca você derrota e mantém longe todos os sintomas de desidratação do seu corpo! Não importa qual é a sua aventura, essa caneca te acompanha em todos os lugares! O produto é feito em território nacional, feita em porcelana possui detalhes incríveis que vão fazer você se apaixonar! Com 400ml de capacidade para te ajudar a derrotar os sintomas da sede e salvar o mundo! Não importa se você é um super-herói ou não, com essa caneca o dia esta á salvo! Altura: 10cm| Largura: 14cm| Profundidade: 13cm | Peso: 355gr| Capacidade: 400ml| Material: Porcelana Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de cerâmica.', 99.9, 99.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-824iq-mpe0zyhhvnyjc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F16793187014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693047989', 'Shampoo 5 em 1 para Cães e Gatos 700ml - Pet Clean', 'Shampoo Pet Clean 5 em 1 para Cães e Gatos - 700ml - Contém 5 ativos, shampoo, condicionador, hidratante, revitalizador e nutrição; - Promove maciez e brilho; - Ph neutro e balanceado, torna o shampoo seguro a saúde do seu pet; - Possui película hidratante que dá proteção a pelagem por muito mais tempo. Detalhes O Shampoo Pet Clean 5 em 1 para Cães e Gatos é indicado para cachorros e gatos de todas as idades, raças, cores e comprimento de pelos. Desenvolvido para fazer a limpeza nos pelos e proporcionar uma maior maciez e brilho na pelagem do animal. Com uma formulação especial, forma uma película hidratante na pelagem do animal que o protege por muito mais tempo, pois contém silicone. Seu amiguinho ficará com o visual renovado, pronto para arrasar mais ainda por onde passar. Dicas Especiais O Shampoo 5 em 1 é indicado para cachorros e gatos a partir dos 3 meses de idade. No momento do banho é necessário alguns cuidados: não esqueça de colocar algodão nos ouvidos para evitar entrar água. Ideal dê banho, quinzenalmente, escolha sempre um dia ensolarado e use água morna. Lembre-se que cachorros de pelagem longa requerem maiores cuidados como a tosa frequente. Indicação: Cachorros, Gatos Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Composição: A cada 100 mL: Lauril éter sufato de sódio ....................25 mL Betaína ...................................................4 mL Óleo de amendoas .................................1 mL Extratos naturais .....................................1 mL Silicone ....................................................0,50 mL Agente condicionante .............................1 mL Metilparabeno ..........................................0,10 mL Fragrância .................................................0,20 mL Veículo Q.s.P .............................................100 mL. Apresentação: 700 mL', 19.84, 12.8, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi20p4hb80lde8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22693047989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10239116966', 'COLECAO FABULAS - ASSEMBLEIA DOS RATOS', 'Conheça essa linda coleção fábulas, baseado na obra de Esopo, em uma assembleia, os ratos decidiram tomar uma atitude para não mais virarem comida de gato. Entre as muitas ideias propostas, uma delas foi aprovada por unanimidade: colocar no pescoço do felino um pequeno sino, que serviria para alertar toda a rataria. Mas só faltava um detalhe... O que será que é? Conheça essa linda fábula, e descubra o que aprender com essa história. Mais 5 títulos disponíveis', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvdc-liwbzgk984qod6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F10239116966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499320050', 'Kit 20 Antibiótico Coveli em Creme Neodexa - 15 g', '- Indicado para cães e gatos; - Ação de: Antifúngico, Anti-inflamatório, Antialérgico, Anestésico e Antipruriginoso. * Consulte sempre o médico veterinário de sua confiança para o uso apropriado deste medicamento. Leia a bula ou informações descritas na embalagem. Detalhes O Antibiótico Coveli em Creme Neodexa é um tratamento de afecções dermatológicas que pode ser utilizado em cães e gatos. Conta com maior absorção e não mancha o pelo do pet, tem ação de 6 medicamentos em um só: antialérgico, antibiótico, antifúngico, anestésico, anti-inflamatório, antipruriginoso; além de ser bom para tratamento de Malassézia sp. Dicas Especiais Neodexa F Creme é indicado para caninos, felinos e eqüinos em toda a lesão de pele infectada ou não. Lesões pruriginosas onde é necessário eliminar a coceira e a dor local. Em todas as dermatites, que não sejam viróticas nem tuberculosas, em tinhas. No eczema de origem conhecida ou criptogênico. Neodexa F Creme é um potente produto antibiótico, antifúngico, anti inflamatório e anti alérgico Composição Cada 100 g contém: Neomicina (sulfato)...................................0,25 g Nistatina...................................................... 10.000.000 unid. Dexametasona (fosfato de sódio)...........0,025 g Benzocaína...................................................1,0 g', 1205.09, 742.99, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mikju6t4cphdf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F18499320050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44069423598', 'Caixa 12 Sachê Special Dog Ultralife Raças Pequenas Sabor Carne - 100g', 'Special Dog Ultralife Sachê Adultos Sabor Carne – 100g Sachê Special Dog Carne para Cães Adultos é um alimento úmido completo e balanceado, feito com pedaços de carne cozidos a vapor e batata‑doce. Enriquecido com minerais que auxiliam na absorção de nutrientes, ômegas e compostos funcionais para manter pele, pelagem e articulações saudáveis. Destaques Principais - Sem corantes nem aromatizantes artificiais - Ômegas 3 e 6 + zinco orgânico: pele protegida e pelos mais bonitos - Condroitina + glicosamina: proteção articular Análise Nutricional Garantida (por kg) Proteína Bruta: mín. 80 g Gordura (Extrato Etéreo): mín. 30 g Umidade: máx. 820 g Energia Metabolizável: 740 kcal Ingredientes Selecionados Carne de bovino, carcaça de aves, miúdos de suíno, plasma sanguíneo desidratado, sulfato de glicosamina, sulfato de condroitina, biomassa de microalgas e mix de vitaminas e minerais essenciais. Perfeito como única fonte de alimento ou misturado à ração seca, garantindo sabor e nutrição em cada sachê.', 49.98, 37.49, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjydn9prhukjf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F44069423598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
