INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204342362', 'Sabonete Líquido Fisiogel Terapia de Hidratação Diária 400ml', 'Sabonete líquido para peles secas e sensíveis. Fisiogel Terapia de Hidratação Diária promove limpeza hidratante para o corpo e o rosto, com suavidade e alívio para a sensação de repuxamento causado pelo ressecamento da pele. O Sabonete Líquido Fisiogel Terapia de Hidratação Diária apresenta fórmula hipoalergênica sem sabão, para maior hidratação e suavização da pele. Sua ação ajuda a proteger o corpo do desconforto da falta de umectação e elasticidade diariamente. Não contém fragrância, corantes e conservantes. Benefícios de Sabonete Líquido Fisiogel: ▸ Sabonete líquido para peles secas e sensíveis.▸ Limpa suavemente sem agredir a barreira natural da pele.▸ Promove hidratação e conforto imediato.▸ Alivia a sensação de repuxamento.▸ Indicado para corpo e rosto.▸ Fórmula hipoalergênica e sem sabão.▸ Livre de fragrância, corantes e conservantes.▸ Mantém a pele macia e com elasticidade por mais tempo. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 111.9, 111.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mk2ytklv3kzsc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204342362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
