INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298157022', 'Lima Rotativa Para Ferro Abaulada 04x13mm C0413M03 TNT', 'Lima Rotativa Ponta Abaulada com Duplo Corte TNT Diâmetro da Lima: 04mm Comprimento S/Haste: 13mm Utilização: Metal, Ferro, Madeira Muito afiada, agressiva, resistente, bem balanceada e durável, perfeita para espaços apertados, superando os discos de lixar. O corte duplo oferece um acabamento mais fino que o corte único e reduz o tamanho dos cavacos e lascas. Também proporciona maior controle da ferramenta. Confortável, fácil de controlar, operando com vibrações reduzidas e menos ruído. Cortes muito limpos com mínimo esforço.', 29.9, 29.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m50jdocjaq8g79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064710210%2F22298157022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397735603', 'Lâmpada Super Branca Nxr 150 Bros Es Mix 2010-2013 M5', '## Ilumine Seu Caminho com a Lâmpada Super Branca Nxr 150 Bros Es Mix! Está cansado da iluminação fraca da sua moto? Procurando por mais segurança e visibilidade nas suas viagens? As lâmpadas são um componente crucial para a segurança, especialmente para motociclistas. Uma boa iluminação garante que você seja visto e que veja o caminho com clareza, independentemente das condições climáticas ou do horário. Por que escolher a Lâmpada Gauss? A Gauss é sinônimo de qualidade e inovação no mercado automotivo. Com a Lâmpada Super Branca Nxr 150 Bros Es Mix, você garante uma iluminação superior, com luz mais branca e intensa, que aumenta significativamente sua visibilidade e a dos outros motoristas. Dirija com mais confiança e segurança! Aplicação / Compatibilidade: Esta lâmpada é perfeita para: Motos: Universal (1960 - 2025) Não perca tempo! Invista na sua segurança e garanta uma pilotagem mais tranquila e protegida. Adquira agora mesmo a sua Lâmpada Super Branca Nxr 150 Bros Es Mix e experimente a diferença!', 32.99, 32.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5ksyb910m11f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F19397735603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198384900', 'Triciclo Infantil Com Haste Removível Toy Azul Urban Baby', 'O Triciclo Infantil Com Haste Removível Toy Urban Baby é perfeito para crianças de até 4 anos. Com máxima segurança, assento ajustável e barra de segurança, garante a proteção necessária durante o passeio. Além disso, possui Guia que gira a roda dianteira e cesto porta-objetos para maior comodidade. Seu design moderno e atraente colorido vai encantar os pequenos, tornando o passeio ainda mais divertido. Com materiais de alta qualidade e resistência, como a Haste Articulada Removível em Aço Carbono, garante durabilidade e segurança. Com rodas de plástico e peso suportado de até 30 kg, é ideal para acompanhar o crescimento da criança. Com 45 cm de largura e 70 cm de comprimento, oferece conforto e praticidade para os pais. A alça removível facilita o transporte e armazenamento do triciclo. Com o Triciclo Infantil Velotrol Com Guia e Haste Removível Até 30kg Toy Urban Baby, os momentos de diversão e aprendizado estão garantidos para os pequenos exploradores. Garantia do vendedor: 90 dias Garantia do vendedor: 90 dias Certificado Inmetro: 011652/2023 Indicado 01- 03 anos Passeio: +12 meses Com Pedal: +24 meses Precisa de Bateria? Sim, 03 pilhas AA Acompanha Bateria? Não. Marca: Urban Baby', 439.9, 285.0, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd5j-m7w8hnmn5acn37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F740995429%2F22198384900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
