INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794139598', 'Vestido Aquarela Curto Infantil Feminino Lilica Ripilica', 'As aquarelas em tons naturais e sutis junto com a estampa floral trazem toda a delicadeza que o Vestido Lilica Ripilica pede! Confeccionado em Tecido popeline para um visual mais leve, suas alças com reguladores garantem frescor para a estação e seus detalhes em babados e franzidos dão um charme a mais para o visual. Além disso, conta com elástico nas costas, oferecendo maior conforto para as meninas. Aposte nessa tendência! • Vestido • Possui alças com reguladores • Estampa floral e em aquarela • Detalhe em babados e franzidos • Tecido popeline', 399.0, 199.5, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-7ravk-mavjkmxtpnc267', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F22794139598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9011884730', 'Onde mora o coração - Jill Shalvis', 'Na adolescência, ele partiu seu coração. Agora, ele a faz vê-lo de modo diferente. Será uma segunda chance? Uma gata maluca vai reaproximar uma garota de seu crush da escola. Mas ela não parece feliz com o reencontro... Pensa que ainda o odeia. O fato de Keane não se lembrar dela torna tudo mais irritante. Agora adultos, ele também deixou de investir em relações, pois não acredita ser capaz de se apaixonar ou encontrar a pessoa certa. Prepare-se para rir e se emocionar como o novo livro de Jill Shalvis! Em meio a amigos e filhotinhos de seu pet shop, Willa Davis leva uma vida de enorme realização profissional. Mas falta algo: a seção de sua vida “relacionamentos amorosos” anda paralisada. E nada parece estar a caminho para mudar esse destino. Keane também anda desiludido depois de muitos desencontros. Mas após receber a tarefa de cuidar da temperamental gata de sua tia-avó, ele procura uma especialista no assunto, e o destino joga suas cartas. Ele não faz a mínima ideia de quem seja a proprietária da loja de animais, mas Willa sabe exatamente quem ele é... Alguém que no passado já partiu seu coração. E nada é fácil quando se trata de duas pessoas que se fecharam para o amor. Os amigos entram em ação. Mas tão diferentes? Tão improváveis? Será que Keane mudou? Será que Willa é capaz de perdoar? Esta é uma história divertida sobre quais escolhas valem a pena e sobre como podemos evitar o olhar viciado que sabota as oportunidades... e, também, sobre aceitar a sorte quando ela aparece. Detalhes do produto Capa comum: 304 páginas Editora: Faro Editorial; Edição: 1 (13 de agosto de 2019) Idioma: Português ISBN-10: 8595810761 ISBN-13: 978-8595810761 Dimensões do produto: 22,6 x 15,4 x 2 cm Peso de envio: 522 g', 67.4, 67.4, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/a008dfd8973611e094d232547a5c9d29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F9011884730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40669258680', 'Magnésio Plus Suplemento Alimentar 90 Cápsulas de 690MG Vitafor', 'O magnésio auxilia: na formação de ossos e dentes; no metabolismo energético; no metabolismo de proteínas, carboidratos e gorduras; no equilíbrio dos eletrólitos.; no funcionamento muscular; no funcionamento neuromuscular; no processo de divisão celular. A vitamina B6 auxilia: na formação das células vermelhas do sangue; no funcionamento do sistema imune; no metabolismo energético; no metabolismo de proteínas e do glicogênio; no metabolismo de proteínas, carboidratos e gorduras; no metabolismo de homocisteína; na síntese de cisteína. Diferenciais: 350 mg de bisglicinato de magnésio por porção; Fonte de vitamina B6; Vegano; Alta concentração e biodisponibilidade; Zero açúcar e glúten. Recomendação de uso: Suplemento alimentar de uso adulto e infantil (a partir de 9 anos de idade): ingerir 2,46 g (3 cápsulas) ao dia ou seguir a recomendação de um profissional da saúde Dados científicos: A suplementação de magnésio pode proporcionar diversos benefícios para o organismo: ajuda a reduzir a frequência e a intensidade das cãibras nas pernas¹, melhora o desempenho físico ao aumentar a disponibilidade de glicose no cérebro, nos músculos e no sangue², além de combater o estresse oxidativo, protegendo as células contra os danos causados pelos radicais livres³. Com o MAGNÉSIO PLUS você encara a rotina com mais leveza, disposição e energia!', 129.9, 109.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meq54i74tce8a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F40669258680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
